window.NGU_PHAP_TAB = window.NGU_PHAP_TAB || {};
window.NGU_PHAP_TAB["/lessons/bai-1.html"] = [{"so":"1.1","ten":"助动词“要”","tenVn":"Trợ động từ “要”","cauTruc":["Sub + 要 + V (+ O)","Phủ định: Sub + 不想 / 不要 + V (+ O)","Nghi vấn: Sub + 要 + V (+ O) + 吗？"],"giaiThich":"“要” là trợ động từ (năng nguyện động từ), luôn đứng trước động từ chính để diễn đạt ý \"muốn, định, sẽ làm gì\", nhấn mạnh ý chí và kế hoạch của người nói. Khác với “想” (nghiêng về mong muốn, ước ao trong lòng), “要” mang sắc thái quyết tâm cao hơn, việc đã được tính toán và gần như chắc chắn sẽ xảy ra: 我想去北京 (tôi muốn đi Bắc Kinh — mới chỉ ước ao) / 我要去北京 (tôi sẽ đi Bắc Kinh — đã quyết). Điểm học sinh Việt phải nhớ kỹ: phủ định của “要” khi mang nghĩa \"muốn\" là “不想”, chứ không phải “不要”; “不要” chỉ dùng khi khuyên ngăn, cấm đoán ai đó, tương đương \"đừng\" trong tiếng Việt. Vì “要” đã là trợ động từ nên trước nó không thêm phó từ mức độ “很”, muốn nói \"rất muốn\" phải nói “很想”.","viDu":[{"zh":"我要去北京旅游。","py":"Wǒ yào qù Běijīng lǚyóu.","vn":"Tôi sẽ (muốn) đi Bắc Kinh du lịch."},{"zh":"明天我要去火车站。","py":"Míngtiān wǒ yào qù huǒchēzhàn.","vn":"Ngày mai tôi phải đi ra ga tàu."},{"zh":"你要喝牛奶吗？","py":"Nǐ yào hē niúnǎi ma?","vn":"Bạn có muốn uống sữa không?"},{"zh":"我很累，今天不想运动。","py":"Wǒ hěn lèi, jīntiān bù xiǎng yùndòng.","vn":"Tôi mệt lắm, hôm nay không muốn vận động."},{"zh":"你生病了，不要喝咖啡。","py":"Nǐ shēngbìng le, bú yào hē kāfēi.","vn":"Bạn ốm rồi, đừng uống cà phê."}],"loi":[{"sai":"我很要去北京。","why":"học sinh dịch máy móc \"rất muốn\" trong tiếng Việt, thêm “很” vào trước trợ động từ “要”.","dung":"我很想去北京。"},{"sai":"我不要去北京旅游。(khi muốn nói \"tôi không muốn đi\")","why":"tiếng Việt phủ định thẳng \"không muốn\", học sinh ghép “不” + “要”, nhưng “不要” trong tiếng Hán lại có nghĩa \"đừng\".","dung":"我不想去北京旅游。"},{"sai":"我要旅游北京。","why":"tiếng Việt nói \"du lịch Bắc Kinh\", học sinh coi “旅游” là ngoại động từ mang tân ngữ.","dung":"我要去北京旅游。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["明天我","去火车站，你去吗？"],"dap":[["要"]]},{"kieu":"dien","phan":["我身体不舒服，今天","去公司。"],"dap":[["不想"]]},{"kieu":"dien","phan":["你","喝牛奶还是","喝水？"],"dap":[["要"],["要"]]},{"kieu":"dien","phan":["你生病了,","吃羊肉。"],"dap":[["不要"]]},{"kieu":"dien","phan":["他","去北京，他想去上海。"],"dap":[["不想"]]},{"kieu":"dien","phan":["我们","几点开始？"],"dap":[["要"]]}],"huongDan":"Chọn: 要 / 不想 / 不要","chon":["要","不想","不要"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["北京","我","去","要","旅游"],"dap":["我要去北京旅游。"]},{"kieu":"xep","manh":["吗","你","打篮球","要"],"dap":["你要打篮球吗？"]},{"kieu":"xep","manh":["不想","今天","我","运动"],"dap":["今天我不想运动。","我今天不想运动。"]},{"kieu":"xep","manh":["妈妈","鸡蛋","买","要","和","牛奶"],"dap":["妈妈要买鸡蛋和牛奶。","妈妈要买牛奶和鸡蛋。"]},{"kieu":"xep","manh":["九月","我们","去","要","旅游"],"dap":["九月我们要去旅游。","我们九月要去旅游。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你要去哪儿？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我要去火车站。"],"goiY":"tôi phải ra ga tàu"},{"kieu":"hoi","dong":[{"ai":"A","t":"明天我们去游泳，好吗？"},{"ai":"B","o":true,"truoc":"对不起,","sau":""}],"dap":["对不起，明天我要去公司。"],"goiY":"ngày mai tôi phải đi công ty"},{"kieu":"dich","vn":"Tháng chín tôi muốn đi Bắc Kinh du lịch.","dap":["九月我要去北京旅游。","我九月要去北京旅游。","九月我想去北京旅游。","我九月想去北京旅游。"]},{"kieu":"dich","vn":"Con ốm rồi, đừng đi đá bóng.","dap":["你生病了，不要去踢足球。","你生病了，别去踢足球。","你生病了，不要踢足球。","你生病了，别踢足球。"]}]}]},{"so":"1.2","ten":"程度副词“最”","tenVn":"Phó từ chỉ mức độ “最”","cauTruc":["Sub + 最 + Adj","Sub + 最 + 喜欢 / 想 / 爱 + O","V + O + 最 + Adj (九月去北京旅游最好)"],"giaiThich":"“最” là phó từ chỉ mức độ cao nhất, tương đương \"nhất\" trong tiếng Việt, dùng để so sánh ngầm một sự vật với tất cả những cái còn lại trong phạm vi đang nói. Về vị trí, “最” luôn đứng TRƯỚC tính từ hoặc động từ tâm lý (喜欢、想、爱), khác hẳn tiếng Việt đặt \"nhất\" ở phía sau. “最” đã là mức cao nhất nên không dùng chung với các phó từ mức độ khác như “很、太、非常”. Khi trả lời câu hỏi lựa chọn hoặc khi đưa ra lời khuyên, người Trung Quốc rất hay dùng “最” để nhấn mạnh phương án tối ưu: 九月去北京旅游最好 (tháng chín đi Bắc Kinh du lịch là tốt nhất).","viDu":[{"zh":"九月去北京旅游最好。","py":"Jiǔ yuè qù Běijīng lǚyóu zuì hǎo.","vn":"Tháng chín đi Bắc Kinh du lịch là tốt nhất."},{"zh":"我最喜欢游泳。","py":"Wǒ zuì xǐhuan yóuyǒng.","vn":"Tôi thích bơi nhất."},{"zh":"这个手表最贵。","py":"Zhège shǒubiǎo zuì guì.","vn":"Cái đồng hồ này đắt nhất."},{"zh":"我们家爸爸最忙。","py":"Wǒmen jiā bàba zuì máng.","vn":"Nhà tôi bố bận nhất."},{"zh":"这儿的羊肉最好吃。","py":"Zhèr de yángròu zuì hǎochī.","vn":"Thịt dê ở đây ngon nhất."}],"loi":[{"sai":"我喜欢最游泳。","why":"học sinh biết “最” đứng trước nhưng chưa xác định đúng trung tâm là động từ tâm lý “喜欢”.","dung":"我最喜欢游泳。"},{"sai":"这个手表贵最。","why":"bê nguyên trật tự tiếng Việt \"đắt nhất\" (tính từ + nhất).","dung":"这个手表最贵。"},{"sai":"这儿的羊肉最很好吃。","why":"học sinh nghĩ “很” là thành phần bắt buộc trước tính từ nên giữ lại cả hai.","dung":"这儿的羊肉最好吃。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["九月去北京旅游","好。"],"dap":[["最"]]},{"kieu":"dien","phan":["我","喜欢红色，别的颜色我都不太喜欢。"],"dap":[["最"]]},{"kieu":"dien","phan":["今天","冷，你多穿衣服。"],"dap":[["很"]]},{"kieu":"dien","phan":["我们家，爸爸","高，妹妹","矮。"],"dap":[["最"],["最"]]},{"kieu":"dien","phan":["这本书","便宜，只要五块钱。"],"dap":[["很"]]},{"kieu":"dien","phan":["在我们公司，他","忙。"],"dap":[["最"]]}],"huongDan":"Điền 最 hoặc 很","chon":["最","很"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["好","去","最","旅游","北京","九月"],"dap":["九月去北京旅游最好。"]},{"kieu":"xep","manh":["喜欢","我","打篮球","最"],"dap":["我最喜欢打篮球。"]},{"kieu":"xep","manh":["便宜","这儿","牛奶","的","最"],"dap":["这儿的牛奶最便宜。"]},{"kieu":"viet","yeuCau":"Viết lại dùng “最”","goc":"我喜欢红色。","dap":["我最喜欢红色。"]},{"kieu":"viet","yeuCau":"Viết lại dùng “最”","goc":"那个手表很贵。","dap":["那个手表最贵。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你最喜欢什么运动？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我最喜欢游泳。"],"goiY":"tôi thích bơi nhất"},{"kieu":"hoi","dong":[{"ai":"A","t":"什么时候去北京旅游好？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["九月去最好。","九月去北京旅游最好。","九月最好。"],"goiY":"tháng chín đi là tốt nhất"},{"kieu":"dich","vn":"Trong nhà tôi, mẹ dậy sớm nhất.","dap":["我们家，妈妈起床最早。","我们家妈妈起床最早。","我家妈妈起床最早。"]},{"kieu":"dich","vn":"Món này ngon nhất, cũng rẻ nhất.","dap":["这个菜最好吃，也最便宜。"]}]}]},{"so":"1.3","ten":"概数的表达：“几”和“多”","tenVn":"Cách diễn đạt số ước lượng: “几” và “多”","cauTruc":["几 + 量词 + N (几天、几个人)","十几 / 几十 + 量词 + N (十几天、几十个人)","số tròn chục trở lên + 多 + 量词 + N (二十多个人、一百多块)","số + 量词 + 多 (một lượng lẻ): 一个多小时、三块多钱"],"giaiThich":"Trong câu trần thuật, “几” không phải là từ để hỏi mà mang nghĩa \"mấy, vài“, chỉ một số lượng không xác định dưới mười: 我要去几天 (tôi đi mấy hôm). Ghép với ”十\" ta có “十几” (mười mấy, 11–19) và “几十” (mấy chục, 20–90). “多” đặt sau số từ tròn chục, tròn trăm để chỉ \"hơn, ngoài“: 二十多个人 (hơn hai mươi người). Còn khi số lẻ sau đơn vị có thể chia nhỏ được (小时、块、岁 dùng với số nhỏ), ”多\" đứng SAU lượng từ: 一个多小时 (hơn một tiếng), 三块多钱 (hơn ba đồng). Ngữ dụng: người Trung Quốc rất hay dùng số ước lượng khi chưa nắm chắc con số hoặc khi muốn nói cho khiêm tốn, tự nhiên, tránh cảm giác quá chính xác, cứng nhắc.","viDu":[{"zh":"我要去几天，九月回来。","py":"Wǒ yào qù jǐ tiān, jiǔ yuè huílai.","vn":"Tôi đi mấy hôm, tháng chín về."},{"zh":"我们班有十几个学生。","py":"Wǒmen bān yǒu shí jǐ ge xuésheng.","vn":"Lớp chúng tôi có mười mấy học sinh."},{"zh":"教室里有二十多个人。","py":"Jiàoshì lǐ yǒu èrshí duō ge rén.","vn":"Trong phòng học có hơn hai mươi người."},{"zh":"这件衣服一百多块。","py":"Zhè jiàn yīfu yìbǎi duō kuài.","vn":"Cái áo này hơn một trăm tệ."},{"zh":"我等了一个多小时。","py":"Wǒ děng le yí ge duō xiǎoshí.","vn":"Tôi đợi hơn một tiếng đồng hồ."}],"loi":[{"sai":"教室里有多二十个人。","why":"tiếng Việt nói \"hơn hai mươi người\", học sinh đặt “多” lên trước theo đúng trật tự tiếng mẹ đẻ.","dung":"教室里有二十多个人。"},{"sai":"我在北京住了十天几。","why":"học sinh hiểu “几” là \"mấy\" và đặt sau danh từ như tiếng Việt \"mười ngày mấy\".","dung":"我在北京住了十几天。"},{"sai":"我等了一多个小时。","why":"học sinh áp dụng máy móc quy tắc “số + 多 + 量词” cho cả trường hợp số lẻ, quên rằng với “一” thì “多” phải đứng sau lượng từ.","dung":"我等了一个多小时。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["我要去北京旅游，去","天就回来。"],"dap":[["几"]]},{"kieu":"dien","phan":["这个手表三百","块，不便宜。"],"dap":[["多"]]},{"kieu":"dien","phan":["我们公司有","十个人。"],"dap":[["几"]]},{"kieu":"dien","phan":["昨天我睡了十","个小时，今天不累了。"],"dap":[["几","多"]]},{"kieu":"dien","phan":["他儿子十","岁，已经很高了。"],"dap":[["多","几"]]},{"kieu":"dien","phan":["我在火车站等了两个","小时。"],"dap":[["多"]]}],"huongDan":"Điền 几 hoặc 多 vào chỗ trống","chon":["几","多"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["个","教室","有","二十多","里","学生"],"dap":["教室里有二十多个学生。"]},{"kieu":"xep","manh":["小时","我","一个多","休息","了"],"dap":["我休息了一个多小时。"]},{"kieu":"xep","manh":["十几","我们","有","公司","个","人"],"dap":["我们公司有十几个人。"]},{"kieu":"xep","manh":["块","这","一百多","衣服","件"],"dap":["这件衣服一百多块。"]},{"kieu":"xep","manh":["天","想","我","北京","去","几","玩"],"dap":["我想去北京玩几天。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你去北京玩几天？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我去十多天。","我去十几天。","十多天。","十几天。"],"goiY":"đi hơn mười ngày"},{"kieu":"hoi","dong":[{"ai":"A","t":"这个手表多少钱？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["三百多块。","三百多块钱。","这个手表三百多块。"],"goiY":"hơn ba trăm tệ"},{"kieu":"dich","vn":"Công ty tôi có hơn hai mươi người.","dap":["我们公司有二十多个人。"]},{"kieu":"dich","vn":"Hôm qua tôi đợi xe buýt hơn một tiếng.","dap":["昨天我等公共汽车等了一个多小时。","昨天我等了一个多小时公共汽车。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-2.html"] = [{"so":"2.1","ten":"用“是不是”的问句","tenVn":"Câu hỏi dùng “是不是”","cauTruc":["Sub + 是不是 + V/Adj (+ O)？","是不是 + Sub + V/Adj (+ O)？","Sub + V/Adj (+ O), 是不是？","Trả lời khẳng định: 是 / 对；Trả lời phủ định: 不是 / 没有"],"giaiThich":"“是不是” tạo thành câu hỏi chính phản dùng để XÁC NHẬN một điều người nói đã đoán trước, đã nhìn thấy hoặc nghe nói, tương đương \"có phải… không?\" trong tiếng Việt. Vị trí linh hoạt: đứng trước vị ngữ (nhấn mạnh nhất), đứng đầu câu (ngạc nhiên), hoặc đặt cuối câu như một câu hỏi đuôi (giọng nhẹ nhàng, thân mật). Điểm cốt tử: “是不是” và “吗” đều là phương tiện tạo câu hỏi nên TUYỆT ĐỐI không dùng chung trong một câu. Về ngữ dụng, so với câu hỏi “吗” trung tính, câu hỏi “是不是” thể hiện người nói đã có sẵn phán đoán, thường dùng khi quan tâm, hỏi han: 你是不是生病了？ (Cậu ốm rồi phải không?).","viDu":[{"zh":"你是不是每天六点起床？","py":"Nǐ shì bu shì měi tiān liù diǎn qǐchuáng?","vn":"Có phải hằng ngày bạn dậy lúc 6 giờ không?"},{"zh":"你是不是生病了？","py":"Nǐ shì bu shì shēngbìng le?","vn":"Có phải bạn ốm rồi không?"},{"zh":"是不是他没来？","py":"Shì bu shì tā méi lái?","vn":"Có phải anh ấy chưa đến không?"},{"zh":"你身体不舒服，是不是？","py":"Nǐ shēntǐ bù shūfu, shì bu shì?","vn":"Người bạn khó chịu, đúng không?"},{"zh":"这个手表是不是很贵？","py":"Zhège shǒubiǎo shì bu shì hěn guì?","vn":"Cái đồng hồ này có phải rất đắt không?"}],"loi":[{"sai":"你是不是每天六点起床吗？","why":"tiếng Việt \"có phải… không?\" có chữ \"không\" ở cuối, học sinh dịch \"không\" thành “吗” rồi thêm vào.","dung":"你是不是每天六点起床？"},{"sai":"你每天六点是不是起床？","why":"đặt “是不是” tuỳ tiện giữa câu, tách rời trạng ngữ thời gian với động từ.","dung":"你是不是每天六点起床？"},{"sai":"他是不是是学生？","why":"học sinh coi “是不是” là một khối cố định rồi vẫn thêm động từ “是” của câu, vì tiếng Việt vẫn nói \"có phải… là học sinh không\".","dung":"他是不是学生？"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["你","每天六点起床？"],"dap":[["是不是"]]},{"kieu":"dien","phan":["你每天六点起床","？"],"dap":[["吗"]]},{"kieu":"dien","phan":["他","生病了？我看他很累。"],"dap":[["是不是"]]},{"kieu":"dien","phan":["明天你去公司","？"],"dap":[["吗"]]},{"kieu":"dien","phan":["","你妻子没来？"],"dap":[["是不是"]]},{"kieu":"dien","phan":["这个颜色很好看,","？"],"dap":[["是不是"]]}],"huongDan":"Điền 是不是 hoặc 吗","chon":["是不是","吗"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["六点","你","是不是","起床","每天"],"dap":["你是不是每天六点起床？"]},{"kieu":"xep","manh":["了","是不是","你","生病"],"dap":["你是不是生病了？"]},{"kieu":"xep","manh":["是不是","贵","手表","这个","很"],"dap":["这个手表是不是很贵？"]},{"kieu":"viet","yeuCau":"Chuyển thành câu hỏi “是不是”","goc":"他今天没来上班。","dap":["他今天是不是没来上班？"]},{"kieu":"viet","yeuCau":"Chuyển thành câu hỏi “是不是”","goc":"你妹妹会唱歌。","dap":["你妹妹是不是会唱歌？"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","o":true,"truoc":"","sau":""},{"ai":"B","t":"对，我有点儿累。"}],"dap":["你是不是身体不舒服？"],"goiY":"Có phải bạn không khoẻ không?"},{"kieu":"hoi","dong":[{"ai":"A","t":"你是不是每天都运动？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["对，我每天都踢足球。"],"goiY":"Đúng vậy, ngày nào tôi cũng đá bóng"},{"kieu":"dich","vn":"Có phải chồng bạn làm việc ở công ty này không?","dap":["你丈夫是不是在这个公司工作？"]},{"kieu":"dich","vn":"Con ốm rồi phải không? Uống thuốc rồi nghỉ một lát đi.","dap":["你是不是生病了？吃药，休息一下吧。"]}]}]},{"so":"2.2","ten":"代词“每”","tenVn":"Đại từ “每”","cauTruc":["每 + 量词 + N + 都 + V (每个学生都…)","每 + 天 / 年 / 月 / 分钟 (những từ tự làm lượng từ, không dùng “个”)","每 + 量词 + N, Sub + 都 + V"],"giaiThich":"“每” nghĩa là \"mỗi, hằng\", chỉ toàn bộ các cá thể trong một phạm vi, nhấn mạnh tính đều đặn, không có ngoại lệ. Về cú pháp, “每” không đứng trực tiếp trước danh từ đếm được mà phải có lượng từ ở giữa: 每个学生、每个星期; riêng 天、年、月 vốn đã kiêm chức năng lượng từ nên nói “每天、每年、每月” (không nói 每个天). Vì “每” mang ý bao quát toàn bộ nên phía sau thường đi kèm phó từ “都” để hô ứng: 每个人都有一个问题. Khi câu đã có trạng ngữ chỉ thời điểm cụ thể như “六点” thì “都” có thể lược bỏ: 我每天六点起床. Ngữ dụng: “每” rất hay xuất hiện khi kể về thói quen, thời gian biểu hằng ngày.","viDu":[{"zh":"我每天六点起床。","py":"Wǒ měi tiān liù diǎn qǐchuáng.","vn":"Hằng ngày tôi dậy lúc 6 giờ."},{"zh":"他每天都吃一个鸡蛋。","py":"Tā měi tiān dōu chī yí ge jīdàn.","vn":"Ngày nào anh ấy cũng ăn một quả trứng gà."},{"zh":"每个学生都有一本书。","py":"Měi ge xuésheng dōu yǒu yì běn shū.","vn":"Mỗi học sinh đều có một quyển sách."},{"zh":"我每个星期去游泳。","py":"Wǒ měi ge xīngqī qù yóuyǒng.","vn":"Mỗi tuần tôi đều đi bơi."},{"zh":"她每天晚上都跳舞。","py":"Tā měi tiān wǎnshang dōu tiàowǔ.","vn":"Tối nào cô ấy cũng nhảy múa."}],"loi":[{"sai":"每学生都有一本书。","why":"tiếng Việt \"mỗi học sinh\" không cần lượng từ nên học sinh bỏ luôn “个”.","dung":"每个学生都有一本书。"},{"sai":"每个天我都去公司。","why":"học sinh vừa học quy tắc “每 + 量词 + N” nên áp dụng quá đà cho cả “天”.","dung":"每天我都去公司。"},{"sai":"我们每个人有一个问题。","why":"tiếng Việt \"mỗi người có một câu hỏi\" không cần từ \"đều\", học sinh bỏ mất “都”.","dung":"我们每个人都有一个问题。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["我","六点起床。"],"dap":[["每天"]]},{"kieu":"dien","phan":["","学生","有一本汉语书。"],"dap":[["每个"],["都"]]},{"kieu":"dien","phan":["他","星期去两次医院。"],"dap":[["每个"]]},{"kieu":"dien","phan":["我们","人","很忙。"],"dap":[["每个"],["都"]]},{"kieu":"dien","phan":["妈妈","早上","喝牛奶。"],"dap":[["每天"],["都"]]},{"kieu":"dien","phan":["","孩子","喜欢玩儿。"],"dap":[["每个"],["都"]]}],"huongDan":"Điền 每天 / 每个 / 都","chon":["每天","每个","都"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["六点","我","起床","每天"],"dap":["我每天六点起床。"]},{"kieu":"xep","manh":["都","鸡蛋","他","吃","每天","一个"],"dap":["他每天都吃一个鸡蛋。"]},{"kieu":"xep","manh":["有","每个","都","手表","学生","一块"],"dap":["每个学生都有一块手表。"]},{"kieu":"xep","manh":["去","每个","我","游泳","星期"],"dap":["我每个星期去游泳。"]},{"kieu":"viet","yeuCau":"Viết lại dùng “每…都…”","goc":"他星期一、星期二、星期三…运动。","dap":["他每天都运动。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你每天几点起床？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我每天六点起床。"],"goiY":"tôi dậy lúc 6 giờ hằng ngày"},{"kieu":"hoi","dong":[{"ai":"A","t":"你每个星期都运动吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["是的，我每个星期都去游泳。"],"goiY":"vâng, tuần nào tôi cũng đi bơi"},{"kieu":"dich","vn":"Sáng nào vợ tôi cũng uống một cốc sữa.","dap":["我妻子每天早上都喝一杯牛奶。"]},{"kieu":"dich","vn":"Mỗi học sinh đều phải giúp thầy giáo chuẩn bị.","dap":["每个学生都要帮老师准备。"]}]}]},{"so":"2.3","ten":"疑问代词“多”","tenVn":"Đại từ nghi vấn “多” (多大/多高/多长时间…)","cauTruc":["多 + Adj đơn âm tiết (多大、多高、多长、多远)？","Sub + 多大 / 多高？","V + 多长时间？(V + 了 + 多长时间 + 了？)"],"giaiThich":"“多” đặt trước tính từ đơn âm tiết tạo thành cụm hỏi về mức độ, con số cụ thể: 多大 (bao nhiêu tuổi / to bằng nào), 多高 (cao bao nhiêu), 多远 (xa bao nhiêu), 多长时间 (bao lâu). Đây đã là hình thức câu hỏi nên cuối câu KHÔNG được thêm “吗”. Khi hỏi tuổi phải chọn đúng sắc thái: hỏi trẻ nhỏ dùng “几岁”, hỏi người cùng trang lứa hoặc lớn hơn mình một chút dùng “多大”, hỏi người già dùng “多大年纪” cho lịch sự. Hỏi về khoảng thời gian, tiếng Hán không nói “多长” trống không mà phải nói đủ “多长时间”, và cụm này đứng SAU động từ như một bổ ngữ thời lượng: 你每天休息多长时间？","viDu":[{"zh":"你每天休息多长时间？","py":"Nǐ měi tiān xiūxi duō cháng shíjiān?","vn":"Hằng ngày bạn nghỉ ngơi bao lâu?"},{"zh":"你今年多大？","py":"Nǐ jīnnián duō dà?","vn":"Năm nay bạn bao nhiêu tuổi?"},{"zh":"你儿子多高？","py":"Nǐ érzi duō gāo?","vn":"Con trai bạn cao bao nhiêu?"},{"zh":"你家离公司多远？","py":"Nǐ jiā lí gōngsī duō yuǎn?","vn":"Nhà bạn cách công ty bao xa?"},{"zh":"你学汉语学了多长时间？","py":"Nǐ xué Hànyǔ xué le duō cháng shíjiān?","vn":"Bạn học tiếng Hán được bao lâu rồi?"}],"loi":[{"sai":"你几岁？(hỏi người lớn)","why":"tiếng Việt chỉ có một cách hỏi \"bao nhiêu tuổi\", học sinh không phân biệt đối tượng.","dung":"你今年多大？"},{"sai":"你每天休息多长？","why":"dịch sát \"nghỉ bao lâu\" mà quên rằng “多长” một mình chỉ hỏi độ dài vật thể, hỏi thời gian phải có “时间”.","dung":"你每天休息多长时间？"},{"sai":"你家离火车站多远吗？","why":"học sinh quen thêm \"không?\" ở cuối câu hỏi tiếng Việt nên thêm “吗” vào câu đã có từ nghi vấn.","dung":"你家离火车站多远？"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["你今年","？——我今年二十岁。"],"dap":[["多大"]]},{"kieu":"dien","phan":["你女儿","？——她四岁。"],"dap":[["几岁"]]},{"kieu":"dien","phan":["你每天睡","？——我睡八个小时。"],"dap":[["多长时间"]]},{"kieu":"dien","phan":["你家离机场","？——很近，十分钟就到。"],"dap":[["多远"]]},{"kieu":"dien","phan":["你弟弟","？——他一米八。"],"dap":[["多高"]]},{"kieu":"dien","phan":["你在北京住了","？——住了三年多。"],"dap":[["多长时间"]]}],"huongDan":"Điền 多大 / 多高 / 多远 / 多长时间 / 几岁","chon":["多大","多高","多远","多长时间","几岁"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["时间","你","休息","每天","多长"],"dap":["你每天休息多长时间？"]},{"kieu":"xep","manh":["多大","你","今年","儿子"],"dap":["你儿子今年多大？"]},{"kieu":"xep","manh":["离","多远","公司","你家"],"dap":["你家离公司多远？"]},{"kieu":"viet","yeuCau":"Đặt câu hỏi cho phần gạch chân","goc":"我每天休息<u>两个小时</u>。","dap":["你每天休息多长时间？"]},{"kieu":"viet","yeuCau":"Đặt câu hỏi cho phần gạch chân","goc":"我哥哥今年<u>三十岁</u>。","dap":["你哥哥今年多大？"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","o":true,"truoc":"","sau":""},{"ai":"B","t":"我休息两个小时。"}],"dap":["你每天休息多长时间？"],"goiY":"Hằng ngày bạn nghỉ bao lâu?"},{"kieu":"hoi","dong":[{"ai":"A","t":"你学汉语学了多长时间了？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我学了一年多了。"],"goiY":"tôi học hơn một năm rồi"},{"kieu":"dich","vn":"Con gái bạn mấy tuổi rồi? Cao bao nhiêu?","dap":["你女儿几岁了？多高？"]},{"kieu":"dich","vn":"Từ đây đến ga tàu bao xa? Đi xe buýt mất bao lâu?","dap":["这儿离火车站多远？坐公共汽车要多长时间？"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-3.html"] = [{"so":"3.1","ten":"“的”字短语","tenVn":"Cụm từ chữ “的” (danh hoá)","cauTruc":["Pron / N + 的 (我的、老师的) = \"của tôi / của thầy giáo\"","Adj + 的 (红色的、大的、便宜的)","Cụm chỉ định + Adj + 的 (左边那个红色的)","Toàn cụm giữ chức năng chủ ngữ hoặc tân ngữ như một danh từ"],"giaiThich":"Khi ngữ cảnh đã rõ danh từ trung tâm là gì, người Trung Quốc lược bỏ danh từ đó và giữ lại “的”, tạo thành “cụm từ chữ 的” mang chức năng như một danh từ. Ví dụ đang nói về cặp sách, thay vì nói 左边那个红色的书包 người ta chỉ cần nói 左边那个红色的. Về ngữ nghĩa, cụm này chỉ \"cái/người… như thế nào\" hoặc \"của ai\". Đây chính là chỗ học sinh Việt hay thiếu chữ “的” cuối cụm, vì tiếng Việt chỉ cần nói \"cái màu đỏ\", \"của tôi\" là đủ. Hãy nhớ: hễ đã bỏ danh từ trung tâm thì “的” bắt buộc phải có, nó chính là dấu hiệu danh hoá. Ngữ dụng: dùng cụm chữ “的” giúp câu ngắn gọn, tránh lặp từ, rất thường gặp khi chọn đồ, nhận đồ, so sánh đồ vật.","viDu":[{"zh":"左边那个红色的是我的。","py":"Zuǒbian nàge hóngsè de shì wǒ de.","vn":"Cái màu đỏ bên trái là của tôi."},{"zh":"这个手表是我的，那个是他的。","py":"Zhège shǒubiǎo shì wǒ de, nàge shì tā de.","vn":"Cái đồng hồ này là của tôi, cái kia là của anh ấy."},{"zh":"这些苹果，大的很贵，小的很便宜。","py":"Zhèxiē píngguǒ, dà de hěn guì, xiǎo de hěn piányi.","vn":"Chỗ táo này, quả to thì đắt, quả nhỏ thì rẻ."},{"zh":"服务员，白色的那个是我们的吗？","py":"Fúwùyuán, báisè de nàge shì wǒmen de ma?","vn":"Nhân viên phục vụ ơi, cái màu trắng kia là của chúng tôi phải không?"},{"zh":"我买的是新的，不是贵的。","py":"Wǒ mǎi de shì xīn de, bú shì guì de.","vn":"Cái tôi mua là cái mới, không phải cái đắt."}],"loi":[{"sai":"左边那个红色是我的。","why":"tiếng Việt \"cái màu đỏ bên trái\" không có thành phần tương ứng với “的” nên học sinh bỏ mất.","dung":"左边那个红色的是我的。"},{"sai":"这是我。(muốn nói \"cái này của tôi\")","why":"tiếng Việt \"của tôi\" dịch thành “我” là xong, quên rằng phải có “的” mới biểu thị sở hữu.","dung":"这是我的。"},{"sai":"这个红色的手表是我的手表。","why":"học sinh lặp lại danh từ trung tâm theo thói quen tiếng Việt, câu trở nên rườm rà.","dung":"这个红色的是我的。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["左边那个红色","是我","。"],"dap":[["的"],["的"]]},{"kieu":"dien","phan":["这个手表不是我",",是我丈夫","。"],"dap":[["的"],["的"]]},{"kieu":"dien","phan":["这些鸡蛋，大","三块，小","两块。"],"dap":[["的"],["的"]]},{"kieu":"dien","phan":["那件白色","衣服很便宜。"],"dap":[["的"]]},{"kieu":"dien","phan":["这本书是谁","？"],"dap":[["的"]]},{"kieu":"dien","phan":["我喜欢新",",不喜欢贵","。"],"dap":[["的"],["的"]]}],"huongDan":"Điền “的” vào vị trí thích hợp, nếu câu đã đúng thì ghi ✓","chon":["的","✓"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["是","那个","我的","红色的","左边"],"dap":["左边那个红色的是我的。"]},{"kieu":"xep","manh":["的","这个","妻子","是","我","手表"],"dap":["这个手表是我妻子的。"]},{"kieu":"xep","manh":["便宜的","我","买","想"],"dap":["我想买便宜的。"]},{"kieu":"viet","yeuCau":"Rút gọn câu","goc":"这个红色的书是我的书。","dap":["这个红色的是我的。"]},{"kieu":"viet","yeuCau":"Rút gọn câu","goc":"大的苹果很贵，小的苹果很便宜。","dap":["大的很贵，小的很便宜。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"哪个是你的？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["左边那个红色的是我的。"],"goiY":"cái màu đỏ bên trái là của tôi"},{"kieu":"hoi","dong":[{"ai":"A","t":"这两个手表，你要哪个？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我要便宜的。"],"goiY":"tôi lấy cái rẻ"},{"kieu":"dich","vn":"Tờ báo này không phải của tôi, là của chồng tôi.","dap":["这个报纸不是我的，是我丈夫的。"]},{"kieu":"dich","vn":"Màu trắng là của con trai tôi, màu đỏ là của con gái tôi.","dap":["白色的是我儿子的，红色的是我女儿的。"]}]}]},{"so":"3.2","ten":"“一下”","tenVn":"Cách dùng “一下”","cauTruc":["V + 一下 (看一下、等一下、休息一下)","V + 一下 + O (介绍一下我的公司)","请 + V + 一下 / V + 一下 + 吧"],"giaiThich":"“一下” đứng sau động từ làm bổ ngữ động lượng, biểu thị động tác diễn ra trong thời gian ngắn, số lượng ít, tương đương \"một chút, một lát, thử\" trong tiếng Việt. Ngoài nghĩa \"ngắn\", “一下” còn có giá trị ngữ dụng rất quan trọng: nó làm cho lời đề nghị, yêu cầu trở nên nhẹ nhàng, lịch sự, bớt áp đặt. So sánh: 你看 (nhìn đi — hơi cộc) với 你看一下 (bạn xem một chút nhé — mềm mại hơn). Nếu động từ có tân ngữ thì “一下” đứng GIỮA động từ và tân ngữ, không được đẩy tân ngữ lên trước. Lưu ý “一下” chỉ kết hợp với động từ; muốn nói \"nhanh một chút, rẻ một chút\" (tính từ) thì phải dùng “一点儿”.","viDu":[{"zh":"你看一下。","py":"Nǐ kàn yíxià.","vn":"Bạn xem một chút."},{"zh":"请等一下，他马上来。","py":"Qǐng děng yíxià, tā mǎshàng lái.","vn":"Xin đợi một lát, anh ấy đến ngay."},{"zh":"我给你们介绍一下。","py":"Wǒ gěi nǐmen jièshào yíxià.","vn":"Tôi giới thiệu một chút với các bạn nhé."},{"zh":"你帮我一下，好吗？","py":"Nǐ bāng wǒ yíxià, hǎo ma?","vn":"Bạn giúp tôi một chút, được không?"},{"zh":"你累了，休息一下吧。","py":"Nǐ lèi le, xiūxi yíxià ba.","vn":"Bạn mệt rồi, nghỉ một lát đi."}],"loi":[{"sai":"请你一下等。","why":"học sinh xếp \"một chút\" như một trạng ngữ đứng trước động từ theo cảm giác tiếng Việt.","dung":"请你等一下。"},{"sai":"你看这本书一下。","why":"tiếng Việt nói \"bạn xem quyển sách này một chút\", tân ngữ đứng trước \"một chút\".","dung":"你看一下这本书。"},{"sai":"你快一下。","why":"học sinh dùng “一下” với tính từ vì tiếng Việt \"nhanh một chút\" cũng dùng chung một từ.","dung":"你快一点儿。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["你看",",这个颜色好看吗？"],"dap":[["一下"]]},{"kieu":"dien","phan":["请等",",我妻子马上到。"],"dap":[["一下"]]},{"kieu":"dien","phan":["这个太贵了，便宜","吧。"],"dap":[["一点儿"]]},{"kieu":"dien","phan":["我给大家介绍","。"],"dap":[["一下"]]},{"kieu":"dien","phan":["你慢","说，我听不懂。"],"dap":[["一点儿"]]},{"kieu":"dien","phan":["你累了，先休息","。"],"dap":[["一下"]]}],"huongDan":"Điền 一下 hoặc 一点儿","chon":["一下","一点儿"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["一下","你","看"],"dap":["你看一下。"]},{"kieu":"xep","manh":["一下","请","等","你"],"dap":["请你等一下。"]},{"kieu":"xep","manh":["一下","我","介绍","给","你们"],"dap":["我给你们介绍一下。"]},{"kieu":"xep","manh":["一下","帮","你","我","好吗"],"dap":["你帮我一下，好吗？"]},{"kieu":"viet","yeuCau":"Thêm “一下” cho câu lịch sự hơn","goc":"你看这个报纸。","dap":["你看一下这个报纸。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"老师在吗？"},{"ai":"B","o":true,"truoc":"在,","sau":""}],"dap":["在，请等一下。"],"goiY":"xin đợi một lát"},{"kieu":"hoi","dong":[{"ai":"A","t":"我不认识他们。"},{"ai":"B","o":true,"truoc":"好,","sau":""}],"dap":["好，我给你们介绍一下。"],"goiY":"tôi giới thiệu một chút"},{"kieu":"dich","vn":"Cái đồng hồ này rất đẹp, bạn xem một chút đi.","dap":["这个手表很好看，你看一下。"]},{"kieu":"dich","vn":"Tôi hơi mệt, muốn nghỉ một lát.","dap":["我有点儿累，想休息一下。"]}]}]},{"so":"3.3","ten":"语气副词“真”","tenVn":"Phó từ ngữ khí “真”","cauTruc":["Sub + 真 + Adj！","Sub + 真 + 喜欢 / 会 / 能 + …！","真 + Adj + 啊！(真好看啊！)"],"giaiThich":"“真” là phó từ ngữ khí, đứng trước tính từ hoặc động từ tâm lý để biểu thị CẢM THÁN, nghĩa là \"thật là, quả là\", thể hiện đánh giá chủ quan và cảm xúc mạnh của người nói ngay tại thời điểm nhìn thấy sự việc. Khác với “很” chỉ mô tả mức độ một cách trung tính (这个颜色很好看 — màu này đẹp), “真” mang cảm xúc ngạc nhiên, khen ngợi, thán phục (这个颜色真好看！ — màu này đẹp thật!). Vì là câu cảm thán nên “真” KHÔNG dùng trong câu nghi vấn “吗”, cũng không dùng để trả lời câu hỏi về mức độ, và cuối câu thường có “啊” hoặc dấu chấm than. Về vị trí, “真” đứng ngay trước tính từ, không đứng đầu câu.","viDu":[{"zh":"这个颜色真好看！","py":"Zhège yánsè zhēn hǎokàn!","vn":"Màu này đẹp thật!"},{"zh":"今天真冷，你多穿衣服。","py":"Jīntiān zhēn lěng, nǐ duō chuān yīfu.","vn":"Hôm nay lạnh thật đấy, bạn mặc thêm áo vào."},{"zh":"你女儿真漂亮！","py":"Nǐ nǚ'ér zhēn piàoliang!","vn":"Con gái bạn xinh thật!"},{"zh":"这个菜真好吃，我最喜欢。","py":"Zhège cài zhēn hǎochī, wǒ zuì xǐhuan.","vn":"Món này ngon thật, tôi thích nhất."},{"zh":"你说汉语说得真快！","py":"Nǐ shuō Hànyǔ shuō de zhēn kuài!","vn":"Bạn nói tiếng Hán nhanh thật!"}],"loi":[{"sai":"这个颜色真好看吗？","why":"học sinh coi “真” như “很” và dùng trong câu hỏi, không nhận ra “真” là phó từ cảm thán.","dung":"这个颜色好看吗？"},{"sai":"真这个菜好吃！","why":"tiếng Việt nói \"thật là món này ngon\", học sinh đặt “真” lên đầu câu.","dung":"这个菜真好吃！"},{"sai":"他真是很高。","why":"học sinh ghép cả “真” lẫn “很” và thêm “是” vì tiếng Việt \"anh ấy thật là cao\".","dung":"他真高。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["这个颜色","好看！"],"dap":[["真"]]},{"kieu":"dien","phan":["这个手表","贵吗？"],"dap":[["很"]]},{"kieu":"dien","phan":["今天","冷，我不想起床！"],"dap":[["真"]]},{"kieu":"dien","phan":["他每天都","忙。"],"dap":[["很"]]},{"kieu":"dien","phan":["你女儿","漂亮！几岁了？"],"dap":[["真"]]},{"kieu":"dien","phan":["那儿的羊肉","好吃，你去吃吧。"],"dap":[["真"]]}],"huongDan":"Điền 真 hoặc 很","chon":["真","很"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["好看","颜色","真","这个"],"dap":["这个颜色真好看！"]},{"kieu":"xep","manh":["快","你","真","说","得"],"dap":["你说得真快！"]},{"kieu":"xep","manh":["冷","今天","真","天气"],"dap":["今天天气真冷！"]},{"kieu":"viet","yeuCau":"Chuyển thành câu cảm thán dùng “真”","goc":"这个菜很好吃。","dap":["这个菜真好吃！"]},{"kieu":"viet","yeuCau":"Chuyển thành câu cảm thán dùng “真”","goc":"你儿子很高。","dap":["你儿子真高！"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你看，这是我买的手表。"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["这个颜色真好看！"],"goiY":"màu này đẹp thật!"},{"kieu":"hoi","dong":[{"ai":"A","t":"今天下雪了。"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["今天真冷，我不想出去。"],"goiY":"hôm nay lạnh thật, tôi không muốn ra ngoài"},{"kieu":"dich","vn":"Bạn hát hay thật! Bạn học bao lâu rồi?","dap":["你唱歌唱得真好！你学了多长时间了？"]},{"kieu":"dich","vn":"Món này ngon thật, lại còn rẻ nữa.","dap":["这个菜真好吃，也很便宜。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-4.html"] = [{"so":"4.1","ten":"“是……的”句","tenVn":"Câu “是……的”","cauTruc":["Khẳng định: 主语 + 是 + [时间 / 地点 / 方式 / 施事] + 动词 (+ 宾语) + 的","→ S + shì + [thời gian / nơi chốn / cách thức / người thực hiện] + V (+ O) + de","Phủ định: 主语 + 不是 + [时间 / 地点 / 方式 / 施事] + 动词 + 的","(chỉ dùng 不是, TUYỆT ĐỐI không dùng 没是)","Nghi vấn: 主语 + 是 + …… + 动词 + 的 + 吗？","hoặc dùng từ để hỏi: 是什么时候……的？／是在哪儿……的？／是怎么……的？／是谁……的？","Vị trí của 的: đứng sau động từ, thường ở CUỐI câu. Nếu tân ngữ là danh từ chỉ vật, 的 có thể đứng trước tân ngữ: 我是去年买的手表。= 我是去年买手表的。"],"giaiThich":"Các em chú ý: câu “是……的” chỉ dùng khi việc đó ĐÃ XẢY RA RỒI, cả người nói và người nghe đều biết là nó đã xảy ra. Người nói không thông báo \"có xảy ra hay không\" nữa, mà nhấn mạnh vào MỘT chi tiết: xảy ra khi nào, ở đâu, bằng cách nào, hay ai làm. Cái chi tiết được nhấn mạnh đó nằm ngay sau 是. Vì vậy khi trả lời câu hỏi 你是什么时候来的？ thì phải trả lời bằng chính khuôn 是……的, chứ không nói 我去年九月来了. Cô nhắc thêm: 是 có thể lược bỏ trong câu khẳng định (我去年九月来的), nhưng 的 thì KHÔNG BAO GIỜ được bỏ — bỏ 的 là hỏng cả câu.","viDu":[{"zh":"这个工作是他帮我介绍的。","py":"Zhège gōngzuò shì tā bāng wǒ jièshào de.","vn":"Công việc này là do anh ấy giới thiệu giúp tôi."},{"zh":"你是什么时候来的？","py":"Nǐ shì shénme shíhou lái de?","vn":"Bạn đến khi nào vậy?"},{"zh":"我是去年九月来的。","py":"Wǒ shì qùnián jiǔ yuè lái de.","vn":"Tôi đến hồi tháng 9 năm ngoái."},{"zh":"这件衣服是在商店买的。","py":"Zhè jiàn yīfu shì zài shāngdiàn mǎi de.","vn":"Chiếc áo này là mua ở cửa hàng."},{"zh":"他不是今天来的，是昨天来的。","py":"Tā bú shì jīntiān lái de, shì zuótiān lái de.","vn":"Anh ấy không phải đến hôm nay, mà là đến hôm qua."}],"loi":[{"sai":"我是去年九月的来。","why":"học sinh Việt đặt 的 theo thói quen \"của\" trong tiếng Việt, dán 的 ngay sau cụm thời gian; thực ra 的 phải đứng SAU động từ, ở cuối câu.","dung":"我是去年九月来的。"},{"sai":"这个工作是他帮我介绍。","why":"tiếng Việt nói \"Công việc này là anh ấy giới thiệu giúp tôi\" không có thành phần nào tương ứng với 的, nên học sinh quên mất vế 的; mà thiếu 的 thì khung 是……的 tan vỡ.","dung":"这个工作是他帮我介绍的。"},{"sai":"我没是坐飞机来的。","why":"nghĩ rằng “việc đã xảy ra trong quá khứ thì phủ định bằng 没”; nhưng ở đây phủ định là phủ định của 是.","dung":"我不是坐飞机来的。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["你","什么时候来的？"],"dap":[["是"]],"chon":["是","在"]},{"kieu":"dien","phan":["我是去年九月来","。"],"dap":[["的"]],"chon":["了","的"]},{"kieu":"dien","phan":["这个工作","他帮我介绍的。"],"dap":[["是"]],"chon":["是","很"]},{"kieu":"dien","phan":["这件衣服是在哪儿买","？"],"dap":[["的"]],"chon":["的","吗"]},{"kieu":"dien","phan":["他","坐飞机来的，是坐火车来的。"],"dap":[["不是"]],"chon":["不是","没是"]},{"kieu":"dien","phan":["我们","一起去","。"],"dap":[["是"],["的"]],"chon":["是……的","在……了"],"ghep":true,"giai":"我们是一起去的。"}]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["我","是","买","在商店","的"],"dap":["我是在商店买的。"]},{"kieu":"xep","manh":["你","是","来","怎么","的"],"dap":["你是怎么来的？"]},{"kieu":"xep","manh":["这个工作","是","他","帮我","介绍","的"],"dap":["这个工作是他帮我介绍的。"]},{"kieu":"xep","manh":["我","是","来","去年九月","的"],"dap":["我是去年九月来的。"]},{"kieu":"xep","manh":["他","不是","来","今天","的"],"dap":["他不是今天来的。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你是什么时候来北京的？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我是去年九月来的。"],"goiY":"tháng 9 năm ngoái"},{"kieu":"hoi","dong":[{"ai":"A","o":true,"truoc":"这件衣服","sau":"？"},{"ai":"B","t":"我是在商店买的。"}],"dap":["这件衣服是在哪儿买的？"],"goiY":"hỏi: mua ở đâu"},{"kieu":"dich","vn":"Công việc này là do chị ấy giới thiệu giúp tôi.","dap":["这个工作是她帮我介绍的。"]},{"kieu":"dich","vn":"Bạn đến bằng cách nào? — Tôi đi máy bay đến.","dap":["你是怎么来的？——我是坐飞机来的。"]}]}]},{"so":"4.2","ten":"“……的时候”","tenVn":"Cấu trúc diễn đạt thời gian “……的时候”","cauTruc":["(在) + 动词/形容词/小句 + 的时候，+ 主语 + 谓语","→ (zài) + V / Adj / mệnh đề + de shíhou, + S + VN = \"khi/lúc …, thì …\"","Các dạng hay gặp:","- 动词 + 的时候：吃饭的时候、上班的时候","- 主语 + 动词 + 的时候：我来的时候、他走的时候","- 形容词 + 的时候：小的时候、忙的时候","- 名词 + 的时候：星期天的时候","Lưu ý: cụm “……的时候” thường đứng ĐẦU câu, sau nó có dấu phẩy; 的 không được lược bỏ."],"giaiThich":"“……的时候” tương đương \"khi/lúc …\" trong tiếng Việt, dùng để nêu mốc thời gian cho sự việc ở vế sau. Điểm khác biệt lớn nhất với tiếng Việt là tiếng Việt đặt \"khi\" ở ĐẦU cụm (khi tôi đến), còn tiếng Trung đặt “的时候” ở CUỐI cụm (我来的时候). Các em nhớ công thức: nội dung trước — 的时候 sau. Vế sau thường dùng 在、正在、还 để tả trạng thái đang diễn ra, hoặc dùng 了 để kể việc đã xảy ra.","viDu":[{"zh":"我来的时候，他在睡觉。","py":"Wǒ lái de shíhou, tā zài shuìjiào.","vn":"Lúc tôi đến, anh ấy đang ngủ."},{"zh":"上班的时候，别看手机。","py":"Shàngbān de shíhou, bié kàn shǒujī.","vn":"Lúc đi làm thì đừng xem điện thoại."},{"zh":"小的时候，我很喜欢吃羊肉。","py":"Xiǎo de shíhou, wǒ hěn xǐhuan chī yángròu.","vn":"Hồi nhỏ, tôi rất thích ăn thịt dê."},{"zh":"生病的时候，要多休息，多喝水。","py":"Shēngbìng de shíhou, yào duō xiūxi, duō hē shuǐ.","vn":"Lúc ốm thì phải nghỉ nhiều, uống nhiều nước."},{"zh":"你来的时候，帮我买一点儿牛奶。","py":"Nǐ lái de shíhou, bāng wǒ mǎi yìdiǎnr niúnǎi.","vn":"Lúc bạn đến, mua giúp tôi một ít sữa nhé."}],"loi":[{"sai":"我来中国时候，他在睡觉。","why":"học sinh nghe quen âm \"shíhou“ nên tưởng 时候 tự nó đã là ”khi\", quên mất 的 bắt buộc phải có để nối với vế trước.","dung":"我来中国的时候，他在睡觉。"},{"sai":"的时候我来，他不在家。","why":"bê nguyên trật tự tiếng Việt \"khi tôi đến\", đặt “的时候” lên trước; tiếng Trung phải để nội dung trước rồi mới tới 的时候.","dung":"我来的时候，他不在家。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["我来","时候，他在睡觉。"],"dap":[["的"]],"chon":["的","的时候","时候"]},{"kieu":"dien","phan":["吃饭","，别看手机。"],"dap":[["的时候"]],"chon":["的","的时候","时候"]},{"kieu":"dien","phan":["","的时候，我很喜欢吃羊肉。"],"dap":[["小"]],"chon":["小","少"]},{"kieu":"dien","phan":["生病的","，要多休息。"],"dap":[["时候"]],"chon":["的","的时候","时候"]},{"kieu":"dien","phan":["你来的时候，","我买一点儿牛奶。"],"dap":[["帮"]],"chon":["帮","给"]},{"kieu":"dien","phan":["他上班","，我还在睡觉。"],"dap":[["的时候"]],"chon":["的","的时候","时候"]}]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["我","的时候","来","他","睡觉","在"],"dap":["我来的时候，他在睡觉。"]},{"kieu":"xep","manh":["的时候","上班","别","手机","看"],"dap":["上班的时候别看手机。"]},{"kieu":"xep","manh":["我","小","的时候","很","羊肉","喜欢","吃"],"dap":["小的时候，我很喜欢吃羊肉。"]},{"kieu":"xep","manh":["的时候","生病","要","休息","多"],"dap":["生病的时候，要多休息。"]},{"kieu":"xep","manh":["你","的时候","来","帮","我","买","牛奶","一点儿"],"dap":["你来的时候，帮我买一点儿牛奶。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你昨天来的时候，我在做什么？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["你在睡觉。","我来的时候，你在睡觉。"],"goiY":"bạn đang ngủ"},{"kieu":"hoi","dong":[{"ai":"A","o":true,"truoc":"","sau":"的时候，你在哪儿？"},{"ai":"B","t":"我在公司。"}],"dap":["我给你打电话的时候，你在哪儿？"],"goiY":"lúc tôi gọi điện thoại"},{"kieu":"dich","vn":"Hồi nhỏ, tôi không thích uống sữa.","dap":["小的时候，我不喜欢喝牛奶。"]},{"kieu":"dich","vn":"Lúc ốm, bạn phải uống thuốc và nghỉ ngơi.","dap":["生病的时候，你要吃药，要休息。"]}]}]},{"so":"4.3","ten":"时间副词“已经”","tenVn":"Phó từ chỉ thời gian “已经” (已经……了)","cauTruc":["主语 + 已经 + 动词 (+ 宾语) + 了","主语 + 已经 + 形容词 + 了","已经 + 数量短语 + 了（已经十点了、已经三年了）","Phủ định (KHÔNG dùng 已经): 主语 + 还没(有) + 动词 (+ 呢)","Nghi vấn: ……已经……了吗？／……已经……了没有？"],"giaiThich":"“已经” nghĩa là \"đã … rồi“, dùng để nói sự việc đã hoàn thành hoặc đã đạt tới một mốc thời gian, số lượng nào đó. Nó là phó từ nên phải đứng SAU chủ ngữ, TRƯỚC động từ hoặc tính từ; cuối câu hầu như luôn có 了 đi kèm thành cặp 已经……了. Khi muốn nói ngược lại — ”chưa … đâu\" — các em không được phủ định 已经, mà phải đổi hẳn sang 还没……呢.","viDu":[{"zh":"我已经吃了。","py":"Wǒ yǐjīng chī le.","vn":"Tôi ăn rồi."},{"zh":"他已经下班了，不在公司。","py":"Tā yǐjīng xiàbān le, bú zài gōngsī.","vn":"Anh ấy tan làm rồi, không có ở công ty."},{"zh":"药我已经吃了，现在好一点儿了。","py":"Yào wǒ yǐjīng chī le, xiànzài hǎo yìdiǎnr le.","vn":"Thuốc tôi đã uống rồi, giờ đỡ hơn một chút rồi."},{"zh":"已经十点了，我们快走吧。","py":"Yǐjīng shí diǎn le, wǒmen kuài zǒu ba.","vn":"Đã 10 giờ rồi, chúng ta đi nhanh thôi."},{"zh":"你吃了吗？——我还没吃呢。","py":"Nǐ chī le ma?","vn":"Wǒ hái méi chī ne. — Bạn ăn chưa? — Tôi chưa ăn đâu."}],"loi":[{"sai":"我已经吃饭。","why":"tiếng Việt \"tôi đã ăn cơm\" không có từ nào tương ứng với 了 ở cuối, học sinh dịch từng chữ nên bỏ mất 了; 已经 gần như luôn cần 了 đi kèm.","dung":"我已经吃饭了。"},{"sai":"我已经没吃饭。","why":"dịch máy móc \"tôi đã chưa ăn cơm\"; 已经 không thể kết hợp với phủ định 没, phải chuyển sang 还没……呢.","dung":"我还没吃饭呢。"},{"sai":"已经他下班了。","why":"đặt phó từ trước chủ ngữ theo trật tự tiếng Việt \"đã anh ấy…\" (thực ra là do bắt chước vị trí trạng ngữ đầu câu); 已经 phải đứng sau chủ ngữ.","dung":"他已经下班了。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["我已经吃","。"],"dap":[["了"]],"chon":["了","的"]},{"kieu":"dien","phan":["他","下班了，不在公司。"],"dap":[["已经"]],"chon":["已经","还"]},{"kieu":"dien","phan":["","十点了，我们快走吧。"],"dap":[["已经"]],"chon":["已经","有点儿"]},{"kieu":"dien","phan":["你吃了吗？——我","没吃呢。"],"dap":[["还"]],"chon":["已经","还"]},{"kieu":"dien","phan":["药我已经吃","，现在好一点儿了。"],"dap":[["了"]],"chon":["了","已经","还"]},{"kieu":"dien","phan":["他来了吗？——他","。"],"dap":[["已经来了"]],"chon":["已经来了","已经没来"]}]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["我","了","已经","吃"],"dap":["我已经吃了。"]},{"kieu":"xep","manh":["他","已经","了","下班"],"dap":["他已经下班了。"]},{"kieu":"xep","manh":["了","已经","十点","我们","走","快","吧"],"dap":["已经十点了，我们快走吧。"]},{"kieu":"xep","manh":["我","呢","还","吃","没"],"dap":["我还没吃呢。"]},{"kieu":"xep","manh":["这个","我","已经","了","知道"],"dap":["这个我已经知道了。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你吃饭了吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我已经吃了。"],"goiY":"đã ăn rồi"},{"kieu":"hoi","dong":[{"ai":"A","t":"他在公司吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["他已经下班了。"],"goiY":"anh ấy tan làm rồi"},{"kieu":"dich","vn":"Đã 8 giờ rồi, bạn sao vẫn chưa đi làm?","dap":["已经八点了，你怎么还不去上班？"]},{"kieu":"dich","vn":"Tôi uống thuốc rồi, nhưng vẫn hơi khó chịu.","dap":["我已经吃药了，可是还有点儿不舒服。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-5.html"] = [{"so":"5.1","ten":"副词“就”","tenVn":"Phó từ “就”","cauTruc":["主语 + 就 + 动词 / 形容词 (+ 其他)","Câu cầu khiến chọn lựa: 就 + 动词 + 宾语 + 吧（就买这件吧。）","Nhấn mạnh \"chính là, ngay ở\": 就 + 在/是 + …（他就在那儿。／我就是他妈妈。）","Nhấn mạnh sớm/nhanh: 主语 + 时间词 + 就 + 动词 + 了（他八点就到了。）","Vị trí: 就 là phó từ, luôn đứng SAU chủ ngữ (hoặc sau trạng ngữ thời gian) và TRƯỚC động từ."],"giaiThich":"Ở trình độ HSK2, các em cần nắm ba nét nghĩa của 就. Thứ nhất, nhấn mạnh SỰ LỰA CHỌN đã quyết định — \"thôi thì … vậy, cứ … đi“: 就买这件吧 (Thôi mua chiếc này đi), thường đi với 吧 ở cuối câu. Thứ hai, nghĩa ”chỉ, chính, ngay“: 我就喜欢这个颜色 (tôi chỉ thích màu này thôi), 你的手表就在桌子上 (đồng hồ của bạn ở ngay trên bàn kìa). Thứ ba, nhấn mạnh sự việc xảy ra SỚM hoặc NHANH hơn dự tính: 他八点就到公司了 (mới 8 giờ anh ấy đã tới công ty rồi). Phân biệt nhanh với 才: 就 là ”mới … mà đã …“ (sớm, nhanh, người nói thấy sớm); 才 là ”mãi … mới …\" (muộn, chậm, người nói thấy muộn). So sánh: 他七点就来了 (7 giờ đã đến — sớm) ≠ 他九点才来 (9 giờ mới đến — muộn). Lưu ý thêm: câu có 就 thường có 了 ở cuối, còn câu có 才 thì thường KHÔNG dùng 了.","viDu":[{"zh":"就买这件吧。","py":"Jiù mǎi zhè jiàn ba.","vn":"Thôi mua chiếc này đi."},{"zh":"我就喜欢这个颜色。","py":"Wǒ jiù xǐhuan zhège yánsè.","vn":"Tôi chỉ thích màu này thôi."},{"zh":"他八点就到公司了。","py":"Tā bā diǎn jiù dào gōngsī le.","vn":"Mới 8 giờ anh ấy đã tới công ty rồi."},{"zh":"你别找了，你的手表就在桌子上。","py":"Nǐ bié zhǎo le, nǐ de shǒubiǎo jiù zài zhuōzi shang.","vn":"Đừng tìm nữa, đồng hồ của bạn ở ngay trên bàn kìa."},{"zh":"他八点就来了，我九点才来。","py":"Tā bā diǎn jiù lái le, wǒ jiǔ diǎn cái lái.","vn":"Anh ấy 8 giờ đã đến rồi, tôi 9 giờ mới đến."}],"loi":[{"sai":"就我喜欢这个颜色。（ý muốn nói \"tôi chỉ thích màu này\"）","why":"tiếng Việt nói \"chỉ tôi thích…\" / \"tôi chỉ thích…\" đều được, học sinh bê \"chỉ“ lên đầu câu; nhưng 就 phải đứng sau chủ ngữ, đặt trước chủ ngữ thì nghĩa đổi thành ”chỉ có mình tôi thích\".","dung":"我就喜欢这个颜色。"},{"sai":"他七点才来了，很早。","why":"lẫn 就 và 才 vì tiếng Việt đều dịch là \"mới\"; nhưng \"mới 7 giờ đã đến\" (sớm) phải dùng 就 + 了.","dung":"他七点就来了，很早。"},{"sai":"我们就吃饭在这儿吧。","why":"đặt 就 sai vị trí, tách khỏi thành phần nó nhấn mạnh; 就 phải đứng ngay trước cụm 在这儿吃饭.","dung":"我们就在这儿吃饭吧。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["这件不太贵，","买这件吧。"],"dap":[["就"]],"chon":["就","还"]},{"kieu":"dien","phan":["我","喜欢这个颜色，别的都不喜欢。"],"dap":[["就"]],"chon":["就","有点儿"]},{"kieu":"dien","phan":["他八点","到公司了，我九点","到。"],"dap":[["就"],["才"]],"chon":["就","才"]},{"kieu":"dien","phan":["你别找了，你的手表","在桌子上。"],"dap":[["就"]],"chon":["就","还"]},{"kieu":"dien","phan":["我们","在这儿吃饭吧。"],"dap":[["就"]],"chon":["就","已经"]},{"kieu":"dien","phan":["他七点","来了，很早。"],"dap":[["就"]],"chon":["就","才"]}]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["就","这件","买","吧"],"dap":["就买这件吧。"]},{"kieu":"xep","manh":["我","就","这个","喜欢","颜色"],"dap":["我就喜欢这个颜色。"]},{"kieu":"xep","manh":["他","就","八点","到","了","公司"],"dap":["他八点就到公司了。"]},{"kieu":"xep","manh":["你的","就","手表","在","上","桌子"],"dap":["你的手表就在桌子上。"]},{"kieu":"xep","manh":["我们","就","吃饭","在这儿","吧"],"dap":["我们就在这儿吃饭吧。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"这两件你买哪件？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["这件便宜，就买这件吧。"],"goiY":"chiếc này rẻ, thôi mua chiếc này đi"},{"kieu":"hoi","dong":[{"ai":"A","t":"你喜欢什么颜色的衣服？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我就喜欢这个颜色。"],"goiY":"tôi chỉ thích màu này"},{"kieu":"dich","vn":"Anh ấy 7 giờ đã đi làm rồi, tôi 9 giờ mới đến công ty.","dap":["他七点就去上班了，我九点才到公司。"]},{"kieu":"dich","vn":"Chúng ta ăn cơm ngay ở đây đi, đừng đi nữa.","dap":["我们就在这儿吃饭吧，别走了。"]}]}]},{"so":"5.2","ten":"语气副词“还”（1）","tenVn":"Phó từ ngữ khí “还” (1)","cauTruc":["主语 + 还 + 动词 / 形容词（还在睡觉、还很忙）","主语 + 还 + 能愿动词 + 动词（还想买、还要吃）","主语 + 动词了……，还 + 动词了……（表示\"còn, thêm nữa\"）","还 + 可以 / 不错 → đánh giá mức trung bình: \"cũng tạm được\"","Phủ định của \"đã … chưa\": 还没(有) + 动词 (+ 呢)"],"giaiThich":"“还” ở bài này có hai nét nghĩa chính. Một là \"còn, vẫn“ — chỉ trạng thái, hành động vẫn tiếp tục kéo dài: 他还在睡觉 (anh ấy vẫn đang ngủ). Hai là ”còn, thêm nữa“ — bổ sung thêm người, vật, việc: 我还想买一件 (tôi còn muốn mua một chiếc nữa). Đặc biệt các em phải nhớ cụm 还可以: đây là cách đánh giá lịch sự, nghĩa là ”cũng tạm được, cũng được, không tệ\" — không quá tốt cũng không tệ, tuyệt đối không dịch là \"vẫn có thể“. Khi người bán hỏi 这件怎么样？, trả lời 还可以 tức là ”cũng tạm, cũng ổn\". 还 là phó từ nên đứng sau chủ ngữ, trước động từ/tính từ.","viDu":[{"zh":"这件还可以。","py":"Zhè jiàn hái kěyǐ.","vn":"Chiếc này cũng tạm được."},{"zh":"他还在睡觉。","py":"Tā hái zài shuìjiào.","vn":"Anh ấy vẫn đang ngủ."},{"zh":"我还想买一件。","py":"Wǒ hái xiǎng mǎi yí jiàn.","vn":"Tôi còn muốn mua thêm một chiếc nữa."},{"zh":"我吃了两个鸡蛋，还喝了一杯牛奶。","py":"Wǒ chī le liǎng gè jīdàn, hái hē le yì bēi niúnǎi.","vn":"Tôi ăn hai quả trứng, còn uống thêm một cốc sữa."},{"zh":"已经八点了，他还没来。","py":"Yǐjīng bā diǎn le, tā hái méi lái.","vn":"Đã 8 giờ rồi mà anh ấy vẫn chưa đến."}],"loi":[{"sai":"这件衣服可以还。","why":"tiếng Việt nói \"chiếc áo này cũng được\", chữ \"cũng/nữa\" hay đứng cuối, học sinh đẩy 还 ra sau; 还 là phó từ, bắt buộc đứng trước 可以.","dung":"这件衣服还可以。"},{"sai":"这件还可以，我很喜欢，太好了！","why":"hiểu sai 还可以 thành \"rất tốt/vẫn có thể“; 还可以 chỉ mức ”tàm tạm\", dùng chung với 太好了 là mâu thuẫn ngữ nghĩa.","dung":"这件很好，我很喜欢，太好了！（hoặc giữ 还可以 thì bỏ 太好了）"},{"sai":"他还没来了。","why":"quen dùng 了 ở cuối câu; cấu trúc 还没…… không đi với 了, nếu cần thì thêm 呢.","dung":"他还没来。／他还没来呢。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["这件","可以，不太贵。"],"dap":[["还"]],"chon":["还","很"]},{"kieu":"dien","phan":["他","在睡觉，你别叫他。"],"dap":[["还"]],"chon":["还","已经"]},{"kieu":"dien","phan":["我买了一件衣服，","买了一个手表。"],"dap":[["还"]],"chon":["还","就"]},{"kieu":"dien","phan":["已经八点了，他","没来。"],"dap":[["还"]],"chon":["还","已经"]},{"kieu":"dien","phan":["我","想喝一杯牛奶。"],"dap":[["还"]],"chon":["还","有点儿"]},{"kieu":"dien","phan":["这个菜怎么样？——","。"],"dap":[["还可以"]],"chon":["还可以","可以还"]}]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["这件","可以","还"],"dap":["这件还可以。"]},{"kieu":"xep","manh":["他","还","睡觉","在"],"dap":["他还在睡觉。"]},{"kieu":"xep","manh":["我","还","买","想","一件"],"dap":["我还想买一件。"]},{"kieu":"xep","manh":["我","两个","吃了","鸡蛋","还","一杯","喝了","牛奶"],"dap":["我吃了两个鸡蛋，还喝了一杯牛奶。"]},{"kieu":"xep","manh":["了","已经","八点","他","还","来","没"],"dap":["已经八点了，他还没来。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"这件衣服怎么样？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["还可以，就是有点儿贵。"],"goiY":"cũng tạm được, chỉ hơi đắt"},{"kieu":"hoi","dong":[{"ai":"A","t":"他起床了吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["他还在睡觉。"],"goiY":"vẫn đang ngủ"},{"kieu":"dich","vn":"Tôi mua một chiếc áo, còn mua thêm một cái đồng hồ.","dap":["我买了一件衣服，还买了一个手表。"]},{"kieu":"dich","vn":"Đã 9 giờ rồi, sao anh ấy vẫn chưa đến công ty?","dap":["已经九点了，他怎么还没到公司？"]}]}]},{"so":"5.3","ten":"程度副词“有点儿”","tenVn":"Phó từ chỉ mức độ “有点儿”","cauTruc":["主语 + 有点儿 + 形容词（这件有点儿贵。）","主语 + 有点儿 + 不 + 形容词（我有点儿不高兴。）","主语 + 有点儿 + 心理动词（有点儿累／有点儿不舒服）","Phân biệt với 一点儿:","- 有点儿 + 形容词（đứng TRƯỚC tính từ, mang sắc thái không hài lòng）","- 形容词 + 一点儿（đứng SAU tính từ, dùng khi so sánh hoặc yêu cầu）：便宜一点儿、快一点儿","- 一点儿 + 名词：一点儿水、一点儿牛奶"],"giaiThich":"“有点儿” nghĩa là \"hơi, có chút“, đứng trước tính từ và mang sắc thái KHÔNG VỪA Ý của người nói: 有点儿贵、有点儿累、有点儿不舒服. Vì vậy ta hầu như không nói 有点儿便宜、有点儿好 — vì rẻ và tốt là điều đáng mừng, không có gì để phàn nàn. Các em Việt Nam hay nhầm 有点儿 với 一点儿 vì tiếng Việt dịch cả hai là ”một chút/hơi\". Mẹo nhớ của cô: 有点儿 ĐỨNG TRƯỚC tính từ và dùng để CHÊ; 一点儿 ĐỨNG SAU tính từ và dùng để YÊU CẦU hoặc SO SÁNH. So sánh cặp câu: 这件有点儿贵 (chiếc này hơi đắt — chê) / 便宜一点儿，好吗？ (rẻ hơn chút được không? — yêu cầu).","viDu":[{"zh":"这件有点儿贵。","py":"Zhè jiàn yǒudiǎnr guì.","vn":"Chiếc này hơi đắt."},{"zh":"我今天有点儿累。","py":"Wǒ jīntiān yǒudiǎnr lèi.","vn":"Hôm nay tôi hơi mệt."},{"zh":"他有点儿不高兴。","py":"Tā yǒudiǎnr bù gāoxìng.","vn":"Anh ấy hơi không vui."},{"zh":"这个羊肉有点儿贵，那个便宜一点儿。","py":"Zhège yángròu yǒudiǎnr guì, nàge piányi yìdiǎnr.","vn":"Thịt dê này hơi đắt, cái kia rẻ hơn một chút."},{"zh":"我有点儿不舒服，想休息一下。","py":"Wǒ yǒudiǎnr bù shūfu, xiǎng xiūxi yíxià.","vn":"Tôi hơi khó chịu, muốn nghỉ một lát."}],"loi":[{"sai":"这件衣服一点儿贵。","why":"tiếng Việt \"chiếc áo này hơi đắt / đắt một chút\" khiến học sinh chọn nhầm 一点儿; 一点儿 không đứng trước tính từ.","dung":"这件衣服有点儿贵。"},{"sai":"服务员，便宜有点儿，好吗？","why":"đảo ngược cặp trên — khi mặc cả, yêu cầu \"rẻ hơn chút\" phải dùng 形容词 + 一点儿.","dung":"服务员，便宜一点儿，好吗？"},{"sai":"我今天有点儿很累。","why":"học sinh nhớ quy tắc “tính từ làm vị ngữ phải có 很” nên thêm cả 很 lẫn 有点儿; hai phó từ mức độ không dùng chồng lên nhau.","dung":"我今天有点儿累。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["这件","贵，我不买了。"],"dap":[["有点儿"]],"chon":["有点儿","一点儿"]},{"kieu":"dien","phan":["服务员，便宜","，好吗？"],"dap":[["一点儿"]],"chon":["有点儿","一点儿"]},{"kieu":"dien","phan":["我今天","累，想休息。"],"dap":[["有点儿"]],"chon":["有点儿","一点儿"]},{"kieu":"dien","phan":["我想喝","牛奶。"],"dap":[["一点儿"]],"chon":["有点儿","一点儿"]},{"kieu":"dien","phan":["他今天","不高兴。"],"dap":[["有点儿"]],"chon":["有点儿","一点儿"]},{"kieu":"dien","phan":["你走得太慢了，快","！"],"dap":[["一点儿"]],"chon":["有点儿","一点儿"]}]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["这件","贵","有点儿"],"dap":["这件有点儿贵。"]},{"kieu":"xep","manh":["我","有点儿","今天","累"],"dap":["我今天有点儿累。"]},{"kieu":"xep","manh":["他","有点儿","高兴","不"],"dap":["他有点儿不高兴。"]},{"kieu":"xep","manh":["我","有点儿","舒服","不","想","一下","休息"],"dap":["我有点儿不舒服，想休息一下。"]},{"kieu":"xep","manh":["这个","有点儿","羊肉","贵","那个","一点儿","便宜"],"dap":["这个羊肉有点儿贵，那个便宜一点儿。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"这件衣服你买吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["有点儿贵，我不买了。"],"goiY":"hơi đắt, tôi không mua nữa"},{"kieu":"hoi","dong":[{"ai":"A","t":"你怎么了？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我有点儿不舒服，想休息一下。"],"goiY":"tôi hơi khó chịu, muốn nghỉ một lát"},{"kieu":"dich","vn":"Món thịt dê này hơi đắt, có món nào rẻ hơn một chút không?","dap":["这个羊肉有点儿贵，有没有便宜一点儿的？"]},{"kieu":"dich","vn":"Hôm nay tôi hơi mệt, vì công việc rất bận.","dap":["我今天有点儿累，因为工作很忙。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-6.html"] = [{"so":"6.1","ten":"疑问代词“怎么”","tenVn":"Đại từ nghi vấn “怎么”","cauTruc":["Hỏi CÁCH THỨC: 主语 + 怎么 + 动词 (+ 宾语)？（这个字怎么读？／怎么走？）","Hỏi NGUYÊN NHÂN (kèm sắc thái ngạc nhiên): 主语 + 怎么 + 不/没 + 动词 + 了？（你怎么不吃了？）","Hỏi tình trạng: 主语 + 怎么了？（你怎么了？）","Lưu ý: câu đã có 怎么 thì KHÔNG thêm 吗 ở cuối."],"giaiThich":"“怎么” có hai công dụng ở HSK2. Thứ nhất là hỏi CÁCH THỨC, tương đương \"như thế nào, làm sao“: 这个字怎么读？ (Chữ này đọc thế nào?). Thứ hai là hỏi NGUYÊN NHÂN, tương đương ”sao mà, sao lại\": 你怎么不吃了？ (Sao bạn không ăn nữa?). Ở nét nghĩa thứ hai, 怎么 khác 为什么 ở chỗ nó mang sắc thái NGẠC NHIÊN, khó hiểu, đôi khi là quan tâm hoặc trách nhẹ; còn 为什么 chỉ hỏi lý do một cách trung tính. Vì bản thân 怎么 đã là từ để hỏi nên cuối câu không được thêm 吗.","viDu":[{"zh":"你怎么不吃了？","py":"Nǐ zěnme bù chī le?","vn":"Sao bạn không ăn nữa?"},{"zh":"这个字怎么读？","py":"Zhège zì zěnme dú?","vn":"Chữ này đọc như thế nào?"},{"zh":"这个菜怎么做？","py":"Zhège cài zěnme zuò?","vn":"Món này làm thế nào?"},{"zh":"你怎么了？是不是生病了？","py":"Nǐ zěnme le? Shì bu shì shēngbìng le?","vn":"Bạn sao thế? Có phải ốm rồi không?"},{"zh":"他怎么还没来？已经八点了。","py":"Tā zěnme hái méi lái? Yǐjīng bā diǎn le.","vn":"Sao anh ấy vẫn chưa đến? Đã 8 giờ rồi."}],"loi":[{"sai":"你怎么不吃了吗？","why":"học sinh quen công thức “câu hỏi phải có 吗” nên thêm 吗 vào cả câu đã có từ để hỏi; 怎么 và 吗 không dùng chung.","dung":"你怎么不吃了？"},{"sai":"怎么你昨天没来？","why":"tiếng Việt nói \"Sao hôm qua bạn không đến?\" — từ \"sao\" đứng đầu câu, học sinh bê nguyên trật tự; 怎么 phải đứng sau chủ ngữ.","dung":"你昨天怎么没来？"},{"sai":"你怎么？ (muốn hỏi \"Bạn sao thế?\")","why":"dịch sát \"bạn sao\"; hỏi tình trạng phải dùng trọn cụm 怎么了.","dung":"你怎么了？"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["你","不吃了？是不是不舒服？"],"dap":[["怎么"]],"chon":["怎么","什么"]},{"kieu":"dien","phan":["这个字","读？"],"dap":[["怎么"]],"chon":["怎么","怎么样"]},{"kieu":"dien","phan":["你","了？是不是生病了？"],"dap":[["怎么"]],"chon":["怎么","为什么"]},{"kieu":"dien","phan":["他","还没来？已经八点了。"],"dap":[["怎么"]],"chon":["怎么","哪儿"]},{"kieu":"dien","phan":["这个菜","做？"],"dap":[["怎么"]],"chon":["怎么","多少"]},{"kieu":"dien","phan":["你怎么昨天没来","？"],"dap":[["不加"]],"chon":["吗","不加"],"giai":"你昨天怎么没来？"}]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["你","怎么","了","吃","不"],"dap":["你怎么不吃了？"]},{"kieu":"xep","manh":["这个","怎么","读","字"],"dap":["这个字怎么读？"]},{"kieu":"xep","manh":["你","了","怎么"],"dap":["你怎么了？"]},{"kieu":"xep","manh":["他","怎么","没","还","来"],"dap":["他怎么还没来？"]},{"kieu":"xep","manh":["你","昨天","怎么","来","没"],"dap":["你昨天怎么没来？"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","o":true,"truoc":"","sau":"？"},{"ai":"B","t":"因为我不太舒服，所以没吃。"}],"dap":["你怎么不吃了？"],"goiY":"sao bạn không ăn nữa"},{"kieu":"hoi","dong":[{"ai":"A","o":true,"truoc":"这个字","sau":"？"},{"ai":"B","t":"读 \"máng\"，“忙”。"}],"dap":["这个字怎么读？"]},{"kieu":"dich","vn":"Bạn sao thế? Có phải ốm rồi không? Nhanh đi uống thuốc đi.","dap":["你怎么了？是不是生病了？快去吃药吧。"]},{"kieu":"dich","vn":"Đã 9 giờ rồi, sao anh ấy vẫn chưa đến công ty?","dap":["已经九点了，他怎么还没到公司？"]}]}]},{"so":"6.2","ten":"量词的重叠","tenVn":"Lượng từ lặp lại (个个、件件、天天、次次…)","cauTruc":["量词 + 量词 + 都 + 动词 / 形容词","AA式：个个、件件、天天、次次、年年、人人、家家","Làm chủ ngữ: 件件都很贵。","Làm định ngữ đứng sau danh từ: 这儿的衣服件件都很贵。","Làm trạng ngữ (với lượng từ thời gian): 他天天都来。","Lưu ý: khi lượng từ đã lặp thì KHÔNG dùng 一 hoặc số từ ở trước; vế sau thường có 都."],"giaiThich":"Lượng từ lặp lại mang nghĩa \"mỗi … đều …, cái nào cũng …“, nhấn mạnh tính toàn bộ, không trừ một cái nào. 天天 = mỗi ngày, 件件 = cái áo nào cũng, 个个 = người nào/cái nào cũng, 次次 = lần nào cũng. Vì nghĩa là ”toàn bộ\" nên phía sau hầu như luôn đi với 都. Về ngữ dụng, cách nói này mang sắc thái nhấn mạnh, cảm thán, sinh động hơn nhiều so với nói 每天 hay 所有的; người Trung Quốc rất hay dùng khi khen hoặc than phiền.","viDu":[{"zh":"他天天都来。","py":"Tā tiāntiān dōu lái.","vn":"Ngày nào anh ấy cũng đến."},{"zh":"这儿的衣服件件都很贵。","py":"Zhèr de yīfu jiànjiàn dōu hěn guì.","vn":"Quần áo ở đây cái nào cũng đắt."},{"zh":"我们公司的人个个都很忙。","py":"Wǒmen gōngsī de rén gègè dōu hěn máng.","vn":"Người ở công ty chúng tôi ai cũng rất bận."},{"zh":"他次次都是第一个到公司的。","py":"Tā cìcì dōu shì dì-yī gè dào gōngsī de.","vn":"Lần nào anh ấy cũng là người đầu tiên đến công ty."},{"zh":"妈妈做的菜个个都好吃。","py":"Māma zuò de cài gègè dōu hǎochī.","vn":"Món nào mẹ nấu cũng ngon."}],"loi":[{"sai":"他一天天都来。","why":"học sinh giữ lại 一 theo thói quen “一天” rồi mới lặp; lượng từ lặp không được kèm số từ.","dung":"他天天都来。"},{"sai":"这儿的衣服件件很贵。","why":"tiếng Việt \"cái nào cũng đắt\" — chữ \"cũng“ bị bỏ quên khi dịch; lượng từ lặp cần 都 để hoàn chỉnh ý ”toàn bộ\".","dung":"这儿的衣服件件都很贵。"},{"sai":"件件衣服都很贵。（trong ngữ cảnh chỉ nhóm áo cụ thể đã nhắc tới）","why":"đặt cụm lặp trước danh từ như tiếng Việt \"từng chiếc áo\"; ở HSK2 nên đặt sau danh từ và làm chủ ngữ.","dung":"这儿的衣服件件都很贵。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["他","都来。"],"dap":[["天天"]],"chon":["天天","一天"]},{"kieu":"dien","phan":["这儿的衣服","都很贵。"],"dap":[["件件"]],"chon":["件件","一件"]},{"kieu":"dien","phan":["我们公司的人","都很忙。"],"dap":[["个个"]],"chon":["个个","一个"]},{"kieu":"dien","phan":["他天天","来。"],"dap":[["都"]],"chon":["都","很"]},{"kieu":"dien","phan":["他","都是第一个到公司的。"],"dap":[["次次"]],"chon":["次次","一次"]},{"kieu":"dien","phan":["妈妈做的菜","都好吃。"],"dap":[["个个"]],"chon":["个个","个"]}]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["他","都","天天","来"],"dap":["他天天都来。"]},{"kieu":"xep","manh":["这儿的","件件","衣服","都","贵","很"],"dap":["这儿的衣服件件都很贵。"]},{"kieu":"xep","manh":["我们公司的","个个","人","都","忙","很"],"dap":["我们公司的人个个都很忙。"]},{"kieu":"xep","manh":["他","次次","都","第一个","是","到","公司","的"],"dap":["他次次都是第一个到公司的。"]},{"kieu":"xep","manh":["妈妈","的","做","菜","个个","都","好吃"],"dap":["妈妈做的菜个个都好吃。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"他常来吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["他天天都来。"],"goiY":"ngày nào anh ấy cũng đến"},{"kieu":"hoi","dong":[{"ai":"A","t":"这儿的衣服怎么样？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["这儿的衣服件件都很贵，我不买了。"],"goiY":"cái nào cũng đắt, tôi không mua"},{"kieu":"dich","vn":"Người ở công ty chúng tôi ai cũng rất bận, ngày nào cũng tan làm rất muộn.","dap":["我们公司的人个个都很忙，天天都很晚下班。"]},{"kieu":"dich","vn":"Món mẹ nấu món nào cũng ngon, tôi ngày nào cũng ăn ba bát cơm.","dap":["妈妈做的菜个个都好吃，我天天都吃三碗饭。"]}]}]},{"so":"6.3","ten":"关联词“因为……，所以……”","tenVn":"Cặp liên từ “因为……，所以……”","cauTruc":["因为 + 原因（nguyên nhân），所以 + 结果（kết quả）。","主语 + 因为 + 原因，所以 + 结果。（因为 có thể đứng sau chủ ngữ: 他因为生病了，所以没来。）","Có thể lược một vế:","- Lược 因为：我不太舒服，所以没吃。","- Lược 所以：因为我不太舒服，没吃。","- Vế sau hỏi lý do: 你怎么不吃了？——因为我不太舒服。"],"giaiThich":"“因为……，所以……” tương đương \"vì … nên …“ trong tiếng Việt: vế 因为 nêu nguyên nhân, đứng trước; vế 所以 nêu kết quả, đứng sau. Trật tự này cố định, không được đảo. Điểm rất khác tiếng Việt là tiếng Trung cho phép dùng ĐỦ CẢ HAI từ nối trong một câu — điều mà tiếng Việt chuẩn hay tránh (”vì … nên …\" thì được, nhưng nhiều em lại dịch thành hai câu rời). Nếu hai vế cùng chủ ngữ, chủ ngữ ở vế sau thường được lược: 因为我不太舒服，所以没吃。","viDu":[{"zh":"因为我不太舒服，所以没吃。","py":"Yīnwèi wǒ bú tài shūfu, suǒyǐ méi chī.","vn":"Vì tôi hơi khó chịu nên không ăn."},{"zh":"因为下雨，所以我们没去。","py":"Yīnwèi xià yǔ, suǒyǐ wǒmen méi qù.","vn":"Vì trời mưa nên chúng tôi không đi."},{"zh":"因为这件衣服有点儿贵，所以我没买。","py":"Yīnwèi zhè jiàn yīfu yǒudiǎnr guì, suǒyǐ wǒ méi mǎi.","vn":"Vì chiếc áo này hơi đắt nên tôi không mua."},{"zh":"他因为生病了，所以今天没来上班。","py":"Tā yīnwèi shēngbìng le, suǒyǐ jīntiān méi lái shàngbān.","vn":"Vì anh ấy ốm nên hôm nay không đến làm."},{"zh":"因为工作很忙，所以他天天都很累。","py":"Yīnwèi gōngzuò hěn máng, suǒyǐ tā tiāntiān dōu hěn lèi.","vn":"Vì công việc rất bận nên ngày nào anh ấy cũng rất mệt."}],"loi":[{"sai":"因为我生病了，我没去上班。","why":"tiếng Việt thường chỉ dùng một từ nối (\"Vì tôi ốm, tôi không đi làm\"), nên học sinh bỏ mất vế 所以; tiếng Trung ở trình độ sơ cấp nên dùng đủ cặp.","dung":"因为我生病了，所以我没去上班。"},{"sai":"所以他生病了，因为今天没来上班。","why":"đảo ngược quan hệ nhân – quả do dịch ngược từ câu tiếng Việt \"Anh ấy hôm nay không đi làm, vì bị ốm\"; 因为 luôn đi với nguyên nhân, 所以 luôn đi với kết quả.","dung":"因为他生病了，所以今天没来上班。"},{"sai":"因为他生病了，但是今天没来上班。","why":"nhớ nhầm cặp liên từ, ghép 因为 với từ nối chỉ quan hệ đối lập.","dung":"因为他生病了，所以今天没来上班。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["","我不太舒服，所以没吃。"],"dap":[["因为"]],"chon":["因为","所以"]},{"kieu":"dien","phan":["因为下雨，","我们没去。"],"dap":[["所以"]],"chon":["所以","但是"]},{"kieu":"dien","phan":["","这件衣服有点儿贵，","我没买。"],"dap":[["因为"],["所以"]],"chon":["因为","所以"]},{"kieu":"dien","phan":["他因为生病了，","今天没来上班。"],"dap":[["所以"]],"chon":["所以","还"]},{"kieu":"dien","phan":["因为工作很忙，所以他","都很累。"],"dap":[["天天"]],"chon":["天天","一天"]},{"kieu":"dien","phan":["你怎么不吃了？——","我不太舒服。"],"dap":[["因为"]],"chon":["因为","所以"]}]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["因为","不太","我","舒服","所以","吃","没"],"dap":["因为我不太舒服，所以没吃。"]},{"kieu":"xep","manh":["因为","下雨","所以","我们","去","没"],"dap":["因为下雨，所以我们没去。"]},{"kieu":"xep","manh":["因为","这件","有点儿","衣服","贵","所以","我","买","没"],"dap":["因为这件衣服有点儿贵，所以我没买。"]},{"kieu":"xep","manh":["他","因为","了","生病","所以","今天","来","没","上班"],"dap":["他因为生病了，所以今天没来上班。"]},{"kieu":"xep","manh":["因为","很","工作","忙","所以","他","天天","都","累","很"],"dap":["因为工作很忙，所以他天天都很累。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你怎么不吃了？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["因为我不太舒服，所以没吃。"],"goiY":"vì tôi hơi khó chịu nên không ăn"},{"kieu":"hoi","dong":[{"ai":"A","t":"你怎么没买那件衣服？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["因为有点儿贵，所以我没买。"],"goiY":"vì hơi đắt nên tôi không mua"},{"kieu":"dich","vn":"Vì hôm nay anh ấy ốm nên không đến công ty, cũng không gọi điện cho tôi.","dap":["因为他今天生病了，所以没来公司，也没给我打电话。"]},{"kieu":"dich","vn":"Vì công việc rất bận nên ngày nào tôi cũng tan làm rất muộn, rất mệt.","dap":["因为工作很忙，所以我天天都很晚下班，很累。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-7.html"] = [{"so":"7.1","ten":"语气副词“还”（2）","tenVn":"Phó từ ngữ khí “还” (2)","cauTruc":["Khẳng định: 主语 + 还 + 在/动词短语 / 形容词短语","→ 他还在工作。","Phủ định (việc chưa xảy ra): 主语 + 还没(有) + 动词 （KHÔNG dùng 了）","→ 我还没下班。","Phủ định (trạng thái/ý muốn): 主语 + 还不 + 动词/形容词","→ 他还不想回家。","Nghi vấn: 主语 + 还 + …… + 吗？ / 怎么还不(没)……？","→ 你还在公司吗？／你怎么还不休息？"],"giaiThich":"“还” ở bài này mang nghĩa \"vẫn, vẫn còn, còn\" — nó cho biết một hành động hoặc một trạng thái đã bắt đầu từ trước và **đến thời điểm nói vẫn tiếp diễn**, chưa kết thúc, chưa thay đổi. Vì thế “还” rất hay đi cùng những từ chỉ thời gian đã muộn hoặc đã lâu như 已经、十二点了、这么晚了 để tạo sắc thái ngạc nhiên: \"muộn thế rồi mà vẫn còn…“. Các em nhớ kỹ một điều: khi nói việc **chưa xảy ra**, tiếng Trung bắt buộc dùng 还没(有) chứ không dùng 还不 — 还不 chỉ dùng cho ý muốn, thói quen hay tính chất. Về vị trí, ”还\" là phó từ nên luôn đứng **sau chủ ngữ, trước động từ / hình dung từ**, không bao giờ đứng đầu câu. Trong khẩu ngữ, câu có “还” rất hay kết thúc bằng trợ từ 呢 để nhấn mạnh thêm: 他还在睡觉呢。","viDu":[{"zh":"已经十一点了，他还在工作。","py":"Yǐjīng shíyī diǎn le, tā hái zài gōngzuò.","vn":"Đã 11 giờ rồi mà anh ấy vẫn còn đang làm việc."},{"zh":"我还没下班呢，你先吃饭吧。","py":"Wǒ hái méi xiàbān ne, nǐ xiān chīfàn ba.","vn":"Tôi vẫn chưa tan làm đâu, bạn ăn cơm trước đi."},{"zh":"这些题太多了，我还有十个没做完。","py":"Zhèxiē tí tài duō le, wǒ hái yǒu shí ge méi zuòwán.","vn":"Mấy bài này nhiều quá, tôi vẫn còn mười câu chưa làm xong."},{"zh":"十二点了，你怎么还不休息？","py":"Shí'èr diǎn le, nǐ zěnme hái bù xiūxi?","vn":"12 giờ rồi, sao bạn vẫn chưa đi nghỉ vậy?"},{"zh":"他的病还没好，今天不能上班。","py":"Tā de bìng hái méi hǎo, jīntiān bù néng shàngbān.","vn":"Bệnh của anh ấy vẫn chưa khỏi, hôm nay không đi làm được."}],"loi":[{"sai":"我还不下班。","why":"tiếng Việt nói \"tôi vẫn chưa tan làm“, học sinh lấy 不 dịch chữ ”chưa\"; nhưng việc chưa xảy ra phải phủ định bằng 没.","dung":"我还没下班。"},{"sai":"他还没来了。","why":"học sinh quen thêm 了 cho \"thì quá khứ\"; 没 và 了 không đi cùng nhau trong một vị ngữ.","dung":"他还没来。"},{"sai":"还他在睡觉呢。","why":"đặt phó từ đầu câu theo trật tự tiếng Việt \"vẫn còn anh ấy đang ngủ\"; 还 phải đứng sau chủ ngữ.","dung":"他还在睡觉呢。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["十点了，他","工作，太累了。"],"dap":[["还在"]]},{"kieu":"dien","phan":["我","吃饭呢，你等我一下。"],"dap":[["还在"]]},{"kieu":"dien","phan":["这些题我","做完，明天做吧。"],"dap":[["还没"]]},{"kieu":"dien","phan":["他","想去医院，他说他没有病。"],"dap":[["还不"]]},{"kieu":"dien","phan":["火车","来，我们","十分钟。"],"dap":[["还没"],["还有"]]},{"kieu":"dien","phan":["你怎么","睡觉？已经十二点了。"],"dap":[["还不"]]}],"huongDan":"Điền 还没 / 还不 / 还在 / 还有 vào chỗ trống.","chon":["还没","还不","还在","还有"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["还","在","他","公司","呢"],"dap":["他还在公司呢。"]},{"kieu":"xep","manh":["没","我","还","下班","呢"],"dap":["我还没下班呢。"]},{"kieu":"xep","manh":["这些","我","做完","题","没","还"],"dap":["这些题我还没做完。"]},{"kieu":"xep","manh":["不","怎么","你","还","休息"],"dap":["你怎么还不休息？"]},{"kieu":"xep","manh":["好","还","他的","没","病"],"dap":["他的病还没好。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你下班了吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我还没下班呢，我还有很多事儿。"],"goiY":"vẫn chưa tan làm, còn nhiều việc"},{"kieu":"hoi","dong":[{"ai":"A","t":"我们去吃饭，好吗？"},{"ai":"B","o":true,"truoc":"对不起，","sau":""}],"dap":["对不起，我还有两个题没做完。"],"goiY":"tôi vẫn còn hai bài chưa làm xong"},{"kieu":"dich","vn":"Muộn thế rồi mà sao anh vẫn chưa về nhà?","dap":["这么晚了，你怎么还不回家？"]},{"kieu":"dich","vn":"Bệnh của mẹ tôi vẫn chưa khỏi, hôm nay tôi không đi làm.","dap":["我妈妈的病还没好，今天我不上班。"]}]}]},{"so":"7.2","ten":"时间副词“就”","tenVn":"Phó từ chỉ thời gian “就”","cauTruc":["时间词 + 就 + 动词 + 了 （nhấn mạnh việc xảy ra SỚM）","→ 他七点就来公司了。","时间/条件 + 就 + 动词（短语） （nhấn mạnh việc xảy ra NGAY, NHANH）","→ 走路十分钟就到了。／我马上就来。","马上／一会儿／很快 + 就 + 动词","→ 我很快就做完了。","Phủ định: hầu như không phủ định trực tiếp “不就”; muốn nói ngược lại thì đổi cách diễn đạt (还没……)."],"giaiThich":"“就” là phó từ chỉ thời gian, mang hai sắc thái gần nhau: **sớm hơn dự kiến** và **ngay lập tức, rất nhanh**. Khi trước “就” có một từ chỉ thời điểm (七点、昨天、去年), người nói muốn nói \"mới … mà đã …“: 他七点就来了 = mới 7 giờ anh ấy đã đến rồi. Khi trước ”就\" là một khoảng thời gian ngắn hoặc một điều kiện, “就” nhấn mạnh \"chỉ cần … là …“: 十分钟就到了 = chỉ mười phút là tới. Vị trí của ”就“ cố định: **đứng ngay trước động từ**, sau từ chỉ thời gian; câu nói về việc đã xảy ra thường có thêm 了 ở cuối. Các em nhớ: ”就\" luôn đi với cảm giác \"nhanh/sớm/dễ\", nên không dùng cho việc muộn màng, chậm trễ.","viDu":[{"zh":"他七点就来公司了。","py":"Tā qī diǎn jiù lái gōngsī le.","vn":"Mới 7 giờ anh ấy đã đến công ty rồi."},{"zh":"我家离火车站很近，走路十分钟就到了。","py":"Wǒ jiā lí huǒchēzhàn hěn jìn, zǒulù shí fēnzhōng jiù dào le.","vn":"Nhà tôi rất gần ga tàu, đi bộ mười phút là tới."},{"zh":"你等我一下，我马上就来。","py":"Nǐ děng wǒ yíxià, wǒ mǎshàng jiù lái.","vn":"Bạn đợi tôi một chút, tôi đến ngay đây."},{"zh":"昨天我十点就睡觉了。","py":"Zuótiān wǒ shí diǎn jiù shuìjiào le.","vn":"Hôm qua mới 10 giờ tôi đã đi ngủ rồi."},{"zh":"这些题很容易，我很快就做完了。","py":"Zhèxiē tí hěn róngyì, wǒ hěn kuài jiù zuòwán le.","vn":"Mấy bài này rất dễ, tôi làm xong rất nhanh."}],"loi":[{"sai":"他就七点来公司了。","why":"dịch theo trật tự tiếng Việt \"anh ấy đã 7 giờ đến\"; 就 phải đứng SAU từ chỉ thời gian, ngay trước động từ.","dung":"他七点就来公司了。"},{"sai":"他七点就来公司。","why":"quên 了; câu nhấn mạnh việc đã xảy ra sớm cần có 了 cuối câu.","dung":"他七点就来公司了。"},{"sai":"我很就到。","why":"nhầm 就 là \"nhanh\"; 就 là phó từ thời gian, không phải hình dung từ, phải nói 很快就.","dung":"我很快就到了。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"vitri","cau":"他 A 六点 B 起床 C 了。","tu":"就","chon":["A","B","C"],"dap":["B"],"giai":""},{"kieu":"vitri","cau":"我家离公司很近，A 五分钟 B 到 C 了。","tu":"就","chon":["A","B","C"],"dap":["B"],"giai":""},{"kieu":"vitri","cau":"你 A 等一下，我 B 马上 C 来。","tu":"就","chon":["A","B","C"],"dap":["C"],"giai":""},{"kieu":"vitri","cau":"昨天 A 我 B 九点 C 下班了。","tu":"就","chon":["A","B","C"],"dap":["C"],"giai":""},{"kieu":"vitri","cau":"这个题 A 很容易，他 B 很快 C 做完了。","tu":"就","chon":["A","B","C"],"dap":["C"],"giai":""},{"kieu":"vitri","cau":"他 A 去年 B 来 C 中国了。","tu":"就","chon":["A","B","C"],"dap":["B"],"giai":""}],"huongDan":"Đặt 就 vào vị trí đúng (A/B/C) trong câu."},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["就","他","了","七点","来","公司"],"dap":["他七点就来公司了。"]},{"kieu":"xep","manh":["十分钟","到","就","走路","了"],"dap":["走路十分钟就到了。"]},{"kieu":"xep","manh":["马上","我","来","就"],"dap":["我马上就来。"]},{"kieu":"xep","manh":["就","我","睡觉","十点","昨天","了"],"dap":["昨天我十点就睡觉了。"]},{"kieu":"xep","manh":["做完","我","就","很快","了","这些题"],"dap":["这些题我很快就做完了。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你什么时候到公司的？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我七点就到了。"],"goiY":"mới 7 giờ tôi đã đến rồi"},{"kieu":"hoi","dong":[{"ai":"A","t":"你家离火车站远吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["不远，走路十分钟就到了。"],"goiY":"không xa, đi bộ 10 phút là tới"},{"kieu":"dich","vn":"Bạn đợi tôi một lát, tôi ăn xong là đi ngay.","dap":["你等我一下，我吃完饭就去。"]},{"kieu":"dich","vn":"Hôm qua mới 9 giờ anh ấy đã tan làm rồi.","dap":["昨天他九点就下班了。"]}]}]},{"so":"7.3","ten":"动词“离”","tenVn":"Động từ “离”","cauTruc":["A + 离 + B + 远/近 （+ 吗？）","→ 你家离公司远吗？","A + 离 + B + 很远/很近/不远/不近","→ 我家离公司很远。／我家离火车站不远。","A + 离 + B + 有 + 数量 / 要 + 时间","→ 我家离机场有三十公里。／我家离公司要一个小时。","Nghi vấn chính phản: A + 离 + B + 远不远？","→ 你家离学校远不远？"],"giaiThich":"“离” là động từ chỉ **khoảng cách giữa hai điểm** (nơi chốn hoặc thời điểm), dịch sang tiếng Việt là \"cách“. Trật tự cố định là: nơi thứ nhất + 离 + nơi thứ hai + rồi mới đến phần nói xa hay gần. Đây chính là chỗ học sinh Việt hay sai nhất, vì tiếng Việt nói ”nhà tôi **rất xa** công ty“ — tính từ đứng trước đối tượng; còn tiếng Trung bắt buộc đưa đối tượng lên trước: 我家 **离公司** 很远。Một điểm nữa: sau 离 không dùng tính từ trần trụi, phải có phó từ mức độ 很/太/非常 hoặc phủ định 不: nói 我家离公司远 nghe cụt và mang ý so sánh, phải nói 很远. Ngoài khoảng cách không gian, ”离\" còn dùng cho thời gian: 离考试还有三天。","viDu":[{"zh":"你家离公司远吗？","py":"Nǐ jiā lí gōngsī yuǎn ma?","vn":"Nhà bạn có xa công ty không?"},{"zh":"我家离公司很远，路上要一个小时呢。","py":"Wǒ jiā lí gōngsī hěn yuǎn, lùshang yào yí ge xiǎoshí ne.","vn":"Nhà tôi rất xa công ty, đi đường mất một tiếng đồng hồ đấy."},{"zh":"我家离火车站不远，很近。","py":"Wǒ jiā lí huǒchēzhàn bù yuǎn, hěn jìn.","vn":"Nhà tôi không xa ga tàu, rất gần."},{"zh":"学校离机场太远了，坐公共汽车要两个小时。","py":"Xuéxiào lí jīchǎng tài yuǎn le, zuò gōnggòng qìchē yào liǎng ge xiǎoshí.","vn":"Trường học xa sân bay quá, đi xe buýt mất hai tiếng."},{"zh":"医院离这儿很近，走路五分钟就到了。","py":"Yīyuàn lí zhèr hěn jìn, zǒulù wǔ fēnzhōng jiù dào le.","vn":"Bệnh viện rất gần đây, đi bộ năm phút là tới."}],"loi":[{"sai":"我家很远离公司。","why":"dịch nguyên văn tiếng Việt \"nhà tôi rất xa công ty\"; trong tiếng Trung 离+对象 phải đứng trước tính từ.","dung":"我家离公司很远。"},{"sai":"离我家公司很远。","why":"đặt 离 lên đầu câu, đảo mất chủ ngữ; A mới là chủ ngữ, 离 đứng sau A.","dung":"我家离公司很远。"},{"sai":"我家离公司远。","why":"thiếu phó từ mức độ; tính từ đơn độc trong câu trần thuật mang ý so sánh, nghe không tự nhiên.","dung":"我家离公司很远。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["你家","公司远吗？"],"dap":[["离"]]},{"kieu":"dien","phan":["我家","火车站","，走路五分钟就到了。"],"dap":[["离"],["很近"]]},{"kieu":"dien","phan":["学校","机场","，坐公共汽车要两个小时。"],"dap":[["离"],["很远"]]},{"kieu":"dien","phan":["你的公司","这儿","？"],"dap":[["离"],["远吗"]]},{"kieu":"dien","phan":["医院","我家不远。"],"dap":[["离"]]},{"kieu":"dien","phan":["他家","学校很近，他每天走路上学。"],"dap":[["离"]]}],"huongDan":"Điền 离 / 很远 / 很近 / 远吗 vào chỗ trống.","chon":["离","很远","很近","远吗"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["离","公司","我家","很远"],"dap":["我家离公司很远。"]},{"kieu":"xep","manh":["远吗","你家","公司","离"],"dap":["你家离公司远吗？"]},{"kieu":"xep","manh":["不远","火车站","我家","离"],"dap":["我家离火车站不远。"]},{"kieu":"xep","manh":["离","太远了","机场","学校"],"dap":["学校离机场太远了。"]},{"kieu":"xep","manh":["很近","这儿","医院","离"],"dap":["医院离这儿很近。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你家离公司远吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["很远，路上要一个小时呢。"],"goiY":"rất xa, đi đường mất một tiếng"},{"kieu":"hoi","dong":[{"ai":"A","o":true,"truoc":"","sau":"？"},{"ai":"B","t":"不远，走路十分钟就到了。"}],"dap":["你家离火车站远吗？"]},{"kieu":"dich","vn":"Nhà tôi không xa sân bay, đi xe buýt nửa tiếng là tới.","dap":["我家离机场不远，坐公共汽车半个小时就到了。"]},{"kieu":"dich","vn":"Bệnh viện cách công ty tôi rất gần.","dap":["医院离我的公司很近。"]}]}]},{"so":"7.4","ten":"语气助词“呢”","tenVn":"Trợ từ ngữ khí “呢”","cauTruc":["(1) Hỏi lại: 名词/代词 + 呢？ → 我很好，你呢？","(2) Hỏi \"ở đâu\": 名词 + 呢？ → 我的手机呢？","(3) Hỏi có từ để hỏi: 疑问词 + ……+ 呢？ → 你在做什么呢？","(4) Nhấn mạnh sự tiếp diễn: 主语 + (正)在 + 动词 + 呢。 → 他在睡觉呢。","(5) Nhấn mạnh mức độ/số lượng: 陈述句 + 呢！ → 路上要一个小时呢！"],"giaiThich":"“呢” là trợ từ ngữ khí đặt cuối câu, và nó có nhiều việc phải làm. Việc thứ nhất là **hỏi lại cho gọn**: khi hai người cùng nói về một chuyện, chỉ cần nêu đối tượng mới rồi thêm 呢: 我很好，你呢？ Việc thứ hai là **hỏi vị trí**: 我的手机呢？= Điện thoại tôi đâu rồi? Việc thứ ba là **làm mềm câu hỏi có từ nghi vấn** và nhấn mạnh hành động đang diễn ra: 你在做什么呢？Việc thứ tư, rất quan trọng trong bài khoá này, là **nhấn mạnh** — người nói thấy con số hoặc mức độ đáng kể: 路上要一个小时呢！(mất tới một tiếng lận!). Điều phải nhớ tuyệt đối: **câu đã có từ để hỏi (什么、哪儿、谁) hoặc câu nhấn mạnh thì dùng 呢, không dùng 吗**; 吗 chỉ dùng cho câu hỏi đúng-sai.","viDu":[{"zh":"我家离公司很远，路上要一个小时呢！","py":"Wǒ jiā lí gōngsī hěn yuǎn, lùshang yào yí ge xiǎoshí ne!","vn":"Nhà tôi xa công ty lắm, đi đường mất tới một tiếng đấy!"},{"zh":"我很好，你呢？","py":"Wǒ hěn hǎo, nǐ ne?","vn":"Tôi khỏe, còn bạn thì sao?"},{"zh":"我的手机呢？你看见了吗？","py":"Wǒ de shǒujī ne? Nǐ kànjiàn le ma?","vn":"Điện thoại của tôi đâu rồi? Bạn có thấy không?"},{"zh":"你在做什么呢？","py":"我在做题呢。","vn":"Nǐ zài zuò shénme ne? — Wǒ zài zuò tí ne. — Bạn đang làm gì đấy? — Tôi đang làm bài đây."},{"zh":"外边还下雨呢，你别出去了。","py":"Wàibian hái xià yǔ ne, nǐ bié chūqù le.","vn":"Bên ngoài vẫn còn mưa đấy, bạn đừng ra ngoài nữa."}],"loi":[{"sai":"你在做什么吗？","why":"học sinh coi 吗 là \"dấu hỏi\" chung; câu đã có 什么 thì không được dùng 吗.","dung":"你在做什么呢？"},{"sai":"我很好，你吗？","why":"dịch \"còn bạn?\" thành 你吗; câu hỏi lại rút gọn phải dùng 呢.","dung":"我很好，你呢？"},{"sai":"他在睡觉呢吗？","why":"dùng chồng hai trợ từ ngữ khí; một câu chỉ mang một trợ từ cuối câu.","dung":"他在睡觉呢。／他在睡觉吗？"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["我很好，你","？"],"dap":[["呢"]]},{"kieu":"dien","phan":["你是中国人","？"],"dap":[["吗"]]},{"kieu":"dien","phan":["你在做什么","？"],"dap":[["呢"]]},{"kieu":"dien","phan":["我的手机","？我找不到了。"],"dap":[["呢"]]},{"kieu":"dien","phan":["他在睡觉","，别说话。"],"dap":[["呢"]]},{"kieu":"dien","phan":["你家离公司远","？"],"dap":[["吗"]]}],"huongDan":"Điền 呢 hoặc 吗.","chon":["呢","吗"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["呢","要","路上","一个小时"],"dap":["路上要一个小时呢。"]},{"kieu":"xep","manh":["呢","做","你","什么","在"],"dap":["你在做什么呢？"]},{"kieu":"xep","manh":["呢","手机","我的"],"dap":["我的手机呢？"]},{"kieu":"xep","manh":["呢","做题","在","我"],"dap":["我在做题呢。"]},{"kieu":"xep","manh":["呢","下雨","还","外边"],"dap":["外边还下雨呢。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","o":true,"truoc":"我今天很累，你","sau":"？"},{"ai":"B","t":"我也很累。"}],"dap":["呢"]},{"kieu":"hoi","dong":[{"ai":"A","o":true,"truoc":"你哥哥","sau":"？"},{"ai":"B","t":"他在房间里休息呢。"}],"dap":["呢"]},{"kieu":"dich","vn":"Nhà anh ấy xa lắm, đi xe buýt mất tới hai tiếng đấy!","dap":["他家很远，坐公共汽车要两个小时呢！"]},{"kieu":"dich","vn":"Bạn đang làm gì đấy? — Tôi đang làm bài đây.","dap":["你在做什么呢？——我在做题呢。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-8.html"] = [{"so":"8.1","ten":"“……，好吗？”问句","tenVn":"Câu hỏi “……，好吗？”","cauTruc":["陈述句（建议/请求）+ ，好吗？","→ 我们一起去，好吗？","咱们/我们 + 动词短语 + ，好吗？","→ 我们休息一会儿，好吗？","你 + 动词短语 + ，好吗？（đề nghị người nghe làm gì）","→ 你帮我一下，好吗？","Trả lời: 好。／好的。／好啊。／太好了。／对不起，今天不行。"],"giaiThich":"Đây là kiểu câu hỏi dùng để **nêu đề nghị và xin ý kiến người nghe**. Người nói đưa ra một câu trần thuật về việc sắp làm, rồi thêm “，好吗？” ở cuối để hỏi \"được không / nhé?\". Ngoài “好吗” còn có các biến thể cùng chức năng: 行吗？、可以吗？、怎么样？ Về ngữ dụng, kiểu câu này rất lịch sự và mềm mỏng, thích hợp khi rủ rê, nhờ vả, thương lượng — dùng nhiều trong công ty, với bạn bè, với người lớn tuổi. Hai điều cần nhớ: phần trước “好吗” **phải là câu trần thuật**, không được là câu hỏi (không nói 你去吗，好吗？); và nội dung phải là **việc chưa xảy ra**, nên không dùng cho chuyện quá khứ.","viDu":[{"zh":"我们一起去，好吗？","py":"Wǒmen yìqǐ qù, hǎo ma?","vn":"Chúng ta cùng đi nhé?"},{"zh":"明天你来我家，好吗？","py":"Míngtiān nǐ lái wǒ jiā, hǎo ma?","vn":"Ngày mai bạn đến nhà tôi nhé?"},{"zh":"我们八点在公司门口见，好吗？","py":"Wǒmen bā diǎn zài gōngsī ménkǒu jiàn, hǎo ma?","vn":"Tám giờ chúng ta gặp nhau ở cổng công ty nhé?"},{"zh":"你帮我一下，好吗？","py":"Nǐ bāng wǒ yíxià, hǎo ma?","vn":"Bạn giúp tôi một chút được không?"},{"zh":"太累了，我们休息一会儿，好吗？","py":"Tài lèi le, wǒmen xiūxi yíhuìr, hǎo ma?","vn":"Mệt quá, chúng ta nghỉ một lát nhé?"}],"loi":[{"sai":"你去不去，好吗？","why":"đặt “好吗” sau một câu hỏi chính phản; phần trước phải là câu trần thuật.","dung":"你去，好吗？／你去不去？"},{"sai":"我们一起去吗，好吗？","why":"dùng chồng hai từ nghi vấn 吗 trong một câu.","dung":"我们一起去，好吗？"},{"sai":"昨天我们一起去了，好吗？","why":"dùng cho việc đã xảy ra; “好吗” chỉ dùng để đề nghị việc sắp làm.","dung":"明天我们一起去，好吗？"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dungsai","cau":"我们一起去看电影，好吗？","dung":true,"sua":""},{"kieu":"dungsai","cau":"你是不是老师，好吗？","dung":false,"sua":"你是老师，好吗？không hợp nghĩa; sửa thành 你是不是老师？"},{"kieu":"dungsai","cau":"明天我来你家，好吗？","dung":true,"sua":""},{"kieu":"dungsai","cau":"昨天我们吃饭了，好吗？","dung":false,"sua":"明天我们一起吃饭，好吗？"},{"kieu":"dungsai","cau":"你帮我一下，好吗？","dung":true,"sua":""},{"kieu":"dungsai","cau":"你喜欢吗，好吗？","dung":false,"sua":"你喜欢吗？／你喜欢这个，好吗？"}],"huongDan":"Câu nào dùng “好吗” đúng? Viết Đ (đúng) hoặc S (sai), câu sai hãy sửa."},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["好吗","一起","我们","去"],"dap":["我们一起去，好吗？"]},{"kieu":"xep","manh":["好吗","休息","我们","一会儿"],"dap":["我们休息一会儿，好吗？"]},{"kieu":"xep","manh":["好吗","帮","你","一下","我"],"dap":["你帮我一下，好吗？"]},{"kieu":"xep","manh":["好吗","见","我们","八点"],"dap":["我们八点见，好吗？"]},{"kieu":"xep","manh":["好吗","明天","来","你","我家"],"dap":["明天你来我家，好吗？"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","o":true,"truoc":"","sau":"，好吗？"},{"ai":"B","t":"好啊，我们八点去。"}],"dap":["我们八点去","明天我们一起去商店"]},{"kieu":"hoi","dong":[{"ai":"A","t":"这些题太多了，你帮我一下，好吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["好的，没问题。"],"goiY":"đồng ý"},{"kieu":"dich","vn":"Chiều nay chúng ta cùng đi ga tàu nhé?","dap":["今天下午我们一起去火车站，好吗？"]},{"kieu":"dich","vn":"Mệt quá rồi, chúng ta nghỉ một lát nhé? — Được thôi.","dap":["太累了，我们休息一会儿，好吗？——好啊。"]}]}]},{"so":"8.2","ten":"副词“再”","tenVn":"Phó từ “再”","cauTruc":["再 + 动词（短语） （lặp lại trong tương lai）","→ 你再说一遍。","先 + V1，再 + V2 （trình tự: trước… rồi sau…）","→ 我们先吃饭，再去商店。","V1 + 了 + 再 + V2 （làm xong V1 rồi mới V2）","→ 我下了班再去。","(以后/明天) + 再 + V （tạm hoãn）","→ 明天再说吧。"],"giaiThich":"“再” là phó từ đứng trước động từ, có hai nghĩa chính. Một là **lặp lại một lần nữa nhưng ở thì tương lai, việc chưa xảy ra**: 你再说一遍 (bạn nói lại lần nữa đi). Hai là **\"rồi mới“, nối hai việc theo thứ tự**: 让我想想再告诉你 — để tôi nghĩ đã, rồi mới nói cho bạn. Đây là điểm mà học sinh Việt phải phân biệt thật rõ với 又: cả hai đều dịch là ”lại“, nhưng **再 dùng cho việc chưa xảy ra**, còn **又 dùng cho việc đã xảy ra rồi**. Vì thế 再 hầu như không đi cùng 了 chỉ hoàn thành. Ngoài ra ”再\" rất hay đi cặp với “先” thành cấu trúc 先……再…… mà các em nên học thuộc cả cụm.","viDu":[{"zh":"让我想想再告诉你。","py":"Ràng wǒ xiǎngxiang zài gàosu nǐ.","vn":"Để tôi nghĩ một chút rồi nói cho bạn biết."},{"zh":"你再说一遍，好吗？我没听懂。","py":"Nǐ zài shuō yí biàn, hǎo ma? Wǒ méi tīngdǒng.","vn":"Bạn nói lại một lần nữa nhé? Tôi chưa nghe hiểu."},{"zh":"我们先吃饭，再去商店。","py":"Wǒmen xiān chīfàn, zài qù shāngdiàn.","vn":"Chúng ta ăn cơm trước, rồi đi cửa hàng sau."},{"zh":"今天太晚了，明天再来吧。","py":"Jīntiān tài wǎn le, míngtiān zài lái ba.","vn":"Hôm nay muộn quá rồi, mai hãy đến."},{"zh":"我下了班再去医院看他。","py":"Wǒ xià le bān zài qù yīyuàn kàn tā.","vn":"Tôi tan làm rồi mới đến bệnh viện thăm anh ấy."}],"loi":[{"sai":"昨天他来了，今天他再来了。","why":"nhầm 再 với 又; việc đã xảy ra phải dùng 又.","dung":"昨天他来了，今天他又来了。"},{"sai":"这个电影我再看了一次。","why":"再 chỉ việc chưa xảy ra nên không kết hợp với 了 hoàn thành.","dung":"这个电影我又看了一次。／我想再看一次。"},{"sai":"我们吃饭先，去商店再。","why":"đặt phó từ sau động từ theo trật tự tiếng Việt (\"ăn cơm trước, đi sau\"); 先/再 phải đứng trước động từ.","dung":"我们先吃饭，再去商店。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["让我想想","告诉你。"],"dap":[["再"]]},{"kieu":"dien","phan":["昨天他来了，今天他","来了。"],"dap":[["又"]]},{"kieu":"dien","phan":["你","说一遍，我没听懂。"],"dap":[["再"]]},{"kieu":"dien","phan":["这个电影我","看了一次，很好看。"],"dap":[["又"]]},{"kieu":"dien","phan":["今天太晚了，明天","来吧。"],"dap":[["再"]]},{"kieu":"dien","phan":["我们先吃饭，","去商店。"],"dap":[["再"]]}],"huongDan":"Điền 再 hoặc 又.","chon":["再","又"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["再","想想","让","告诉","我","你"],"dap":["让我想想再告诉你。"]},{"kieu":"xep","manh":["再","一遍","你","说"],"dap":["你再说一遍。"]},{"kieu":"xep","manh":["先","再","我们","去商店","吃饭"],"dap":["我们先吃饭，再去商店。"]},{"kieu":"xep","manh":["再","明天","吧","来"],"dap":["明天再来吧。"]},{"kieu":"xep","manh":["再","我","去","下了班","医院"],"dap":["我下了班再去医院。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你去不去？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["让我想想再告诉你。"],"goiY":"để tôi nghĩ rồi nói cho bạn biết"},{"kieu":"hoi","dong":[{"ai":"A","t":"对不起，我没听懂。"},{"ai":"B","o":true,"truoc":"好，","sau":""}],"dap":["我再说一遍。"],"goiY":"tôi nói lại một lần nữa"},{"kieu":"dich","vn":"Chúng ta ăn cơm trước, rồi đi xem phim.","dap":["我们先吃饭，再去看电影。"]},{"kieu":"dich","vn":"Hôm nay muộn quá rồi, ngày mai hãy làm tiếp nhé.","dap":["今天太晚了，明天再做吧。"]}]}]},{"so":"8.3","ten":"兼语句","tenVn":"Câu kiêm ngữ","cauTruc":["主语1 + 让/叫/请 + 兼语(N) + 动词2 + （宾语）","→ 妈妈叫我早点儿回家。","Phủ định: 主语1 + 不/没 + 让/叫/请 + 兼语 + 动词2","→ 爸爸不让我看电视。","Nghi vấn: ……吗？／让不让……？","→ 你妈妈让你去吗？"],"giaiThich":"Câu kiêm ngữ là câu có **hai động từ và một danh từ làm hai vai cùng lúc**: nó vừa là tân ngữ của động từ thứ nhất, vừa là chủ ngữ của động từ thứ hai. Trong 妈妈叫我回家, chữ 我 vừa là người bị 叫, vừa là người 回家 — vì thế gọi là \"kiêm ngữ“. Động từ thứ nhất ở HSK2 thường là 让 (để, cho phép, bảo), 叫 (bảo, sai), 请 (mời, nhờ) — đều mang nghĩa sai khiến, yêu cầu. Điểm học sinh Việt hay sai nhất là **vị trí phủ định**: tiếng Việt nói ”mẹ bảo tôi đừng đi\", còn tiếng Trung thường nói 妈妈不让我去 — chữ 不 đặt trước động từ thứ nhất. Về ngữ dụng: 让 và 请 lịch sự hơn, 叫 mang sắc thái ra lệnh mạnh hơn.","viDu":[{"zh":"让我想想再告诉你。","py":"Ràng wǒ xiǎngxiang zài gàosu nǐ.","vn":"Để tôi nghĩ một chút rồi nói cho bạn biết."},{"zh":"妈妈叫我早点儿回家。","py":"Māma jiào wǒ zǎo diǎnr huí jiā.","vn":"Mẹ bảo tôi về nhà sớm một chút."},{"zh":"今天我请你吃饭。","py":"Jīntiān wǒ qǐng nǐ chīfàn.","vn":"Hôm nay tôi mời bạn ăn cơm."},{"zh":"老师让我们做完这些题。","py":"Lǎoshī ràng wǒmen zuòwán zhèxiē tí.","vn":"Cô giáo bảo chúng tôi làm xong những bài này."},{"zh":"爸爸不让我看电视，让我休息。","py":"Bàba bú ràng wǒ kàn diànshì, ràng wǒ xiūxi.","vn":"Bố không cho tôi xem tivi, bảo tôi đi nghỉ."}],"loi":[{"sai":"妈妈让我不去公司。","why":"dịch theo tiếng Việt \"mẹ bảo tôi đừng đi công ty\"; ý \"không cho phép\" phải phủ định động từ thứ nhất.","dung":"妈妈不让我去公司。"},{"sai":"我请他了吃饭。","why":"đặt 了 giữa kiêm ngữ và động từ thứ hai; 了 phải ở cuối câu hoặc sau động từ thứ hai.","dung":"我请他吃饭了。"},{"sai":"让想想我再告诉你。","why":"đảo sai vị trí kiêm ngữ; kiêm ngữ phải đứng ngay sau 让.","dung":"让我想想再告诉你。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["","我想想再告诉你。"],"dap":[["让"]]},{"kieu":"dien","phan":["今天我","你吃饭，你想吃什么？"],"dap":[["请"]]},{"kieu":"dien","phan":["妈妈","我早点儿回家。"],"dap":[["叫","让"]]},{"kieu":"dien","phan":["老师","我们做完这些题。"],"dap":[["让","叫"]]},{"kieu":"dien","phan":["爸爸不","我看电视。"],"dap":[["让"]]},{"kieu":"dien","phan":["我","你帮我一下，好吗？"],"dap":[["请"]]}],"huongDan":"Điền 让 / 叫 / 请.","chon":["让","叫","请"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["让","想想","我","再","告诉你"],"dap":["让我想想再告诉你。"]},{"kieu":"xep","manh":["叫","妈妈","回家","我","早点儿"],"dap":["妈妈叫我早点儿回家。"]},{"kieu":"xep","manh":["请","我","吃饭","你","今天"],"dap":["今天我请你吃饭。"]},{"kieu":"xep","manh":["不","我","看电视","爸爸","让"],"dap":["爸爸不让我看电视。"]},{"kieu":"xep","manh":["让","做完","老师","这些题","我们"],"dap":["老师让我们做完这些题。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你今天怎么不去？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我妈妈不让我去。"],"goiY":"mẹ không cho tôi đi"},{"kieu":"hoi","dong":[{"ai":"A","t":"这些题你做完了吗？"},{"ai":"B","o":true,"truoc":"还没有，","sau":""}],"dap":["还没有，老师让我们明天做完。"],"goiY":"cô giáo bảo chúng tôi mai làm xong"},{"kieu":"dich","vn":"Hôm nay tôi mời bạn ăn cơm nhé?","dap":["今天我请你吃饭，好吗？"]},{"kieu":"dich","vn":"Bố tôi không cho tôi xem tivi, bảo tôi đi ngủ sớm.","dap":["我爸爸不让我看电视，让我早点儿睡觉。"]}]}]},{"so":"8.4","ten":"动词的重叠","tenVn":"Động từ lặp lại","cauTruc":["Động từ đơn âm: AA → 看看、想想、说说、听听","Động từ đơn âm có 一: A一A → 看一看、想一想","Đã xảy ra: A了A → 看了看、想了想","Động từ song âm: ABAB → 休息休息、帮助帮助、商量商量","Song âm đã xảy ra: AB了AB / AB了一下 → 休息了休息、休息了一下","Từ li hợp: AAB → 散散步、聊聊天儿、见见面","Tương đương: 动词 + 一下 → 看一下、帮一下"],"giaiThich":"Lặp lại động từ là cách người Trung Quốc **làm nhẹ giọng câu nói**: hành động diễn ra trong thời gian ngắn, số lần ít, thử một chút, và quan trọng nhất là **nghe khách khí, thoải mái, không áp đặt**. So sánh: 你看这个 nghe như mệnh lệnh, còn 你看看这个 nghe như một lời mời. Vì thế dạng lặp rất hay dùng khi nhờ vả, đề nghị, hoặc nói về ý định của mình: 让我想想. Các em chú ý ba quy tắc hình thức: (1) với động từ hai âm tiết phải lặp **cả cụm** ABAB, không lặp AABB; (2) với **từ li hợp** như 散步、聊天儿、见面 chỉ lặp âm tiết động từ ở trước, thành AAB: 散散步; (3) âm tiết lặp lại **đọc nhẹ** (khinh thanh). Cuối cùng, hình thức lặp đã mang sẵn nghĩa \"một chút\" nên **không thêm 一下 nữa**, và cũng không nhận phó từ mức độ 很/非常.","viDu":[{"zh":"让我想想再告诉你。","py":"Ràng wǒ xiǎngxiang zài gàosu nǐ.","vn":"Để tôi nghĩ một chút rồi nói cho bạn biết."},{"zh":"你看看这个手机，怎么样？","py":"Nǐ kànkan zhège shǒujī, zěnmeyàng?","vn":"Bạn xem thử cái điện thoại này xem, thế nào?"},{"zh":"太累了，我们休息休息吧。","py":"Tài lèi le, wǒmen xiūxi xiūxi ba.","vn":"Mệt quá, chúng ta nghỉ một chút đi."},{"zh":"他想了想，说：“我去。”","py":"Tā xiǎng le xiǎng, shuō: \"Wǒ qù.\"","vn":"Anh ấy nghĩ một lát rồi nói: \"Tôi đi.\""},{"zh":"晚上我和妈妈去外边散散步。","py":"Wǎnshang wǒ hé māma qù wàibian sànsan bù.","vn":"Buổi tối tôi với mẹ ra ngoài đi dạo một chút."}],"loi":[{"sai":"你看看了这本书。","why":"thêm 了 sau dạng lặp cho việc tương lai; 了 chỉ xen giữa hai âm tiết khi việc đã xảy ra (看了看).","dung":"你看看这本书。／他看了看这本书。"},{"sai":"我们休息休息一下吧。","why":"dùng chồng hai cách diễn đạt \"một chút\"; dạng lặp đã có nghĩa đó rồi.","dung":"我们休息休息吧。／我们休息一下吧。"},{"sai":"我们去散步散步。","why":"coi 散步 là động từ song âm bình thường; đây là từ li hợp, phải lặp theo dạng AAB.","dung":"我们去散散步。"},{"sai":"他很想想这个问题。","why":"dạng lặp mang nghĩa \"một chút\", không thể nhận phó từ mức độ 很/非常.","dung":"他想想这个问题。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"go","cau":"让我（想）_____ 再告诉你。","dap":["想想"]},{"kieu":"go","cau":"太累了，我们（休息）_____ 吧。","dap":["休息休息"]},{"kieu":"go","cau":"你（看）_____ 这个手机，很便宜。","dap":["看看"]},{"kieu":"go","cau":"他（想）_____ 了_____，说他不去。","dap":["想了想"]},{"kieu":"go","cau":"晚上我们去外边（散步）_____。","dap":["散散步"]},{"kieu":"go","cau":"你（帮助）_____ 他，好吗？","dap":["帮助帮助"]}],"huongDan":"Viết dạng lặp lại đúng của động từ trong ngoặc."},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"viet","yeuCau":"Viết lại câu bằng dạng động từ lặp lại.","goc":"你看这个手机。","dap":["你看看这个手机。"]},{"kieu":"viet","yeuCau":"Viết lại câu bằng dạng động từ lặp lại.","goc":"我们休息一下吧。","dap":["我们休息休息吧。"]},{"kieu":"viet","yeuCau":"Viết lại câu bằng dạng động từ lặp lại.","goc":"让我想一下。","dap":["让我想想。"]},{"kieu":"viet","yeuCau":"Viết lại câu bằng dạng động từ lặp lại.","goc":"晚上我们去外边散步。","dap":["晚上我们去外边散散步。"]},{"kieu":"viet","yeuCau":"Viết lại câu bằng dạng động từ lặp lại.","goc":"他看了我一下，没说话。","dap":["他看了看我，没说话。"]}],"huongDan":"Viết lại câu bằng dạng động từ lặp lại."},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你去不去？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["让我想想再告诉你。"],"goiY":"để tôi nghĩ một chút"},{"kieu":"hoi","dong":[{"ai":"A","t":"我太累了。"},{"ai":"B","o":true,"truoc":"好，","sau":""}],"dap":["好，我们休息休息吧。"],"goiY":"chúng ta nghỉ một chút đi"},{"kieu":"dich","vn":"Bạn xem thử quyển sách này đi, rất hay.","dap":["你看看这本书，很好。"]},{"kieu":"dich","vn":"Buổi tối tôi thường đi dạo một chút với mẹ.","dap":["晚上我常常和妈妈去散散步。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-9.html"] = [{"so":"9.1","ten":"结果补语","tenVn":"Bổ ngữ kết quả","cauTruc":["Khẳng định: 主语 + 动词 + 结果补语 + 了 + （宾语）","→ 我做完了这些题。／这些题我做完了。","Phủ định: 主语 + 没(有) + 动词 + 结果补语 （BỎ 了）","→ 我没做完。／我没听懂。","Nghi vấn 1: ……了吗？ → 你写完了吗？","Nghi vấn 2: ……了没有？ → 你写完了没有？","Nghi vấn 3: V + 没 + V + 补语？ → 你写没写完？","Các bổ ngữ kết quả thường gặp ở HSK2:","- 完 — xong, hết: 做完、写完、吃完、看完","- 好 — xong xuôi, ổn thoả: 做好、写好、准备好","- 见 — nhìn thấy / nghe thấy (kết quả giác quan): 看见、听见","- 到 — đạt được, tới được: 找到、买到、看到、听到","- 懂 — hiểu: 听懂、看懂","- 错 — sai, nhầm: 做错、写错、说错、买错","- 对 — đúng: 做对、说对、写对","- 会 — học được, biết làm: 学会"],"giaiThich":"Bổ ngữ kết quả là **thành phần đứng ngay sau động từ để cho biết hành động đó có đạt kết quả gì không**. Trong tiếng Việt chúng ta nói \"làm **xong**\", \"nghe **hiểu**\", \"tìm **thấy**“ — đúng là kiểu này. Ba điều quan trọng nhất các em phải thuộc lòng. Thứ nhất, **động từ và bổ ngữ dính liền nhau như một khối**, không được chen tân ngữ hay 了 vào giữa: nói 做完了这些题, không nói 做了完这些题. Thứ hai, câu khẳng định nói về việc đã xảy ra **thường có 了**, còn câu phủ định dùng **没(有)** và **phải bỏ 了**: 我没做完 (không nói 我没做完了). Thứ ba, phủ định của bổ ngữ kết quả **dùng 没, không dùng 不** — vì ta đang nói kết quả chưa đạt được chứ không phải ta không muốn làm; 不 chỉ dùng khi nói về ý muốn hoặc tương lai (今天我不做这些题). Về sắc thái, 见 và 到 đều chỉ kết quả giác quan nhưng 见 thiên về ”vô tình thấy/nghe được“, 到 thiên về ”đạt được sau khi cố gắng\": 我找到了我的手机。","viDu":[{"zh":"题太多，我没做完。","py":"Tí tài duō, wǒ méi zuòwán.","vn":"Đề nhiều quá, tôi làm không hết."},{"zh":"你写完了吗？","py":"写完了。","vn":"Nǐ xiěwán le ma? — Xiěwán le. — Bạn viết xong chưa? — Viết xong rồi."},{"zh":"老师说的话我没听懂，请你再说一遍。","py":"Lǎoshī shuō de huà wǒ méi tīngdǒng, qǐng nǐ zài shuō yí biàn.","vn":"Lời cô giáo nói tôi chưa nghe hiểu, xin bạn nói lại một lần nữa."},{"zh":"昨天我在路上看见他了。","py":"Zuótiān wǒ zài lùshang kànjiàn tā le.","vn":"Hôm qua tôi nhìn thấy anh ấy ở trên đường."},{"zh":"我的手机找到了，在房间里呢。","py":"Wǒ de shǒujī zhǎodào le, zài fángjiān lǐ ne.","vn":"Điện thoại của tôi tìm thấy rồi, ở trong phòng đấy."}],"loi":[{"sai":"我不听懂。","why":"dịch \"tôi không nghe hiểu\" bằng 不; kết quả chưa đạt được phải phủ định bằng 没.","dung":"我没听懂。"},{"sai":"我没做完了。","why":"giữ 了 trong câu phủ định; 没 và 了 không dùng chung.","dung":"我没做完。"},{"sai":"我做了完这些题。","why":"chen 了 vào giữa động từ và bổ ngữ; 了 phải đứng sau cả khối “动词+补语”.","dung":"我做完了这些题。"},{"sai":"这个题我做错。","why":"thiếu 了; câu khẳng định nói việc đã xảy ra với bổ ngữ kết quả cần 了.","dung":"这个题我做错了。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["题太多了，我没做","。"],"dap":[["完"]]},{"kieu":"dien","phan":["老师说的话我没听","。"],"dap":[["懂"]]},{"kieu":"dien","phan":["昨天我在路上看","他了。"],"dap":[["见"]]},{"kieu":"dien","phan":["我的手机找","了，在房间里。"],"dap":[["到"]]},{"kieu":"dien","phan":["这个字你写","了，不是这样写的。"],"dap":[["错"]]},{"kieu":"dien","phan":["你准备","了吗？我们走吧。"],"dap":[["好"]]}],"huongDan":"Điền bổ ngữ kết quả thích hợp: 完 / 懂 / 见 / 到 / 错 / 好.","chon":["完","懂","见","到","错","好"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"viet","yeuCau":"phủ định","goc":"我做完了这些题。","dap":["我没做完这些题。"]},{"kieu":"viet","yeuCau":"phủ định","goc":"我听懂了老师说的话。","dap":["我没听懂老师说的话。"]},{"kieu":"viet","yeuCau":"câu hỏi dùng 了吗","goc":"你写完了。","dap":["你写完了吗？"]},{"kieu":"viet","yeuCau":"câu hỏi dùng 了没有","goc":"你写完了。","dap":["你写完了没有？"]},{"kieu":"viet","yeuCau":"câu hỏi dùng V没V+补语","goc":"你做完了这些题。","dap":["你做没做完这些题？"]}],"huongDan":"Viết lại câu theo yêu cầu trong ngoặc."},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"这些题你做完了吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["题太多，我没做完。"],"goiY":"đề nhiều quá, tôi làm không hết"},{"kieu":"hoi","dong":[{"ai":"A","t":"我说的话你听懂了吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我没听懂，请你再说一遍。"],"goiY":"chưa hiểu, xin nói lại một lần nữa"},{"kieu":"dich","vn":"Điện thoại của tôi tìm thấy rồi, ở trong phòng.","dap":["我的手机找到了，在房间里。"]},{"kieu":"dich","vn":"Câu này bạn viết sai rồi, bạn viết lại một lần nữa nhé?","dap":["这个句子你写错了，你再写一遍，好吗？"]}]}]},{"so":"9.2","ten":"介词“从”","tenVn":"Giới từ “从”","cauTruc":["从 + 处所/时间 + 动词（短语）","→ 他从中国来。／我从八点开始工作。","从 + A + 到 + B （+ 谓语）","→ 从我家到公司要一个小时。","从 + 处所 + 来/去/出来/回来","→ 他从公司回来了。","Phủ định: 不/没 đặt TRƯỚC 从","→ 我不从这儿走。／他没从家里出来。"],"giaiThich":"“从” là giới từ chỉ **điểm xuất phát** — về nơi chốn (\"từ đâu\") hoặc về thời gian (\"từ lúc nào\"). Cụm “从 + …” luôn đứng **trước động từ**, không bao giờ đứng sau, đây là điểm khác biệt lớn nhất với tiếng Việt vì ta hay nói \"tôi đi **từ** nhà **đến** công ty mất một tiếng\" theo trật tự động từ trước. Cặp cố định 从……到…… dùng để nêu cả hai đầu mút: nơi bắt đầu và nơi kết thúc, hoặc thời gian bắt đầu và thời gian kết thúc: 从八点到十二点. Khi phủ định, 不 hoặc 没 phải đặt trước cả cụm giới từ chứ không phải trước động từ chính.","viDu":[{"zh":"从我家到公司要一个小时。","py":"Cóng wǒ jiā dào gōngsī yào yí ge xiǎoshí.","vn":"Từ nhà tôi đến công ty mất một tiếng."},{"zh":"他从中国来，现在在我们公司工作。","py":"Tā cóng Zhōngguó lái, xiànzài zài wǒmen gōngsī gōngzuò.","vn":"Anh ấy từ Trung Quốc đến, hiện đang làm việc ở công ty chúng tôi."},{"zh":"我们从八点到十二点上课。","py":"Wǒmen cóng bā diǎn dào shí'èr diǎn shàngkè.","vn":"Chúng tôi học từ 8 giờ đến 12 giờ."},{"zh":"从这儿到火车站很近，走路就到了。","py":"Cóng zhèr dào huǒchēzhàn hěn jìn, zǒulù jiù dào le.","vn":"Từ đây đến ga tàu rất gần, đi bộ là tới."},{"zh":"我从昨天就开始做这些题了。","py":"Wǒ cóng zuótiān jiù kāishǐ zuò zhèxiē tí le.","vn":"Tôi bắt đầu làm mấy bài này từ hôm qua rồi."}],"loi":[{"sai":"我去公司从家要一个小时。","why":"đặt cụm 从… sau động từ theo trật tự tiếng Việt; cụm giới từ phải đứng trước động từ.","dung":"从我家到公司要一个小时。"},{"sai":"我在家到公司要一个小时。","why":"nhầm 在 với 从; 在 chỉ nơi đang ở, 从 mới chỉ điểm xuất phát.","dung":"从我家到公司要一个小时。"},{"sai":"我从这儿不走。","why":"đặt phủ định sai vị trí; 不/没 đứng trước cả cụm 从….","dung":"我不从这儿走。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["","我家","公司要一个小时。"],"dap":[["从"],["到"]]},{"kieu":"dien","phan":["他","中国来。"],"dap":[["从"]]},{"kieu":"dien","phan":["我们","八点","十二点上课。"],"dap":[["从"],["到"]]},{"kieu":"dien","phan":["我家","火车站很近。"],"dap":[["离"]]},{"kieu":"dien","phan":["他","公司工作，不","家工作。"],"dap":[["在"],["在"]]},{"kieu":"dien","phan":["我","昨天就开始做这些题了。"],"dap":[["从"]]}],"huongDan":"Điền 从 / 到 / 在 / 离.","chon":["从","到","在","离"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["从","到","我家","公司","要","一个小时"],"dap":["从我家到公司要一个小时。"]},{"kieu":"xep","manh":["从","来","他","中国"],"dap":["他从中国来。"]},{"kieu":"xep","manh":["从","到","上课","我们","八点","十二点"],"dap":["我们从八点到十二点上课。"]},{"kieu":"xep","manh":["从","到","这儿","火车站","很近"],"dap":["从这儿到火车站很近。"]},{"kieu":"xep","manh":["从","我","开始","昨天","做","了","这些题","就"],"dap":["我从昨天就开始做这些题了。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你家离公司远吗？"},{"ai":"B","o":true,"truoc":"很远，","sau":""}],"dap":["很远，从我家到公司要一个小时。"],"goiY":"từ nhà tôi đến công ty mất một tiếng"},{"kieu":"hoi","dong":[{"ai":"A","t":"你们几点上课？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我们从八点到十二点上课。"],"goiY":"chúng tôi học từ 8 giờ đến 12 giờ"},{"kieu":"dich","vn":"Từ đây đến sân bay xa không? — Không xa, đi xe buýt nửa tiếng là tới.","dap":["从这儿到机场远吗？——不远，坐公共汽车半个小时就到了。"]},{"kieu":"dich","vn":"Anh ấy từ công ty về nhà rồi.","dap":["他从公司回家了。"]}]}]},{"so":"9.3","ten":"“第”表示顺序","tenVn":"“第” biểu thị thứ tự","cauTruc":["第 + 数词 + 量词 + 名词","→ 第一个人、第二本书、第三个问题","第 + 数词 + 名词（một số danh từ tự mang tính lượng từ）","→ 第一天、第一年、第一课、第一题","第 + 数词 + 次 （số lần）","→ 第一次、第二次"],"giaiThich":"“第” đặt trước số đếm để biến nó thành **số thứ tự**: 一 là \"một“, còn 第一 là ”thứ nhất\". Quy tắc quan trọng nhất về hình thức: sau 第+số thường **phải có lượng từ** rồi mới đến danh từ — nói 第一本书, không nói 第一书. Chỉ một số danh từ vốn đã có tính lượng từ như 天、年、课、题、次 thì đi thẳng với 第: 第一天、第一次. Cụm 第一次 rất hay dùng để nói lần đầu làm một việc gì đó: 这是我第一次来中国。Lưu ý 第一 còn có thể đứng một mình làm vị ngữ hoặc định ngữ: 他是第一。Về ngữ dụng, kết cấu này xuất hiện nhiều khi nói về thứ tự bài học, thứ tự câu hỏi trong bài thi, thứ tự ngày làm việc — đúng những tình huống các em gặp trong lớp và trong công ty.","viDu":[{"zh":"这是我第一次来中国。","py":"Zhè shì wǒ dì-yī cì lái Zhōngguó.","vn":"Đây là lần đầu tiên tôi đến Trung Quốc."},{"zh":"第一题我做错了，第二题我做对了。","py":"Dì-yī tí wǒ zuòcuò le, dì-èr tí wǒ zuòduì le.","vn":"Câu một tôi làm sai, câu hai tôi làm đúng."},{"zh":"今天是我上班的第一天。","py":"Jīntiān shì wǒ shàngbān de dì-yī tiān.","vn":"Hôm nay là ngày đầu tiên tôi đi làm."},{"zh":"他是第一个到公司的人。","py":"Tā shì dì-yī ge dào gōngsī de rén.","vn":"Anh ấy là người đầu tiên đến công ty."},{"zh":"第二本书我还没看完呢。","py":"Dì-èr běn shū wǒ hái méi kànwán ne.","vn":"Quyển sách thứ hai tôi vẫn chưa đọc xong đâu."}],"loi":[{"sai":"我第一来中国。","why":"dịch \"lần đầu\" mà bỏ mất lượng từ 次.","dung":"这是我第一次来中国。"},{"sai":"第一书我看完了。","why":"thiếu lượng từ giữa số thứ tự và danh từ.","dung":"第一本书我看完了。"},{"sai":"一次我来中国的时候，我不会说汉语。","why":"dùng số đếm thay số thứ tự; \"lần đầu\" phải là 第一次.","dung":"第一次我来中国的时候，我不会说汉语。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["这是我","来中国。"],"dap":[["第一次"]]},{"kieu":"dien","phan":["他是","到公司的人。"],"dap":[["第一个"]]},{"kieu":"dien","phan":["今天是我上班的","。"],"dap":[["第一天"]]},{"kieu":"dien","phan":["","我做错了。"],"dap":[["第一题"]]},{"kieu":"dien","phan":["","书我还没看完。"],"dap":[["第二本"]]},{"kieu":"dien","phan":["","问题你听懂了吗？"],"dap":[["第三个"]]}],"huongDan":"Điền 第一次 / 第一个 / 第一天 / 第一题 / 第二本 / 第三个.","chon":["第一次","第一个","第一天","第一题","第二本","第三个"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["第一次","这","我","是","来","中国"],"dap":["这是我第一次来中国。"]},{"kieu":"xep","manh":["第一题","做错","我","了"],"dap":["第一题我做错了。"]},{"kieu":"xep","manh":["第一天","今天","我","上班","的","是"],"dap":["今天是我上班的第一天。"]},{"kieu":"xep","manh":["第一个","他","到公司","的","人","是"],"dap":["他是第一个到公司的人。"]},{"kieu":"xep","manh":["第二本","没","我","看完","书","还"],"dap":["第二本书我还没看完。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你以前来过中国吗？"},{"ai":"B","o":true,"truoc":"没有，","sau":""}],"dap":["没有，这是我第一次来中国。"],"goiY":"đây là lần đầu tiên tôi đến Trung Quốc"},{"kieu":"hoi","dong":[{"ai":"A","t":"这些题你都做对了吗？"},{"ai":"B","o":true,"truoc":"没有，","sau":""}],"dap":["没有，第一题我做错了。"],"goiY":"câu một tôi làm sai rồi"},{"kieu":"dich","vn":"Hôm nay là ngày đầu tiên tôi đi làm, tôi đến công ty rất sớm.","dap":["今天是我上班的第一天，我很早就到公司了。"]},{"kieu":"dich","vn":"Quyển sách thứ hai tôi vẫn chưa đọc xong.","dap":["第二本书我还没看完。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-10.html"] = [{"so":"10.1","ten":"祈使句：“不要……了”、“别……了”","tenVn":"Câu cầu khiến “不要……了”, “别……了”","cauTruc":["(主语) + 不要 / 别 + V + (O) + 了！","(Chủ ngữ) + bùyào / bié + Động từ + (Tân ngữ) + le!","别 + 再 + V + 了！  → nhấn mạnh \"đừng … NỮA\"","别 + V + 了，+ (lý do／phương án thay thế)"],"giaiThich":"“不要……了” và “别……了” đều là câu cầu khiến phủ định, dùng để khuyên hoặc yêu cầu người nghe DỪNG một hành động đang diễn ra hoặc sắp diễn ra. Điểm mấu chốt các em phải nhớ: 别 chính là dạng nói tắt, khẩu ngữ của 不要, nghĩa hoàn toàn giống nhau, nhưng 别 nghe thân mật và tự nhiên hơn nên trong hội thoại hằng ngày người Trung Quốc dùng 别 nhiều hơn hẳn. Chữ 了 ở cuối câu rất quan trọng: nó mang nghĩa \"thay đổi trạng thái\", tức là \"đang làm rồi thì thôi đi, dừng lại đi“ — vì vậy 别找了 nghĩa là ”đang tìm thì đừng tìm nữa\", chứ không phải \"đừng tìm\" (chưa làm gì cả). Nếu muốn nhấn mạnh hơn nữa, ta thêm 再 vào giữa: 别再吃了 (đừng ăn thêm nữa). Về mặt ngữ dụng, đây là câu mang sắc thái quan tâm, nhắc nhở giữa những người thân quen; với người lớn tuổi hoặc trong hoàn cảnh trang trọng, các em nên thêm 请 hoặc nói nhẹ đi bằng 吧 để lịch sự hơn.","viDu":[{"zh":"别找了，手机在桌子上呢。","py":"Bié zhǎo le, shǒujī zài zhuōzi shang ne.","vn":"Đừng tìm nữa, điện thoại ở trên bàn kìa."},{"zh":"你别再吃了，太多了。","py":"Nǐ bié zài chī le, tài duō le.","vn":"Bạn đừng ăn nữa, nhiều quá rồi."},{"zh":"不要说了，我知道了。","py":"Bùyào shuō le, wǒ zhīdào le.","vn":"Đừng nói nữa, tôi biết rồi."},{"zh":"别看手机了，快睡吧。","py":"Bié kàn shǒujī le, kuài shuì ba.","vn":"Đừng xem điện thoại nữa, mau ngủ đi."},{"zh":"外面下雪呢，你别出去了。","py":"Wàimiàn xià xuě ne, nǐ bié chūqù le.","vn":"Bên ngoài đang có tuyết, bạn đừng ra ngoài nữa."}],"loi":[{"sai":"别找。手机在桌子上呢。","why":"Học sinh Việt dịch máy móc \"đừng tìm“ nên bỏ mất 了 cuối câu. Thiếu 了, câu mất đi nghĩa ”dừng việc đang làm\", nghe cụt và không tự nhiên trong ngữ cảnh người kia đang tìm.","dung":"别找了，手机在桌子上呢。"},{"sai":"你不要别吃了。","why":"Nhầm 别 với 不要 là hai từ khác nghĩa nên dùng chồng lên nhau, trong khi 别 chính là dạng rút gọn của 不要 — chỉ được chọn MỘT.","dung":"你别吃了。／你不要吃了。"},{"sai":"别不出去了。","why":"Chuyển di từ tiếng Việt \"đừng không đi ra\" và tưởng phải có thêm 不 để phủ định. 别 tự thân đã mang nghĩa phủ định, không bao giờ đi cùng 不.","dung":"别出去了。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":[""," 找了，你的手机在桌子上呢。"],"dap":[["别"]]},{"kieu":"dien","phan":["你别 "," 吃了，已经很多了。"],"dap":[["再"]]},{"kieu":"dien","phan":["不要说 "," ，我都知道了。"],"dap":[["了"]]},{"kieu":"dien","phan":["今天很冷，你 "," 出去了。"],"dap":[["别","不要"]]},{"kieu":"dien","phan":["妈妈说：“"," 看电视了，快去睡觉。”"],"dap":[["别","不要"]]},{"kieu":"dien","phan":["时间不早了，你们 "," 玩了。"],"dap":[["别","不要"]]}],"huongDan":"Điền 别 / 不要 / 再 / 了 vào chỗ trống (mỗi chỗ một từ).","chon":["别","不要","再","了"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["别","了","你","找"],"dap":["你别找了。"]},{"kieu":"xep","manh":["了","再","别","他","说"],"dap":["他别再说了。"]},{"kieu":"xep","manh":["不要","了","买","衣服","你"],"dap":["你不要买衣服了。"]},{"kieu":"xep","manh":["了","出去","下雪","别","外面","你"],"dap":["外面下雪，你别出去了。"]},{"kieu":"xep","manh":["了","手机","看","别","快","吧","睡"],"dap":["别看手机了，快睡吧。"]}],"huongDan":"Sắp xếp các từ sau thành câu hoàn chỉnh."},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"我的手机在哪儿？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["别找了，你的手机在桌子上呢。"],"goiY":"dùng 别……了"},{"kieu":"hoi","dong":[{"ai":"A","t":"我再吃一个吧。"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["你别再吃了，太多了。"],"goiY":"dùng 别再……了"},{"kieu":"dich","vn":"Bên ngoài trời lạnh lắm, bạn đừng ra ngoài nữa.","dap":["外面很冷，你别出去了。"]},{"kieu":"dich","vn":"Đừng nói nữa, tôi muốn ngủ rồi.","dap":["别说了，我想睡觉了。"]}]}]},{"so":"10.2","ten":"介词“对”","tenVn":"Giới từ “对” (对……说/对……好/对……有帮助)","cauTruc":["主语 + 对 + 对象 + V／Adj．","Chủ ngữ + duì + đối tượng + Động từ／Tính từ.","Ba khuôn hay gặp nhất trong HSK 2:","① 对 + N + 说／笑  → 他对我说……／她对我笑了。","② 对 + N + 很/非常 + 好  → 他对我很好。","③ 对 + N + 有帮助  → 运动对身体有帮助。","Phủ định: 主语 + 对 + N + 不 + Adj．（他对我不好。）"],"giaiThich":"介词 “对” giới thiệu đối tượng mà hành động hoặc thái độ hướng tới, tương đương \"với / đối với“ trong tiếng Việt. Quy tắc vàng các em phải khắc cốt ghi tâm: cụm 对+đối tượng LUÔN đứng TRƯỚC động từ hoặc tính từ, không bao giờ đứng sau — đây chính là chỗ ngược hẳn với tiếng Việt (”tốt với tôi“ → 对我很好). Khi 对 đi với tính từ 好, câu bắt buộc phải có phó từ mức độ 很/非常/太, không được nói trống 他对我好。Khi đi với 有帮助, chủ ngữ thường là một sự việc, một hoạt động (运动、说汉语、写汉字), đối tượng thường là 身体、学习、我们. Về ngữ dụng, ”对……很好\" là cách người Trung Quốc khen ngợi tình cảm, sự chăm sóc của người khác, rất hay dùng khi nói về gia đình, bạn bè, thầy cô.","viDu":[{"zh":"他对我很好。","py":"Tā duì wǒ hěn hǎo.","vn":"Anh ấy rất tốt với tôi."},{"zh":"老师对我们说：“别找了。”","py":"Lǎoshī duì wǒmen shuō: \"Bié zhǎo le.\"","vn":"Cô giáo nói với chúng tôi: \"Đừng tìm nữa.\""},{"zh":"运动对身体有帮助。","py":"Yùndòng duì shēntǐ yǒu bāngzhù.","vn":"Vận động có ích cho sức khỏe."},{"zh":"妈妈对我笑了笑。","py":"Māma duì wǒ xiào le xiào.","vn":"Mẹ cười với tôi."},{"zh":"每天说汉语对学习很有帮助。","py":"Měi tiān shuō Hànyǔ duì xuéxí hěn yǒu bāngzhù.","vn":"Mỗi ngày nói tiếng Trung rất có ích cho việc học."}],"loi":[{"sai":"他很好对我。","why":"Bê nguyên trật tự tiếng Việt \"tốt với tôi\" sang tiếng Trung, đặt cụm giới từ ra sau tính từ. Trong tiếng Trung, cụm 对+N là trạng ngữ nên phải đứng trước vị ngữ.","dung":"他对我很好。"},{"sai":"他对我好。","why":"Quên rằng tính từ làm vị ngữ trong câu khẳng định cần phó từ mức độ; thiếu 很 câu mang nghĩa so sánh dở dang, nghe chưa trọn.","dung":"他对我很好。"},{"sai":"老师说对我们……","why":"Nhầm 对 là bổ ngữ đứng sau động từ 说 giống kiểu \"nói với ai\" của tiếng Việt.","dung":"老师对我们说……"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["他 "," 我很好。"],"dap":[["对"]]},{"kieu":"dien","phan":["老师 "," 我们说：“明天有考试。”"],"dap":[["对"]]},{"kieu":"dien","phan":["运动对身体 "," 。"],"dap":[["有帮助"]]},{"kieu":"dien","phan":["我妈妈对我 "," 好。"],"dap":[["很"]]},{"kieu":"dien","phan":["多写汉字对学习 "," 帮助。"],"dap":[["有"]],"chon":["对","很","有","有帮助"]},{"kieu":"dien","phan":["她 "," 我笑了。"],"dap":[["对"]]}],"huongDan":"Điền 对 / 很 / 有帮助 vào chỗ trống.","chon":["对","很","有帮助"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["很","他","我","好","对"],"dap":["他对我很好。"]},{"kieu":"xep","manh":["说","老师","对","我们","了"],"dap":["老师对我们说了。"]},{"kieu":"xep","manh":["有帮助","身体","运动","对"],"dap":["运动对身体有帮助。"]},{"kieu":"xep","manh":["汉语","说","学习","对","很","有帮助","每天"],"dap":["每天说汉语对学习很有帮助。"]},{"kieu":"xep","manh":["不","对","好","他","弟弟"],"dap":["他对弟弟不好。"]}],"huongDan":"Sắp xếp các từ sau thành câu hoàn chỉnh."},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你的老师怎么样？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我的老师对我们很好。"],"goiY":"dùng 对……很好"},{"kieu":"hoi","dong":[{"ai":"A","t":"跑步好吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["跑步对身体有帮助。"],"goiY":"dùng 对……有帮助"},{"kieu":"dich","vn":"Mẹ nói với tôi: Đừng xem điện thoại nữa.","dap":["妈妈对我说：“别看手机了。”"]},{"kieu":"dich","vn":"Bạn ấy rất tốt với chúng tôi.","dap":["他对我们很好。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-11.html"] = [{"so":"11.1","ten":"动词结构作定语","tenVn":"Kết cấu động từ làm định ngữ (V + 的 + N)","cauTruc":["V (+ O) + 的 + N","Động từ (+ Tân ngữ) + de + Danh từ","主语 + V + 的 + N + 是 + ……","那个 + V + O + 的 + 人 + 是 + ……"],"giaiThich":"Trong tiếng Trung, một động từ hoặc cả một kết cấu động-tân có thể làm định ngữ để miêu tả danh từ đứng sau, và giữa chúng bắt buộc phải có trợ từ 的. Điều làm học sinh Việt bối rối nhất là trật tự: tiếng Việt nói \"người MẶC áo đỏ\" (danh từ trước, phần miêu tả sau), còn tiếng Trung nói ngược hoàn toàn — 穿红衣服的人 (phần miêu tả trước, danh từ sau). Thầy khuyên các em khi dịch hãy đọc câu tiếng Trung từ PHẢI sang TRÁI: 人 ← 的 ← 穿红衣服. Về ngữ nghĩa, kết cấu này giúp ta chỉ đích danh một người, một vật giữa nhiều người, nhiều vật khác; vì vậy trong hội thoại nó rất hay xuất hiện khi giới thiệu ai đó trong ảnh, trong đám đông, hoặc khi trả lời câu hỏi 哪个…？. Danh từ trung tâm cũng có thể lược bỏ nếu ngữ cảnh đã rõ: 穿红衣服的是我姐姐。","viDu":[{"zh":"那个穿红衣服的是我姐姐。","py":"Nàge chuān hóng yīfu de shì wǒ jiějie.","vn":"Người mặc áo đỏ kia là chị tôi."},{"zh":"说汉语的那个人是我们老师。","py":"Shuō Hànyǔ de nàge rén shì wǒmen lǎoshī.","vn":"Người nói tiếng Trung kia là cô giáo chúng tôi."},{"zh":"做饭的是我爸爸。","py":"Zuò fàn de shì wǒ bàba.","vn":"Người nấu cơm là bố tôi."},{"zh":"桌子上的手机是谁的？","py":"Zhuōzi shang de shǒujī shì shéi de?","vn":"Điện thoại trên bàn là của ai?"},{"zh":"我认识那个跑步的人。","py":"Wǒ rènshi nàge pǎobù de rén.","vn":"Tôi quen người chạy bộ kia."}],"loi":[{"sai":"那个人穿红衣服的是我姐姐。","why":"Bê trật tự tiếng Việt \"người mặc áo đỏ\" sang, đặt danh từ trung tâm lên trước kết cấu động từ. Trong tiếng Trung định ngữ luôn đứng TRƯỚC danh từ.","dung":"那个穿红衣服的人是我姐姐。"},{"sai":"穿红衣服人是我姐姐。","why":"Quên 的. Khi định ngữ là kết cấu động từ (nhiều hơn một chữ), 的 là bắt buộc, không được lược như định ngữ chỉ quan hệ thân thuộc (我妈妈).","dung":"穿红衣服的人是我姐姐。"},{"sai":"说汉语得那个人是我们老师。","why":"Nhầm 得 với 的. 的 nối định ngữ với danh từ; 得 chỉ dùng nối động từ với bổ ngữ trạng thái (bài 12).","dung":"说汉语的那个人是我们老师。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["那个穿红衣服 "," 是我姐姐。"],"dap":[["的"]]},{"kieu":"dien","phan":["做饭 "," 人是我妈妈。"],"dap":[["的"]]},{"kieu":"dien","phan":["桌子上 "," 手机是我的。"],"dap":[["的"]]},{"kieu":"dien","phan":["我认识那个唱歌 "," 女孩儿。"],"dap":[["的"]]},{"kieu":"dien","phan":["说汉语 "," 那个人是我们老师。"],"dap":[["的"]]},{"kieu":"dien","phan":["跑步 "," 那个人是我哥哥。"],"dap":[["的"]]}],"huongDan":"Điền 的 / 得 vào chỗ trống cho đúng.","chon":["的","得"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["的","是","穿红衣服","我姐姐","那个"],"dap":["那个穿红衣服的是我姐姐。"]},{"kieu":"xep","manh":["人","我们老师","说汉语","是","的"],"dap":["说汉语的人是我们老师。"]},{"kieu":"xep","manh":["的","谁","桌子上","是","手机","的"],"dap":["桌子上的手机是谁的？"]},{"kieu":"xep","manh":["那个","我","人","认识","的","跑步"],"dap":["我认识那个跑步的人。"]},{"kieu":"xep","manh":["我爸爸","做饭","是","的"],"dap":["做饭的是我爸爸。"]}],"huongDan":"Sắp xếp các từ sau thành câu hoàn chỉnh."},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"哪个是你姐姐？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["那个穿红衣服的是我姐姐。"],"goiY":"dùng 穿……的"},{"kieu":"hoi","dong":[{"ai":"A","t":"谁做饭？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["做饭的是我妈妈。"],"goiY":"dùng V + 的 + 是"},{"kieu":"dich","vn":"Người đang chạy bộ kia là anh trai tôi.","dap":["那个跑步的人是我哥哥。"]},{"kieu":"dich","vn":"Điện thoại trên bàn là của chị tôi.","dap":["桌子上的手机是我姐姐的。"]}]}]},{"so":"11.2","ten":"“比”字句（1）","tenVn":"Câu chữ “比” (1): A 比 B + Adj (+ số lượng)","cauTruc":["A + 比 + B + Adj．","A + 比 + B + Adj + 数量（三岁／一点儿／很多／多了）","Phủ định: A + 没有 + B + Adj．（他没有我大。）","KHÔNG dùng: 很 / 非常 / 太 sau 比 → chỉ dùng 更 / 还"],"giaiThich":"Câu chữ 比 dùng để so sánh hai đối tượng A và B về cùng một phương diện, tương đương \"A hơn B“ trong tiếng Việt. Trật tự hết sức cố định: A đứng đầu, 比 và B đứng giữa làm trạng ngữ, tính từ đứng cuối. Đây là nơi học sinh Việt mắc lỗi nhiều nhất trong cả quyển HSK 2, vì tiếng Việt nói ”anh ấy RẤT cao hơn tôi\" nên các em tự động thêm 很 vào: ✗他比我很高。 Hãy nhớ nguyên tắc: sau 比, tính từ ĐÃ mang nghĩa so sánh rồi, tuyệt đối không dùng 很/非常/太; nếu muốn nhấn mạnh thì chỉ được dùng 更 hoặc 还 (他比我更高／还高). Muốn nói rõ chênh lệch bao nhiêu, ta đặt số lượng SAU tính từ: 比我大三岁 (hơn tôi ba tuổi), 比昨天冷一点儿 (lạnh hơn hôm qua một chút), 比这个贵得多／贵多了 (đắt hơn nhiều). Về phủ định, người Trung Quốc rất ít nói 不比, mà dùng 没有: 他没有我大 (anh ấy không lớn bằng tôi).","viDu":[{"zh":"他比我大三岁。","py":"Tā bǐ wǒ dà sān suì.","vn":"Anh ấy hơn tôi ba tuổi."},{"zh":"今天比昨天冷一点儿。","py":"Jīntiān bǐ zuótiān lěng yìdiǎnr.","vn":"Hôm nay lạnh hơn hôm qua một chút."},{"zh":"这件衣服比那件贵得多。","py":"Zhè jiàn yīfu bǐ nà jiàn guì de duō.","vn":"Cái áo này đắt hơn cái kia nhiều."},{"zh":"他比我更高。","py":"Tā bǐ wǒ gèng gāo.","vn":"Anh ấy còn cao hơn tôi nữa."},{"zh":"我没有他大。","py":"Wǒ méiyǒu tā dà.","vn":"Tôi không lớn bằng anh ấy."}],"loi":[{"sai":"他比我很大。","why":"Chuyển di trực tiếp từ tiếng Việt \"lớn hơn tôi nhiều/rất\". Trong câu 比, tính từ tự thân đã có nghĩa so sánh nên không được thêm 很/非常/太.","dung":"他比我大。／他比我大三岁。／他比我更大。"},{"sai":"他比我不高。","why":"Dùng 不 để phủ định câu 比 theo thói quen phủ định tiếng Việt \"không cao hơn tôi\". Câu 比 phủ định bằng 没有 + B + Adj.","dung":"他没有我高。"},{"sai":"他比我三岁大。","why":"Đặt số lượng trước tính từ theo trật tự tiếng Việt \"ba tuổi lớn hơn\". Bổ ngữ số lượng bắt buộc đứng SAU tính từ.","dung":"他比我大三岁。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["他比我","大三岁。"],"dap":[["∅"]],"chon":["很","∅"],"giai":"không dùng 很"},{"kieu":"dien","phan":["今天比昨天","冷。"],"dap":[["更"]],"chon":["更","非常"]},{"kieu":"dien","phan":["我","他高。"],"dap":[["没有"]],"chon":["不","没有"]},{"kieu":"dien","phan":["这件衣服比那件贵","。"],"dap":[["多了"]],"chon":["多了","很多了"]},{"kieu":"dien","phan":["他比我","快。"],"dap":[["还"]],"chon":["太","还"]},{"kieu":"dien","phan":["姐姐比我大","。"],"dap":[["两岁"]],"chon":["两岁","岁两"]}],"huongDan":"Chọn từ đúng trong ngoặc."},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["我","三岁","他","比","大"],"dap":["他比我大三岁。"]},{"kieu":"xep","manh":["昨天","一点儿","今天","冷","比"],"dap":["今天比昨天冷一点儿。"]},{"kieu":"xep","manh":["得多","那件","这件衣服","贵","比"],"dap":["这件衣服比那件贵得多。"]},{"kieu":"xep","manh":["更","他","我","高","比"],"dap":["他比我更高。"]},{"kieu":"xep","manh":["没有","大","我","他"],"dap":["他没有我大。"]}],"huongDan":"Sắp xếp các từ sau thành câu hoàn chỉnh."},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你哥哥多大？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["他比我大三岁。"],"goiY":"dùng 比……大……岁"},{"kieu":"hoi","dong":[{"ai":"A","t":"今天的天气怎么样？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["今天比昨天冷一点儿。"],"goiY":"dùng 比昨天……一点儿"},{"kieu":"dich","vn":"Cái áo này đắt hơn cái kia nhiều.","dap":["这件衣服比那件贵得多。","这件衣服比那件贵多了。"]},{"kieu":"dich","vn":"Tôi không cao bằng chị tôi.","dap":["我没有姐姐高。"]}]}]},{"so":"11.3","ten":"助动词“可能”","tenVn":"Trợ động từ “可能”","cauTruc":["主语 + 可能 + V／Adj + (O)．","Chủ ngữ + kěnéng + Động từ／Tính từ + (Tân ngữ).","Phủ định: 主语 + 可能 + 不 + V．（他可能不来。）","主语 + 不可能 + V．（他不可能来。→ chắc chắn không）","可能 + 会 + V：他可能会来。"],"giaiThich":"“可能” là trợ động từ biểu thị sự suy đoán, phỏng đoán của người nói, tương đương \"có thể / có lẽ / chắc là“ trong tiếng Việt. Vị trí của nó rất cố định: đứng TRƯỚC động từ hoặc tính từ chính, sau chủ ngữ. Các em cần phân biệt kỹ hai kiểu phủ định vì nghĩa khác hẳn nhau: 他可能不来了 nghĩa là ”có lẽ anh ấy không đến nữa“ (suy đoán về việc không đến), còn 他不可能来 nghĩa là ”anh ấy không thể nào đến được“ (khẳng định chắc chắn là không). Học sinh Việt hay đặt 可能 ở cuối câu hoặc trước chủ ngữ theo kiểu ”Anh ấy đến có thể\" — đó là lỗi trật tự nghiêm trọng. Về ngữ dụng, 可能 làm cho lời nói mềm đi, bớt khẳng định, nên rất hay dùng khi ta không chắc chắn, khi báo tin không vui, hoặc khi từ chối khéo.","viDu":[{"zh":"他可能不来了。","py":"Tā kěnéng bù lái le.","vn":"Có lẽ anh ấy không đến nữa."},{"zh":"明天可能下雪。","py":"Míngtiān kěnéng xià xuě.","vn":"Ngày mai có thể có tuyết."},{"zh":"手机可能在桌子上。","py":"Shǒujī kěnéng zài zhuōzi shang.","vn":"Điện thoại có lẽ ở trên bàn."},{"zh":"他可能比我大。","py":"Tā kěnéng bǐ wǒ dà.","vn":"Anh ấy có lẽ lớn hơn tôi."},{"zh":"今天可能很热。","py":"Jīntiān kěnéng hěn rè.","vn":"Hôm nay có lẽ rất nóng."}],"loi":[{"sai":"他来可能了。","why":"Đặt 可能 sau động từ theo trật tự tiếng Việt \"anh ấy đến có thể\". 可能 là trợ động từ, bắt buộc đứng trước động từ chính.","dung":"他可能来。／他可能不来了。"},{"sai":"他可能没来了。","why":"Nhầm phủ định suy đoán về tương lai với phủ định quá khứ. Suy đoán việc chưa xảy ra dùng 不, không dùng 没.","dung":"他可能不来了。"},{"sai":"明天不可能下雪一点儿。","why":"Nhầm 不可能 (chắc chắn không thể) với 可能不 (có lẽ không), khiến câu suy đoán nhẹ nhàng thành khẳng định tuyệt đối.","dung":"明天可能不下雪。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["他今天很忙，"," 来了。"],"dap":[["可能不"]]},{"kieu":"dien","phan":["天阴了，明天 "," 下雪。"],"dap":[["可能"]]},{"kieu":"dien","phan":["我的手机 "," 在桌子上。"],"dap":[["可能"]]},{"kieu":"dien","phan":["他比我大三岁，"," 比我小。"],"dap":[["不可能"]]},{"kieu":"dien","phan":["今天天气很好，"," 下雨。"],"dap":[["可能不"]]},{"kieu":"dien","phan":["老师 "," 会对我们说这件事。"],"dap":[["可能"]]}],"huongDan":"Điền 可能 / 可能不 / 不可能 vào chỗ trống.","chon":["可能","可能不","不可能"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["了","不","可能","他","来"],"dap":["他可能不来了。"]},{"kieu":"xep","manh":["下雪","明天","可能"],"dap":["明天可能下雪。"]},{"kieu":"xep","manh":["在","可能","手机","桌子上"],"dap":["手机可能在桌子上。"]},{"kieu":"xep","manh":["比","可能","我","他","大"],"dap":["他可能比我大。"]},{"kieu":"xep","manh":["热","今天","很","可能"],"dap":["今天可能很热。"]}],"huongDan":"Sắp xếp các từ sau thành câu hoàn chỉnh."},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"他今天来吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["他可能不来了。"],"goiY":"dùng 可能不……了"},{"kieu":"hoi","dong":[{"ai":"A","t":"我的手机在哪儿？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["你的手机可能在桌子上。"],"goiY":"dùng 可能"},{"kieu":"dich","vn":"Ngày mai có lẽ rất lạnh, bạn đừng ra ngoài nữa.","dap":["明天可能很冷，你别出去了。"]},{"kieu":"dich","vn":"Chị ấy có lẽ lớn hơn tôi hai tuổi.","dap":["她可能比我大两岁。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-12.html"] = [{"so":"12.1","ten":"状态补语","tenVn":"Bổ ngữ trạng thái (V + 得 + Adj)","cauTruc":["① Không có tân ngữ: 主语 + V + 得 + 很 / 太 + Adj．","他跑得很快。","② Có tân ngữ — LẶP động từ: 主语 + V + O + V + 得 + Adj．","他说汉语说得很好。","③ Có tân ngữ — ĐẢO tân ngữ lên trước: 主语 + (O) + V + 得 + Adj．／O + 主语 + V + 得 + Adj．","他汉语说得很好。／汉语他说得很好。","④ Phủ định: 主语 + V + 得 + 不 + Adj．（他跑得不快。）","⑤ Nghi vấn: ……得怎么样？／……得 + A 不 A？／……得 + Adj + 吗？","他跑得怎么样？／他跑得快不快？／他跑得快吗？"],"giaiThich":"状态补语 (bổ ngữ trạng thái) dùng để đánh giá, miêu tả mức độ hay kết quả của một hành động đã thành thói quen hoặc đã xảy ra rồi — tức là trả lời câu hỏi \"làm như thế nào?“. Giữa động từ và bổ ngữ bắt buộc phải có trợ từ 得, và bổ ngữ thường là tính từ có kèm phó từ mức độ (很、太、非常). Điểm khiến học sinh Việt sai nhiều nhất là khi động từ mang tân ngữ: tiếng Việt nói thẳng ”anh ấy nói tiếng Trung rất giỏi\" nên các em viết ✗他说汉语得很好 — SAI, vì 得 phải bám ngay sau động từ. Tiếng Trung có hai cách chữa: LẶP lại động từ (他说汉语说得很好) hoặc ĐẢO tân ngữ lên trước động từ (他汉语说得很好). Phủ định đặt 不 SAU 得 chứ không đặt trước động từ: 他跑得不快, tuyệt đối không nói ✗他不跑得快. Về ngữ dụng, kiểu câu này rất hay dùng để khen, để nhận xét, để hỏi thăm kết quả học tập, sức khỏe, nên trong hội thoại HSK 2 xuất hiện liên tục.","viDu":[{"zh":"他跑得很快。","py":"Tā pǎo de hěn kuài.","vn":"Anh ấy chạy rất nhanh."},{"zh":"你穿得太少了。","py":"Nǐ chuān de tài shǎo le.","vn":"Bạn mặc ít quá rồi."},{"zh":"他说汉语说得很好。","py":"Tā shuō Hànyǔ shuō de hěn hǎo.","vn":"Anh ấy nói tiếng Trung rất giỏi."},{"zh":"我妈妈饭做得很好吃。","py":"Wǒ māma fàn zuò de hěn hǎochī.","vn":"Mẹ tôi nấu cơm rất ngon."},{"zh":"你昨天睡得怎么样？","py":"Nǐ zuótiān shuì de zěnmeyàng?","vn":"Hôm qua bạn ngủ thế nào?"}],"loi":[{"sai":"他说汉语得很好。","why":"Quên lặp động từ khi câu có tân ngữ, do bê nguyên trật tự tiếng Việt \"nói tiếng Trung rất giỏi\". 得 phải đứng ngay sau động từ, nên phải lặp 说 hoặc đảo 汉语 lên trước.","dung":"他说汉语说得很好。／他汉语说得很好。"},{"sai":"他跑的很快。","why":"Nhầm 得 với 的 vì ba chữ 的/地/得 đọc đều là \"de\". 的 nối định ngữ với danh từ, 地 nối trạng ngữ với động từ, còn 得 mới là chữ nối động từ với bổ ngữ trạng thái.","dung":"他跑得很快。"},{"sai":"他不跑得快。","why":"Đặt 不 trước động từ theo thói quen phủ định thông thường. Trong câu bổ ngữ trạng thái, 不 phủ định BỔ NGỮ nên phải đứng sau 得.","dung":"他跑得不快。"},{"sai":"他跑得快。","why":"Quên phó từ mức độ. Câu khẳng định với bổ ngữ trạng thái cần 很/太/非常, nếu không câu mang nghĩa so sánh dở dang.","dung":"他跑得很快。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["他跑 "," 很快。"],"dap":[["得"]]},{"kieu":"dien","phan":["你穿 "," 太少了。"],"dap":[["得"]]},{"kieu":"dien","phan":["他说汉语说 "," 很好。"],"dap":[["得"]]},{"kieu":"dien","phan":["他跑得 "," 快，我们等一下吧。"],"dap":[["不"]]},{"kieu":"dien","phan":["桌子上 "," 手机是我的。"],"dap":[["的"]]},{"kieu":"dien","phan":["我妈妈饭做得 "," 好吃。"],"dap":[["很"]]}],"huongDan":"Điền 得 / 的 / 不 / 很 vào chỗ trống.","chon":["得","的","不","很"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["得","快","跑","很","他"],"dap":["他跑得很快。"]},{"kieu":"xep","manh":["太","了","你","得","少","穿"],"dap":["你穿得太少了。"]},{"kieu":"xep","manh":["怎么样","昨天","睡","你","得"],"dap":["你昨天睡得怎么样？"]},{"kieu":"viet","yeuCau":"đảo tân ngữ","goc":"他说汉语说得很好。","dap":["他汉语说得很好。"]},{"kieu":"viet","yeuCau":"đảo tân ngữ","goc":"我妈妈做饭做得很好吃。","dap":["我妈妈饭做得很好吃。"]}],"huongDan":"Sắp xếp các từ sau thành câu hoàn chỉnh; câu 4, 5 viết lại theo cách đảo tân ngữ."},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"他跑得怎么样？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["他跑得很快。"],"goiY":"dùng V+得+很+Adj"},{"kieu":"hoi","dong":[{"ai":"A","t":"你汉语说得好不好？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我汉语说得不好。"],"goiY":"trả lời phủ định"},{"kieu":"dich","vn":"Hôm nay trời lạnh, bạn mặc ít quá rồi.","dap":["今天很冷，你穿得太少了。"]},{"kieu":"dich","vn":"Chị tôi hát rất hay, nhảy cũng rất đẹp.","dap":["我姐姐唱歌唱得很好，跳舞也跳得很好。"]}]}]},{"so":"12.2","ten":"“比”字句（2）","tenVn":"Câu chữ “比” (2): so sánh có bổ ngữ trạng thái / 更、还","cauTruc":["① 比 + bổ ngữ trạng thái, kiểu 1: A + 比 + B + V + 得 + Adj．","他比我跑得快。","② 比 + bổ ngữ trạng thái, kiểu 2: A + V + 得 + 比 + B + Adj．","他跑得比我快。","③ Có tân ngữ: A + V + O + 比 + B + V + 得 + Adj．／A + O + V + 得 + 比 + B + Adj．","他说汉语比我说得好。／他汉语说得比我好。","④ Nhấn mạnh: 比 + B + 更／还 + Adj（KHÔNG dùng 很/非常/太）","他比我更高。／他跑得比我还快。","⑤ Mức chênh lệch: A + 比 + B + V + 得 + Adj + 一点儿／多了／得多．","他比我跑得快一点儿。／他比我跑得快多了。"],"giaiThich":"Đây là bước nâng cấp của câu 比 ở bài 11: thay vì so sánh tính chất (大、高), ta so sánh CÁCH THỰC HIỆN một hành động (chạy nhanh hơn, nói giỏi hơn). Có hai vị trí đặt cụm 比 đều đúng: đặt trước động từ (他比我跑得快) hoặc đặt sau 得 (他跑得比我快) — nghĩa như nhau, các em chọn cách nào dễ nhớ cũng được, nhưng phải giữ nguyên trật tự, không được trộn lẫn. Quy tắc cấm kỵ của bài 11 vẫn giữ nguyên và còn quan trọng hơn ở đây: sau 比 tuyệt đối KHÔNG được dùng 很/非常/太, chỉ được dùng 更 hoặc 还 để nhấn mạnh — vì vậy ✗他比我跑得很快 là sai, phải nói 他比我跑得快 hoặc 他比我跑得更快. Muốn nói rõ hơn bao nhiêu, ta thêm 一点儿 (một chút), 多了／得多 (nhiều) vào cuối: 他比我跑得快多了. Về ngữ dụng, kiểu câu này rất hay dùng khi khen ngợi, khi nhận xét khách quan, hoặc khi khiêm tốn tự nhận mình kém hơn người khác.","viDu":[{"zh":"他比我跑得快。","py":"Tā bǐ wǒ pǎo de kuài.","vn":"Anh ấy chạy nhanh hơn tôi."},{"zh":"他跑得比我还快。","py":"Tā pǎo de bǐ wǒ hái kuài.","vn":"Anh ấy chạy còn nhanh hơn tôi nữa."},{"zh":"姐姐唱歌比我唱得好。","py":"Jiějie chànggē bǐ wǒ chàng de hǎo.","vn":"Chị tôi hát hay hơn tôi."},{"zh":"他汉语说得比我好多了。","py":"Tā Hànyǔ shuō de bǐ wǒ hǎo duō le.","vn":"Anh ấy nói tiếng Trung giỏi hơn tôi nhiều."},{"zh":"今天我比昨天起得早一点儿。","py":"Jīntiān wǒ bǐ zuótiān qǐ de zǎo yìdiǎnr.","vn":"Hôm nay tôi dậy sớm hơn hôm qua một chút."}],"loi":[{"sai":"他比我跑得很快。","why":"Chuyển di từ tiếng Việt \"chạy rất nhanh hơn tôi\"; học sinh giữ thói quen phải có 很 trước tính từ. Trong câu 比，很 bị cấm tuyệt đối, chỉ dùng 更/还.","dung":"他比我跑得快。／他比我跑得更快。"},{"sai":"他比我跑不得快。／他不比我跑得快。","why":"Dùng 不 phủ định câu 比 theo thói quen tiếng Việt \"không chạy nhanh hơn tôi\". Phủ định của so sánh này là 没有 + B + V + 得 + Adj.","dung":"我没有他跑得快。"},{"sai":"他说汉语比我得好。","why":"Trộn lẫn hai cấu trúc, để 得 mất chỗ bám vào động từ. Phải hoặc lặp động từ (说汉语比我说得好) hoặc đảo tân ngữ (汉语说得比我好).","dung":"他说汉语比我说得好。／他汉语说得比我好。"},{"sai":"他比我跑得快很多了。","why":"Ghép lẫn 很多 với 多了. Bổ ngữ mức chênh lệch chỉ có các dạng cố định: 一点儿、多了、得多.","dung":"他比我跑得快多了。／他比我跑得快得多。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["他比我跑得","快。"],"dap":[["∅"]],"chon":["很","∅"],"giai":"không dùng 很"},{"kieu":"dien","phan":["他跑得比我","快。"],"dap":[["还"]],"chon":["还","太"]},{"kieu":"dien","phan":["我","他跑得快。"],"dap":[["没有"]],"chon":["不","没有"]},{"kieu":"dien","phan":["他汉语说得比我好","。"],"dap":[["多了"]],"chon":["多了","很多了"]},{"kieu":"dien","phan":["今天我比昨天起得早","。"],"dap":[["一点儿"]],"chon":["一点儿","一点儿的"]},{"kieu":"dien","phan":["姐姐唱歌比我","好。"],"dap":[["唱得"]],"chon":["唱得","得"]}],"huongDan":"Chọn từ đúng trong ngoặc."},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["比","快","跑","得","我","他"],"dap":["他比我跑得快。"]},{"kieu":"xep","manh":["唱","比","姐姐","得","我","好","唱歌"],"dap":["姐姐唱歌比我唱得好。"]},{"kieu":"xep","manh":["早","一点儿","比","起","我","得","昨天","今天"],"dap":["今天我比昨天起得早一点儿。"]},{"kieu":"viet","yeuCau":"đặt 比 sau 得","goc":"他比我跑得快。","dap":["他跑得比我快。"]},{"kieu":"viet","yeuCau":"đặt 比 sau 得，thêm 还","goc":"他比我说得好。","dap":["他说得比我还好。"]}],"huongDan":"Sắp xếp các từ sau thành câu hoàn chỉnh; câu 4, 5 viết lại theo cách đặt 比 sau 得."},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你跑得快还是他跑得快？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["他比我跑得快。"],"goiY":"dùng 比……跑得快"},{"kieu":"hoi","dong":[{"ai":"A","t":"你的汉语怎么样？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我没有他说得好。"],"goiY":"dùng 没有……说得好，khiêm tốn"},{"kieu":"dich","vn":"Chị tôi hát hay hơn tôi nhiều.","dap":["我姐姐唱歌比我唱得好多了。"]},{"kieu":"dich","vn":"Hôm nay tôi dậy sớm hơn hôm qua một chút.","dap":["今天我比昨天起得早一点儿。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-13.html"] = [{"so":"13.1","ten":"动态助词“着”","tenVn":"Trợ từ động thái “着”","cauTruc":["(1) Trạng thái duy trì: S + V + 着 (+ 呢)","门　开着　呢。","(2) Câu tồn hiện: Nơi chốn + V + 着 + (Số + Lượng từ) + N","桌子上　放着　一本　书。","(3) Liên động V1着 + V2: S + V1 + 着 + V2 (+ O)","他　坐着　看书。","(4) Phủ định: S + 没（有） + V + 着 (+ O) 　→ TUYỆT ĐỐI không dùng 不","(5) Nghi vấn: S + V + 着 + O + 吗？　/　S + V + 着 + O + 没有？"],"giaiThich":"Về cú pháp, “着” là trợ từ động thái, luôn bám sát ngay sau động từ, không bao giờ tách rời; phủ định của nó là “没（有）”, còn “不” chỉ dùng cho thói quen hay ý chí nên không thể đi với “着”. Về ngữ nghĩa, “着” không nói hành động đang diễn tiến mà nói TRẠNG THÁI do hành động ấy để lại vẫn còn duy trì: “开着” là cửa đã được mở và hiện vẫn ở tình trạng mở, khác hẳn “在开” (đang thực hiện thao tác mở). Các em hãy nhớ công thức phân biệt: 在/正在 = tiến trình của động tác, 着 = trạng thái còn lại; vì thế nói 他在开门 (anh ấy đang mở cửa) nhưng 门开着 (cửa đang mở). Về ngữ dụng, “着” hay đi với “呢” ở cuối câu để nhấn mạnh và làm giọng nói mềm đi, thường dùng khi ta miêu tả khung cảnh trước mắt, nhắc nhở hoặc trấn an người nghe (门开着呢，你进来吧). Dạng V1着 + V2 thì V1着 là tư thế/cách thức, V2 mới là hành động chính, dịch sang tiếng Việt là \"vừa… vừa…\" hoặc \"ngồi mà đọc, đứng mà nói\".","viDu":[{"zh":"门开着呢。","py":"Mén kāizhe ne.","vn":"Cửa đang mở kìa."},{"zh":"桌子上放着一本书。","py":"Zhuōzi shang fàngzhe yì běn shū.","vn":"Trên bàn có đặt một quyển sách."},{"zh":"他坐着看书。","py":"Tā zuòzhe kàn shū.","vn":"Anh ấy ngồi đọc sách."},{"zh":"教室的门没有开着。","py":"Jiàoshì de mén méiyǒu kāizhe.","vn":"Cửa lớp học không mở."},{"zh":"你的手机开着没有？","py":"Nǐ de shǒujī kāizhe méiyǒu?","vn":"Điện thoại của bạn có đang bật không?"}],"loi":[{"sai":"门不开着。","why":"học sinh Việt dịch thẳng \"cửa KHÔNG mở\" nên lấy 不, quên rằng 着 chỉ trạng thái đã tồn tại nên phải phủ định bằng 没（有）.","dung":"门没（有）开着。"},{"sai":"他坐看着书。","why":"đặt sai vị trí, 着 bị đẩy sang động từ thứ hai; trong kết cấu V1着 V2 thì 着 phải dính liền động từ chỉ tư thế.","dung":"他坐着看书。"},{"sai":"我来的时候，门开了着。","why":"lẫn 了 (hoàn thành) với 着 (duy trì), dùng cả hai cùng lúc.","dung":"我来的时候，门开着。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["门开","呢，你进来吧。"],"dap":[["着"]]},{"kieu":"dien","phan":["桌子上放","两本书。"],"dap":[["着"]]},{"kieu":"dien","phan":["他坐","看电视呢。"],"dap":[["着"]]},{"kieu":"dien","phan":["教室的门","开着。"],"dap":[["没有"]]},{"kieu":"dien","phan":["妈妈","做饭呢。"],"dap":[["在"]]},{"kieu":"dien","phan":["你的手机开着","？"],"dap":[["吗"]]}],"huongDan":"Điền 着、了、在、没有、吗 vào chỗ trống","chon":["着","了","在","没有","吗"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["着","门","呢","开"],"dap":["门开着呢。"]},{"kieu":"xep","manh":["一本书","放着","桌子上"],"dap":["桌子上放着一本书。"]},{"kieu":"xep","manh":["看书","他","着","坐"],"dap":["他坐着看书。"]},{"kieu":"xep","manh":["没有","那个","开着","门"],"dap":["那个门没有开着。"]},{"kieu":"xep","manh":["吗","你的","开着","手机"],"dap":["你的手机开着吗？"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"门开着吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["开着呢。"],"goiY":"trả lời: đang mở kìa"},{"kieu":"hoi","dong":[{"ai":"A","t":"他在做什么？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["他坐着看电视呢。"],"goiY":"cậu ấy ngồi xem tivi"},{"kieu":"dich","vn":"Trên bàn để một chiếc điện thoại.","dap":["桌子上放着一个手机。"]},{"kieu":"dich","vn":"Cửa lớp học đang mở kìa, chúng ta vào đi.","dap":["教室的门开着呢，我们进去吧。"]}]}]},{"so":"13.2","ten":"反问句“不是……吗”","tenVn":"Câu phản vấn “不是……吗”","cauTruc":["S + 不是 + (V / Adj / Danh ngữ) + 吗？","Phía sau thường thêm một vế chất vấn: ……不是……吗？+ 你怎么 + …… ?","今天　不是　星期日　吗？你怎么去上班？","Lưu ý phát âm: 不是 đọc là **bú shì** (biến điệu)."],"giaiThich":"Về cú pháp, đây là khung cố định “不是……吗”, hai đầu khung ôm lấy phần cần khẳng định; tuy có 不 và 吗 nhưng câu KHÔNG phải câu phủ định, cũng KHÔNG phải câu hỏi thật. Về ngữ nghĩa, hình thức phủ định + nghi vấn lại cho ra một khẳng định mạnh: 你不是有钥匙吗？ = 你有钥匙 (bạn rõ ràng có chìa khóa mà). Về ngữ dụng, người nói dùng nó khi tin chắc điều mình nói là đúng và muốn nhắc nhở, trách nhẹ hoặc tỏ ra ngạc nhiên; sắc thái tiếng Việt tương ứng là \"chẳng phải… sao?\", \"… mà?\", \"… còn gì?\". Vì có sắc thái trách móc nên với người trên hoặc người lạ, các em nên hạ giọng hoặc thêm 你看/那个 cho mềm đi, tránh nghe như đang gắt.","viDu":[{"zh":"你不是有钥匙吗？","py":"Nǐ bú shì yǒu yàoshi ma?","vn":"Bạn chẳng phải có chìa khóa sao?"},{"zh":"这不是你的手机吗？","py":"Zhè bú shì nǐ de shǒujī ma?","vn":"Đây chẳng phải điện thoại của bạn sao?"},{"zh":"你不是说今天不下雨吗？","py":"Nǐ bú shì shuō jīntiān bú xià yǔ ma?","vn":"Bạn chẳng phải nói hôm nay không mưa sao?"},{"zh":"今天不是星期日吗？你怎么去上班？","py":"Jīntiān bú shì xīngqīrì ma? Nǐ zěnme qù shàngbān?","vn":"Hôm nay chẳng phải chủ nhật sao? Sao bạn còn đi làm?"},{"zh":"门不是开着吗？你怎么不进去？","py":"Mén bú shì kāizhe ma? Nǐ zěnme bú jìnqù?","vn":"Cửa chẳng phải đang mở sao? Sao bạn không vào?"}],"loi":[{"sai":"你不是有钥匙？","why":"học sinh bỏ 吗 vì thấy câu đã có nghĩa hỏi; nhưng khung phản vấn bắt buộc phải đủ hai đầu 不是…吗.","dung":"你不是有钥匙吗？"},{"sai":"你是有钥匙吗？","why":"bỏ mất 不, câu trở thành câu hỏi thường, mất hẳn sắc thái \"chẳng phải… sao\".","dung":"你不是有钥匙吗？"},{"sai":"A：你不是去过北京吗？　B：不是，我去过。","why":"hiểu nhầm đây là câu hỏi phủ định nên trả lời 不是; thực ra câu này đang khẳng định, phải đáp xuôi theo.","dung":"B：对，我去过。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["你","有钥匙吗？门开着呢。"],"dap":[["不是"]]},{"kieu":"dien","phan":["这不是你的手机","？"],"dap":[["吗"]]},{"kieu":"dien","phan":["今天不是星期日吗？你","去上班？"],"dap":[["怎么"]]},{"kieu":"dien","phan":["你不是","今天不下雨吗？"],"dap":[["说"]]},{"kieu":"dien","phan":["门不是","着吗？你进去吧。"],"dap":[["开"]]},{"kieu":"dien","phan":["他","你哥哥吗？怎么不认识你？"],"dap":[["不是"]]}],"huongDan":"Điền 不是、吗、怎么、说、开 vào chỗ trống","chon":["不是","吗","怎么","说","开"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"viet","yeuCau":"Đổi các câu sau thành câu phản vấn “不是……吗”","goc":"你有钥匙。","dap":["你不是有钥匙吗？"]},{"kieu":"viet","yeuCau":"Đổi các câu sau thành câu phản vấn “不是……吗”","goc":"他去过北京。","dap":["他不是去过北京吗？"]},{"kieu":"viet","yeuCau":"Đổi các câu sau thành câu phản vấn “不是……吗”","goc":"这是你的书。","dap":["这不是你的书吗？"]},{"kieu":"viet","yeuCau":"Đổi các câu sau thành câu phản vấn “不是……吗”","goc":"今天是晴天。","dap":["今天不是晴天吗？"]},{"kieu":"viet","yeuCau":"Đổi các câu sau thành câu phản vấn “不是……吗”","goc":"你说今天很冷。","dap":["你不是说今天很冷吗？"]}],"huongDan":"Đổi các câu sau thành câu phản vấn “不是……吗”"},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"我进不去，没有钥匙。"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["你不是有钥匙吗？"],"goiY":"bạn chẳng phải có chìa khóa sao?"},{"kieu":"hoi","dong":[{"ai":"A","t":"我想去看那个电影。"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["你不是看过了吗？"],"goiY":"bạn chẳng phải xem rồi sao?"},{"kieu":"dich","vn":"Hôm nay chẳng phải chủ nhật sao? Sao bạn còn đi làm?","dap":["今天不是星期日吗？你怎么还去上班？"]},{"kieu":"dich","vn":"Cửa chẳng phải đang mở sao? Bạn vào đi.","dap":["门不是开着吗？你进去吧。"]}]}]},{"so":"13.3","ten":"介词“往”","tenVn":"Giới từ “往”","cauTruc":["S + 往 + Từ chỉ phương hướng / Địa điểm + V","（你）　往　前　走。","请　　往　里　走。","这个火车　往　北京　开。","Từ đi sau 往 thường là: 前、后、左、右、里、外、上、下 hoặc tên địa điểm. Động từ đi sau thường là động từ di chuyển: 走、开、看、跑、来、去."],"giaiThich":"Về cú pháp, “往” là giới từ, kết cấu 往 + phương vị/địa điểm phải đứng TRƯỚC động từ, tạo thành trạng ngữ — đây là điểm ngược hoàn toàn với tiếng Việt \"đi về phía trước\", nên các em phải đảo lại thành \"về phía trước + đi\". Về ngữ nghĩa, “往” chỉ hướng của sự di chuyển hoặc của tầm nhìn, trả lời câu hỏi 往哪儿 (về phía nào). Cần nhớ “往” chỉ dẫn hướng tới một PHƯƠNG HƯỚNG hay ĐỊA ĐIỂM, không dùng với người: nói 往前走 được nhưng không nói 往我看. Về ngữ dụng, kết cấu này rất hay gặp khi chỉ đường, hướng dẫn khách, thông báo trên tàu xe; khi nói với người lạ nên thêm 请 phía trước cho lịch sự: 请往里走。","viDu":[{"zh":"往前走，前面就是火车站。","py":"Wǎng qián zǒu, qiánmiàn jiù shì huǒchēzhàn.","vn":"Đi về phía trước, đằng trước chính là ga tàu."},{"zh":"到前面往左走。","py":"Dào qiánmiàn wǎng zuǒ zǒu.","vn":"Đến phía trước thì rẽ sang bên trái."},{"zh":"你往右看，那个门开着呢。","py":"Nǐ wǎng yòu kàn, nàge mén kāizhe ne.","vn":"Bạn nhìn sang bên phải, cái cửa đó đang mở kìa."},{"zh":"这个火车往北京开。","py":"Zhège huǒchē wǎng Běijīng kāi.","vn":"Chuyến tàu này chạy về Bắc Kinh."},{"zh":"请大家往里走。","py":"Qǐng dàjiā wǎng lǐ zǒu.","vn":"Mời mọi người đi vào phía trong."}],"loi":[{"sai":"走往前。","why":"bê nguyên trật tự tiếng Việt \"đi về phía trước\"; trong tiếng Hán kết cấu giới từ phải đứng trước động từ.","dung":"往前走。"},{"sai":"你往我看。","why":"học sinh dịch \"nhìn về phía tôi\" nên ghép 往 với người; 往 chỉ đi với phương hướng hoặc địa điểm.","dung":"你看我。/ 你往这边看。"},{"sai":"往前面很远。","why":"sau kết cấu 往 + phương vị phải có động từ, không được để tính từ đứng một mình.","dung":"往前走很远。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["","前走，前面就是火车站。"],"dap":[["往"]]},{"kieu":"dien","phan":["你往","看，那个门开着呢。（bên phải）"],"dap":[["右"]]},{"kieu":"dien","phan":["请大家往","走。（bên trong）"],"dap":[["里"]]},{"kieu":"dien","phan":["到前面往","走就到我家了。（bên trái）"],"dap":[["左"]]},{"kieu":"dien","phan":["这个火车","北京开。"],"dap":[["往"]]},{"kieu":"dien","phan":["你往","走五分钟就到了。（phía trước）"],"dap":[["前"]]}],"huongDan":"Điền 往、前、左、右、里 vào chỗ trống","chon":["往","前","左","右","里"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["走","往","前"],"dap":["往前走。"]},{"kieu":"xep","manh":["就是","前面","火车站","往前走"],"dap":["往前走，前面就是火车站。"]},{"kieu":"xep","manh":["看","你","右","往"],"dap":["你往右看。"]},{"kieu":"xep","manh":["开","这个","往","火车","北京"],"dap":["这个火车往北京开。"]},{"kieu":"xep","manh":["走","请","往","大家","里"],"dap":["请大家往里走。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"请问，火车站怎么走？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["往前走。"],"goiY":"đi thẳng về phía trước"},{"kieu":"hoi","dong":[{"ai":"A","t":"你们的教室在哪儿？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["往前走，到前面往左走。"],"goiY":"đi về phía trước, đến đằng trước thì rẽ trái"},{"kieu":"dich","vn":"Mời mọi người đi vào phía trong.","dap":["请大家往里走。"]},{"kieu":"dich","vn":"Bạn nhìn sang bên phải, đó là nhà tôi.","dap":["你往右看，那是我家。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-14.html"] = [{"so":"14.1","ten":"动态助词“过”","tenVn":"Trợ từ động thái “过”","cauTruc":["Khẳng định: S + V + 过 + O","他们　来过　我家。","我　　看过　那个电影。","我　　去过　中国。","Phủ định: S + 没（有） + V + 过 + O","他们　没（有）来过　我家。","我　　没（有）看过　那个电影。","Nghi vấn: S + V + 过 + O + 吗？　/　S + V + 过 + O + 没有？","你看过那个电影吗？　/　你看过那个电影没有？","Phát âm: 过 ở đây đọc nhẹ **guo** (khinh thanh)."],"giaiThich":"Về cú pháp, “过” là trợ từ động thái, dính liền sau động từ, tân ngữ đặt sau 过; phủ định dùng 没（有）và 过 vẫn được giữ lại — đây là chỗ khác hẳn với 了 (phủ định thì 了 biến mất). Về ngữ nghĩa, “过” biểu thị KINH NGHIỆM: một việc từng xảy ra trong quá khứ, nay đã kết thúc, tiếng Việt là \"đã từng, từng“. So sánh: 我去过中国 (tôi từng đi Trung Quốc — nay đã về, chỉ kể kinh nghiệm) và 我去了中国 (tôi đã đi Trung Quốc — nhấn mạnh việc đi đã hoàn thành, có thể vẫn đang ở đó). Về ngữ dụng, ”过\" chuyên dùng khi kể trải nghiệm, khoe hoặc hỏi thăm sở thích, kinh nghiệm của nhau: 你看过那个电影吗？— câu mở đầu rất tự nhiên khi bắt chuyện với bạn Trung Quốc.","viDu":[{"zh":"他们来过我家。","py":"Tāmen láiguo wǒ jiā.","vn":"Họ từng đến nhà tôi."},{"zh":"我看过那个电影。","py":"Wǒ kànguo nàge diànyǐng.","vn":"Tôi đã xem bộ phim đó rồi."},{"zh":"我去过中国。","py":"Wǒ qùguo Zhōngguó.","vn":"Tôi từng đi Trung Quốc."},{"zh":"我没（有）看过那个电影。","py":"Wǒ méi(yǒu) kànguo nàge diànyǐng.","vn":"Tôi chưa từng xem bộ phim đó."},{"zh":"你看过那个电影吗？","py":"Nǐ kànguo nàge diànyǐng ma?","vn":"Bạn đã xem bộ phim đó chưa?"}],"loi":[{"sai":"我不看过那个电影。","why":"học sinh Việt quen dùng 不 cho mọi câu phủ định; nhưng việc đã/chưa xảy ra chỉ phủ định được bằng 没（有）.","dung":"我没（有）看过那个电影。"},{"sai":"我去了中国，那儿很漂亮。（ý muốn nói \"tôi từng đi Trung Quốc“）","why":"nhầm 过 với 了, chỉ nhớ ”quá khứ thì dùng 了\".","dung":"我去过中国，那儿很漂亮。"},{"sai":"我没看过了那个电影。","why":"dùng chồng 过 và 了; câu đã có 没 thì tuyệt đối không thêm 了 cuối câu.","dung":"我没（有）看过那个电影。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["我看","那个电影。"],"dap":[["过"]]},{"kieu":"dien","phan":["他们来","我家。"],"dap":[["过"]]},{"kieu":"dien","phan":["我","（有）看过那个电影。"],"dap":[["没"]]},{"kieu":"dien","phan":["你看过那个电影","？（có/chưa）"],"dap":[["没有"]]},{"kieu":"dien","phan":["我去","中国，那儿很漂亮。"],"dap":[["过"]]},{"kieu":"dien","phan":["昨天我去","他家。"],"dap":[["了"]]}],"huongDan":"Điền 过、了、没、没有 vào chỗ trống","chon":["过","了","没","没有"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"viet","yeuCau":"Viết dạng phủ định.","goc":"他们来过我家。","dap":["他们没来过我家。","他们没有来过我家。"]},{"kieu":"viet","yeuCau":"Viết dạng phủ định.","goc":"我看过那个电影。","dap":["我没看过那个电影。","我没有看过那个电影。"]},{"kieu":"viet","yeuCau":"Viết dạng câu hỏi có 吗.","goc":"我去过中国。","dap":["你去过中国吗？"]},{"kieu":"viet","yeuCau":"Viết dạng câu hỏi có 没有.","goc":"他坐过飞机。","dap":["他坐过飞机没有？"]},{"kieu":"viet","yeuCau":"Viết dạng phủ định.","goc":"我吃过中国菜。","dap":["我没吃过中国菜。","我没有吃过中国菜。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你看过那个电影吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我没看过。","我没有看过。"],"goiY":"chưa từng xem"},{"kieu":"hoi","dong":[{"ai":"A","o":true,"truoc":"","sau":""},{"ai":"B","t":"去过，我去过中国。"}],"dap":["你去过中国没有？","你去过中国吗？"],"goiY":"Bạn đã từng đi Trung Quốc chưa?"},{"kieu":"dich","vn":"Họ đã từng đến nhà tôi.","dap":["他们来过我家。"]},{"kieu":"dich","vn":"Tuy tôi chưa từng xem bộ phim đó, nhưng tôi biết nó rất hay.","dap":["虽然我没看过那个电影，但是我知道它很有意思。"]}]}]},{"so":"14.2","ten":"关联词“虽然……，但是……”","tenVn":"Cặp liên từ “虽然……，但是……”","cauTruc":["虽然 + Vế 1，但是 + Vế 2。","虽然　外面很冷，　但是　房间里很热。","Nếu hai vế CÙNG chủ ngữ, 虽然 có thể đứng sau chủ ngữ:","他　虽然　很忙，但是　每天都运动。","Lưu ý: 虽然 có thể lược bỏ, nhưng 但是 thì hầu như luôn phải giữ."],"giaiThich":"Về cú pháp, đây là cặp liên từ đi thành đôi: 虽然 mở vế nhượng bộ, 但是 mở vế chuyển ý; 虽然 đứng đầu câu (khi hai vế khác chủ ngữ) hoặc sau chủ ngữ (khi cùng chủ ngữ), còn 但是 luôn đứng đầu vế sau. Về ngữ nghĩa, cặp từ này diễn đạt quan hệ nhượng bộ – chuyển折: vế 1 thừa nhận một sự thật, vế 2 nêu điều ngược lại với dự đoán thông thường, tiếng Việt là \"tuy… nhưng…\". Điểm mấu chốt là hai vế PHẢI trái ngược nhau về lô-gic; nếu hai vế là quan hệ nguyên nhân – kết quả thì phải dùng 因为……所以…… chứ không phải 虽然……但是……. Về ngữ dụng, trọng tâm thông tin luôn nằm ở vế có 但是, nên khi nói các em hãy nhấn giọng ở vế sau; cặp từ này rất hay dùng để nêu nhận xét hai chiều, làm câu trả lời nghe chín chắn hơn hẳn.","viDu":[{"zh":"虽然外面很冷，但是房间里很热。","py":"Suīrán wàimiàn hěn lěng, dànshì fángjiān li hěn rè.","vn":"Tuy bên ngoài rất lạnh nhưng trong phòng lại rất nóng."},{"zh":"虽然汉字很难，但是我很喜欢写汉字。","py":"Suīrán Hànzì hěn nán, dànshì wǒ hěn xǐhuan xiě Hànzì.","vn":"Tuy chữ Hán rất khó nhưng tôi rất thích viết chữ Hán."},{"zh":"虽然是晴天，但是很冷。","py":"Suīrán shì qíngtiān, dànshì hěn lěng.","vn":"Tuy là trời nắng nhưng rất lạnh."},{"zh":"虽然这个电影很长，但是很有意思。","py":"Suīrán zhège diànyǐng hěn cháng, dànshì hěn yǒuyìsi.","vn":"Tuy bộ phim này rất dài nhưng rất thú vị."},{"zh":"虽然他很忙，但是每天都运动。","py":"Suīrán tā hěn máng, dànshì měi tiān dōu yùndòng.","vn":"Tuy anh ấy rất bận nhưng ngày nào cũng tập thể dục."}],"loi":[{"sai":"虽然外面很冷，房间里很热。","why":"tiếng Việt cho phép nói \"tuy ngoài trời lạnh, trong phòng lại nóng\" mà không cần \"nhưng\"; tiếng Hán đã dùng 虽然 thì bắt buộc có 但是 (hoặc 可是).","dung":"虽然外面很冷，但是房间里很热。"},{"sai":"虽然下雨了，但是我没去。","why":"hai vế không hề tương phản mà là nhân – quả, học sinh dùng nhầm khung nhượng bộ.","dung":"因为下雨了，所以我没去。"},{"sai":"他很忙虽然，但是每天都运动。","why":"đặt 虽然 sau vị ngữ theo trật tự tiếng Việt \"bận tuy\"; 虽然 chỉ đứng đầu câu hoặc ngay sau chủ ngữ.","dung":"他虽然很忙，但是每天都运动。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["","外面很冷，但是房间里很热。"],"dap":[["虽然"]]},{"kieu":"dien","phan":["虽然汉字很难，","我很喜欢写汉字。"],"dap":[["但是"]]},{"kieu":"dien","phan":["","是晴天，","很冷。"],"dap":[["虽然"],["但是"]]},{"kieu":"dien","phan":["虽然这个电影很长，","很有意思。"],"dap":[["但是"]]},{"kieu":"dien","phan":["","他很忙，但是每天都运动。"],"dap":[["虽然"]]},{"kieu":"dien","phan":["虽然我去过北京，","没去过上海。"],"dap":[["但是"]]}],"huongDan":"Điền 虽然 hoặc 但是 vào chỗ trống","chon":["虽然","但是"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"viet","yeuCau":"Dùng “虽然……，但是……” nối hai câu thành một câu","goc":"外面很冷。 / 房间里很热。","dap":["虽然外面很冷，但是房间里很热。"]},{"kieu":"viet","yeuCau":"Dùng “虽然……，但是……” nối hai câu thành một câu","goc":"汉字很难。 / 我很喜欢写汉字。","dap":["虽然汉字很难，但是我很喜欢写汉字。"]},{"kieu":"viet","yeuCau":"Dùng “虽然……，但是……” nối hai câu thành một câu","goc":"今天是晴天。 / 今天很冷。","dap":["虽然今天是晴天，但是很冷。"]},{"kieu":"viet","yeuCau":"Dùng “虽然……，但是……” nối hai câu thành một câu","goc":"那个电影我看过三次。 / 我还想看。","dap":["虽然那个电影我看过三次，但是我还想看。"]},{"kieu":"viet","yeuCau":"Dùng “虽然……，但是……” nối hai câu thành một câu","goc":"他很忙。 / 他每天都运动。","dap":["虽然他很忙，但是他每天都运动。"]}],"huongDan":"Dùng “虽然……，但是……” nối hai câu thành một câu"},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"今天天气怎么样？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["虽然是晴天，但是很冷。"],"goiY":"Tuy là trời nắng nhưng rất lạnh"},{"kieu":"hoi","dong":[{"ai":"A","t":"你喜欢写汉字吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["虽然汉字很难，但是我很喜欢写汉字。"],"goiY":"Tuy chữ Hán khó nhưng tôi rất thích viết"},{"kieu":"dich","vn":"Tuy bên ngoài rất lạnh nhưng trong phòng rất nóng.","dap":["虽然外面很冷，但是房间里很热。"]},{"kieu":"dich","vn":"Tuy tôi đã đi Bắc Kinh ba lần rồi nhưng vẫn còn muốn đi.","dap":["虽然我去过三次北京，但是还想去。"]}]}]},{"so":"14.3","ten":"动量补语“次”","tenVn":"Bổ ngữ động lượng “次”","cauTruc":["(1) Tân ngữ là SỰ VẬT: S + V + 过 + Số từ + 次 + O","他们　看过　三次　电影。","他们　坐过　一次　飞机。","(2) Tân ngữ là ĐỊA ĐIỂM: cả hai trật tự đều được","他们去过三次北京。 = 他们去过北京三次。","(3) Tân ngữ là ĐẠI TỪ NHÂN XƯNG: S + V + 过 + Đại từ + Số từ + 次 （BẮT BUỘC）","我们　找过　他　三次。"],"giaiThich":"Về cú pháp, “次” là lượng từ động lượng, luôn đi sau số từ tạo thành bổ ngữ động lượng đặt sau động từ; vị trí của nó so với tân ngữ phụ thuộc vào LOẠI tân ngữ — đây chính là điểm học sinh hay sai nhất. Quy tắc vàng các em phải thuộc lòng: tân ngữ là sự vật thì “次” đứng TRƯỚC tân ngữ; tân ngữ là đại từ nhân xưng (他、你、我们…) thì “次” bắt buộc đứng SAU đại từ; tân ngữ là địa danh thì linh hoạt cả hai. Về ngữ nghĩa, “次” đếm số lần hành động lặp lại, trả lời câu hỏi 几次 (mấy lần), thường đi kèm 过 để kể kinh nghiệm. Về ngữ dụng, khi trả lời câu hỏi 几次 người Trung Quốc thường lược bỏ tân ngữ cho gọn: 你看过几次？— 看过两次。","viDu":[{"zh":"他们看过三次电影。","py":"Tāmen kànguo sān cì diànyǐng.","vn":"Họ đã xem phim ba lần."},{"zh":"他们坐过一次飞机。","py":"Tāmen zuòguo yí cì fēijī.","vn":"Họ từng đi máy bay một lần."},{"zh":"他们去过三次北京。","py":"Tāmen qùguo sān cì Běijīng.","vn":"Họ đã đi Bắc Kinh ba lần."},{"zh":"他们去过北京三次。","py":"Tāmen qùguo Běijīng sān cì.","vn":"Họ đã đi Bắc Kinh ba lần."},{"zh":"我们找过他三次。","py":"Wǒmen zhǎoguo tā sān cì.","vn":"Chúng tôi đã tìm anh ấy ba lần."}],"loi":[{"sai":"我们找过三次他。","why":"học sinh áp máy móc quy tắc “次 đứng trước tân ngữ”; khi tân ngữ là đại từ nhân xưng thì 次 bắt buộc đứng sau đại từ.","dung":"我们找过他三次。"},{"sai":"他们看过电影三次。","why":"bê trật tự tiếng Việt \"xem phim ba lần\"; tân ngữ là sự vật thì 次 phải chen vào giữa động từ và tân ngữ.","dung":"他们看过三次电影。"},{"sai":"我们找他过三次。","why":"đặt 过 sau tân ngữ; 过 phải dính ngay sau động từ, trước cả tân ngữ lẫn bổ ngữ động lượng.","dung":"我们找过他三次。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"vitri","cau":"他们看过 A 电影 B 。","tu":"三次","chon":["A","B"],"dap":["A"],"giai":"他们看过三次电影。"},{"kieu":"vitri","cau":"他们坐过 A 飞机 B 。","tu":"一次","chon":["A","B"],"dap":["A"],"giai":"他们坐过一次飞机。"},{"kieu":"vitri","cau":"我们找过 A 他 B 。","tu":"三次","chon":["A","B"],"dap":["B"],"giai":"我们找过他三次。"},{"kieu":"vitri","cau":"他们去过 A 北京 B 。","tu":"三次","chon":["A","B"],"dap":["A","B"],"giai":"他们去过三次北京。= 他们去过北京三次。"},{"kieu":"vitri","cau":"我给他打过 A 电话 B 。","tu":"两次","chon":["A","B"],"dap":["A"],"giai":"我给他打过两次电话。"},{"kieu":"vitri","cau":"我看过 A 他 B 。","tu":"一次","chon":["A","B"],"dap":["B"],"giai":"我看过他一次。"}],"huongDan":"Đặt cụm từ trong ngoặc vào vị trí đúng (A hoặc B)"},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"xep","manh":["三次","看过","电影","他们"],"dap":["他们看过三次电影。"]},{"kieu":"xep","manh":["一次","坐过","飞机","他们"],"dap":["他们坐过一次飞机。"]},{"kieu":"xep","manh":["北京","去过","他们","三次"],"dap":["他们去过三次北京。","他们去过北京三次。"]},{"kieu":"xep","manh":["他","三次","找过","我们"],"dap":["我们找过他三次。"]},{"kieu":"xep","manh":["那个电影","我","两次","看过"],"dap":["我看过两次那个电影。","那个电影我看过两次。"]}]},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"你看过几次那个电影？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["我看过两次。"],"goiY":"hai lần"},{"kieu":"hoi","dong":[{"ai":"A","t":"你坐过飞机吗？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["坐过，我坐过一次飞机。"],"goiY":"từng ngồi, một lần"},{"kieu":"dich","vn":"Chúng tôi đã tìm anh ấy ba lần.","dap":["我们找过他三次。"]},{"kieu":"dich","vn":"Tuy tôi đã đi Bắc Kinh ba lần nhưng chưa từng đi tàu hỏa.","dap":["虽然我去过三次北京，但是没坐过火车。"]}]}]}];
window.NGU_PHAP_TAB["/lessons/bai-15.html"] = [{"so":"15.1","ten":"动作的状态“要……了”","tenVn":"Trạng thái sắp xảy ra “要/快要/快/就要……了”","cauTruc":["(1) 要 + V / Adj + 了　　　　　要下雨了。","(2) 快要 + V / Adj + 了　　　　火车快要来了。","(3) 快 + V / Adj + 了　　　　　新年快到了。","(4) 就要 + V / Adj + 了　　　　明天姐姐就要走了。","QUY TẮC QUAN TRỌNG: Khi trong câu CÓ trạng ngữ thời gian (明天、下个月、下个星期…) thì CHỈ được dùng 就要……了, KHÔNG dùng 快要……了.","下个月我们就要回国了。（✓）　下个月我们快要回国了。（✗）"],"giaiThich":"Về cú pháp, 要/快要/快/就要 là phó từ đặt trước động từ hoặc tính từ, còn 了 là trợ từ ngữ khí đóng cuối câu — hai đầu khung phải có đủ, thiếu 了 là câu chưa trọn. Về ngữ nghĩa, cả bốn dạng đều nói việc SẮP xảy ra trong thời gian ngắn tới đây, tiếng Việt là \"sắp… rồi\"; trong đó 就要……了 cho cảm giác gần hơn, gấp hơn 快要……了, và chỉ 就要……了 mới kết hợp được với trạng ngữ thời gian cụ thể. Các em nhớ mẹo này: hễ trong câu đã nêu rõ MỐC thời gian (明天、下个星期) thì tự động chọn 就要……了. Về ngữ dụng, kết cấu này dùng để báo tin, giục giã hoặc bày tỏ cảm xúc hồi hộp, tiếc nuối; đầu năm cuối năm người Trung Quốc rất hay nói 新年就要到了，时间过得真快！","viDu":[{"zh":"火车快要来了。","py":"Huǒchē kuàiyào lái le.","vn":"Tàu hỏa sắp đến rồi."},{"zh":"要下雨了。","py":"Yào xià yǔ le.","vn":"Sắp mưa rồi."},{"zh":"新的一年快要到了。","py":"Xīn de yì nián kuàiyào dào le.","vn":"Một năm mới sắp đến rồi."},{"zh":"下个月我们就要回国了。","py":"Xià ge yuè wǒmen jiù yào huí guó le.","vn":"Tháng sau chúng tôi sắp về nước rồi."},{"zh":"明天姐姐就要走了。","py":"Míngtiān jiějie jiù yào zǒu le.","vn":"Ngày mai chị gái sắp đi rồi."}],"loi":[{"sai":"明天姐姐快要走了。","why":"câu đã có trạng ngữ thời gian 明天 mà học sinh vẫn dùng 快要……了; 快要 không đi được với mốc thời gian cụ thể.","dung":"明天姐姐就要走了。"},{"sai":"外面就要下雨了。（không có trạng ngữ thời gian）","why":"học sinh dùng 就要 tùy tiện; khi không có mốc thời gian, theo giáo trình nên dùng 要/快要/快……了.","dung":"外面快要下雨了。"},{"sai":"火车快要来。","why":"quên 了 cuối câu vì tiếng Việt \"tàu sắp đến\" không cần từ nào tương ứng; khung này bắt buộc đóng bằng 了.","dung":"火车快要来了。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["火车","来了。"],"dap":[["快要","就要","要"]]},{"kieu":"dien","phan":["","下雨了，我们回家吧。"],"dap":[["要","快要","就要"]]},{"kieu":"dien","phan":["新的一年","到了。"],"dap":[["快要","就要","要"]]},{"kieu":"dien","phan":["下个月我们","回国了。"],"dap":[["就要"]]},{"kieu":"dien","phan":["明天姐姐","走了。"],"dap":[["就要"]]},{"kieu":"dien","phan":["下个星期我们","考试了。"],"dap":[["就要"]]}],"huongDan":"Điền 要、快要、就要 vào chỗ trống","chon":["要","快要","就要"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"viet","yeuCau":"Sửa câu sai hoặc viết lại câu cho đúng","goc":"明天姐姐快要走了。","dap":["明天姐姐就要走了。"]},{"kieu":"viet","yeuCau":"Sửa câu sai hoặc viết lại câu cho đúng","goc":"火车快要来。","dap":["火车快要来了。"]},{"kieu":"viet","yeuCau":"Sửa câu sai hoặc viết lại câu cho đúng","goc":"下个月我们快要回国了。","dap":["下个月我们就要回国了。"]},{"kieu":"viet","yeuCau":"thêm 就要……了","goc":"新年到了。","dap":["新年就要到了。"]},{"kieu":"viet","yeuCau":"Sửa câu sai hoặc viết lại câu cho đúng","goc":"要下雨。","dap":["要下雨了。"]}],"huongDan":"Sửa câu sai hoặc viết lại câu cho đúng"},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"我们什么时候考试？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["下个星期我们就要考试了。"],"goiY":"tuần sau chúng ta sắp thi rồi"},{"kieu":"hoi","dong":[{"ai":"A","t":"外面天气怎么样？"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["要下雨了。"],"goiY":"sắp mưa rồi"},{"kieu":"dich","vn":"Năm mới sắp đến rồi.","dap":["新年就要到了。"]},{"kieu":"dich","vn":"Tàu hỏa sắp đến rồi, chúng ta đi nhanh lên.","dap":["火车快要来了，我们快点儿走吧。"]}]}]},{"so":"15.2","ten":"“都……了”","tenVn":"Cấu trúc “都……了”","cauTruc":["都 + Cụm chỉ thời gian / tuổi tác / số lượng + 了","都　12点　了。","他　都　30岁　了。","都 + V + Cụm chỉ thời lượng + 了","都　等你　半天　了。","Thường đi kèm vế sau mang sắc thái trách móc: 都……了，怎么还没/还不……？","都十点了，爸爸怎么还没回来？"],"giaiThich":"Về cú pháp, 都 ở đây đứng trước cụm thời gian/tuổi tác/số lượng, cuối câu bắt buộc có 了; câu thường không có chủ ngữ (都十二点了) hoặc chủ ngữ là số ít (他都30岁了) — dấu hiệu cho thấy đây KHÔNG phải 都 \"đều“. Về ngữ nghĩa, 都 trong khung này tương đương 已经, nghĩa là ”đã… rồi“, nhấn mạnh rằng con số ấy đã vượt quá mức người nói mong đợi; 都十二点了 = ”đã mười hai giờ rồi cơ đấy“. Đây chính là chỗ học sinh Việt hay hiểu sai nhất: 都 ở đây tuyệt đối không dịch là ”đều\". Về ngữ dụng, khung này mang sắc thái cảm thán, sốt ruột hoặc trách nhẹ, nên hay dùng khi giục người khác, than thời gian trôi nhanh; vế sau thường có 还没/还不 để tăng sắc thái sốt ruột.","viDu":[{"zh":"都12点了。","py":"Dōu shí'èr diǎn le.","vn":"Đã mười hai giờ rồi."},{"zh":"他都30岁了。","py":"Tā dōu sānshí suì le.","vn":"Anh ấy đã ba mươi tuổi rồi."},{"zh":"都等你半天了。","py":"Dōu děng nǐ bàntiān le.","vn":"Đợi bạn cả buổi rồi đấy."},{"zh":"都十点了，爸爸怎么还没回来？","py":"Dōu shí diǎn le, bàba zěnme hái méi huílái?","vn":"Đã mười giờ rồi, sao bố vẫn chưa về?"},{"zh":"都十二点了，你怎么还不睡觉？","py":"Dōu shí'èr diǎn le, nǐ zěnme hái bú shuìjiào?","vn":"Đã mười hai giờ rồi, sao bạn vẫn chưa đi ngủ?"}],"loi":[{"sai":"我们都十二点了。","why":"hiểu 都 là \"đều\" nên thấy cần một chủ ngữ số nhiều đứng trước; thực ra 都 ở đây = 已经, câu không cần chủ ngữ.","dung":"都十二点了。"},{"sai":"都十点。","why":"quên 了 cuối câu vì tiếng Việt \"đã mười giờ\" nghe đã đủ; khung 都……了 bắt buộc đóng bằng 了.","dung":"都十点了。"},{"sai":"他都三十岁，还没工作。","why":"vẫn là lỗi thiếu 了, đồng thời vế sau thiếu 呢 làm câu cụt sắc thái trách móc.","dung":"他都三十岁了，还没工作呢。"}],"bt":[{"so":1,"tieuDe":"Chọn/điền từ thích hợp","cap":"Cơ học","cau":[{"kieu":"dien","phan":["","12点了，你怎么还不睡觉？"],"dap":[["都"]]},{"kieu":"dien","phan":["他都30","了。"],"dap":[["岁"]]},{"kieu":"dien","phan":["都等你半天","。"],"dap":[["了"]]},{"kieu":"dien","phan":["都十点了，爸爸怎么","没回来？"],"dap":[["还"]]},{"kieu":"dien","phan":["","九月了，天气还很热。"],"dap":[["都"]]},{"kieu":"dien","phan":["你","三十岁了，怎么还不工作？"],"dap":[["都"]]}],"huongDan":"Điền 都、了、岁、还 vào chỗ trống","chon":["都","了","岁","还"]},{"so":2,"tieuDe":"Sắp xếp trật tự từ / viết lại câu","cap":"Bán giao tiếp","cau":[{"kieu":"viet","yeuCau":"Viết lại các câu sau bằng cấu trúc “都……了”","goc":"现在是十二点。","dap":["都十二点了。"]},{"kieu":"viet","yeuCau":"Viết lại các câu sau bằng cấu trúc “都……了”","goc":"他三十岁。","dap":["他都三十岁了。"]},{"kieu":"viet","yeuCau":"Viết lại các câu sau bằng cấu trúc “都……了”","goc":"我等你半天。","dap":["都等你半天了。","我都等你半天了。"]},{"kieu":"viet","yeuCau":"Viết lại các câu sau bằng cấu trúc “都……了”","goc":"现在十点，爸爸还没回来。","dap":["都十点了，爸爸怎么还没回来？","都十点了，爸爸还没回来。"]},{"kieu":"viet","yeuCau":"Viết lại các câu sau bằng cấu trúc “都……了”","goc":"现在九月，天气还很热。","dap":["都九月了，天气还很热。"]}],"huongDan":"Viết lại các câu sau bằng cấu trúc “都……了”"},{"so":3,"tieuDe":"Hoàn thành hội thoại & dịch Việt–Trung","cap":"Giao tiếp","cau":[{"kieu":"hoi","dong":[{"ai":"A","t":"我们再玩儿一会儿吧。"},{"ai":"B","o":true,"truoc":"","sau":""}],"dap":["都十二点了，我们回家吧。"],"goiY":"đã mười hai giờ rồi, chúng ta về nhà thôi"},{"kieu":"hoi","dong":[{"ai":"A","t":"爸爸怎么还没回来？"},{"ai":"B","o":true,"truoc":"是啊，","sau":""}],"dap":["都十点了。"],"goiY":"đã mười giờ rồi"},{"kieu":"dich","vn":"Đợi bạn cả buổi rồi đấy.","dap":["都等你半天了。"]},{"kieu":"dich","vn":"Anh ấy đã ba mươi tuổi rồi mà vẫn chưa đi làm.","dap":["他都三十岁了，还没工作呢。"]}]}]}];
